// src/client/components/canvas/GroupCard.tsx
//
// Team 卡片：组标签 + 成员迷你列表（可滚动）+ 右下角拉伸把手。
// 成员节点为组内角色（data.groupId = 组 id），作为迷你卡片渲染于组内（见 GraphCanvas）；
// Team 卡片提供流程入/出与上下文入（团队整体任务，父代理读图理解，不注入成员），
// 跨组上下文连线走成员锚点；迷你卡仅显示输入按钮，保持列表紧凑。
//
// 为什么 Team 卡片没有运行状态徽标：Team 卡片是包裹层、不是执行主体（用户裁决 2026-10），
// 它不进入运行事实；运行状态只属于成员节点（每个成员各自有状态徽标）。

import { memo } from 'react'
import type { Dict } from '../../i18n.js'
import type { CanvasNode } from '../../studio/studio-state.js'
import { nodeSizeOf } from '../../lib/card-geometry.js'
import { statusLabelOf } from '../../lib/status-label.js'
import type { PortSide } from '../../../host/shared/graph-model.js'

interface GroupCardProps {
  node: CanvasNode
  copy: Dict
  members: Array<{ id: string; label: string; status: string | null; locked?: boolean; highlighted?: boolean; dimmed?: boolean }>
  selected: boolean
  /** 联动高亮（与角色节点同款语义：外部选择/定位聚焦到本卡）。 */
  highlighted?: boolean
  dimmed?: boolean
  /** 拖拽悬停目标（左栏角色卡拖入时高亮并提示「放开以入组」）。 */
  dropTarget: boolean
  /** Team 卡片自身运行中锁定（已完成/执行中）：锁角标 + 悬停提示。 */
  locked?: boolean
  lockHint?: string
  connectedHandles?: string
  onPointerDown(event: React.PointerEvent, id: string): void
  onHandlePointerDown(event: React.PointerEvent, id: string, handle: string): void
  onMemberSelect(id: string): void
  onResizeStart(event: React.PointerEvent, id: string, direction: string): void
}

/**
 * 以 memo 包住：父组件拖拽/平移/缩放等本地渲染态变化时，只要组卡输入（节点、成员列表、
 * 选中/高亮/锁定、回调引用）未变即不重渲染；成员列表由 GraphCanvas 以 useMemo 保持引用稳定。
 */
export const GroupCard = memo(function GroupCard({ node, copy, members, selected, highlighted, dimmed = false, dropTarget, locked, lockHint, connectedHandles, onPointerDown, onHandlePointerDown, onMemberSelect, onResizeStart }: GroupCardProps) {
  const size = nodeSizeOf(node)
  const portEl = (side: PortSide): React.ReactNode => {
    const input = side === 'left' || side === 'top'
    const available = input ? ['ctx-in', 'flow-in'] : ['flow-out']
    const connected = available.some(h => connectedHandles?.includes(`|${node.id}:${h}:${side}|`))
    return <span key={side} className={`wf-graph__handle is-side-${side} is-${input ? 'in' : 'out'}${connected ? ' is-connected' : ''}`}
      style={side === 'left' || side === 'right' ? { top: '50%', [side]: -6 } : { left: '50%', [side]: -6 }}
      data-handle={input ? 'flow-in' : 'flow-out'} data-handles={available.join(' ')} data-port-side={side}
      title={String(input ? copy.nodeKinds.input : copy.nodeKinds.output)}
      onPointerDown={event => onHandlePointerDown(event, node.id, input ? 'flow-in' : 'flow-out')} />
  }
  // 去重计数（历史数据可能残留重复 memberIds，避免计数虚高）
  const memberIds = [...new Set((node.data.memberIds as string[] | undefined) ?? [])]
  // Team 卡片提供流程入/出接点（居中；成员节点的上下文/数据库连线走成员自身接点）
  return (
    <div
      className={`wf-graph__node wf-group-node${dropTarget ? ' is-drop-target' : ''}${dimmed ? ' is-runtime-dimmed' : ''}`}
      data-wf-node-id={node.id}
      style={{ left: node.position.x, top: node.position.y, width: size.w, height: size.h }}
      onPointerDown={(event) => onPointerDown(event, node.id)}
    >
      <div className={`wf-node wf-node--group${selected ? ' is-selected' : ''}${highlighted ? ' is-highlighted' : ''}${dropTarget ? ' is-drop-target' : ''}${locked ? ' is-locked' : ''}`} title={locked ? lockHint : undefined}>
        <div className="wf-node__kind">
          <span>{String(copy.nodeKinds.group)}</span>
          {node.data.dynamic === true
            ? <span className="wf-hint">{`${String(copy.dynamicTeam)} · ${String(copy.dynamicTeamLimit)} ${Number(node.data.maxMembers ?? 4)}`}</span>
            : <span className="wf-hint">{`${memberIds.length} ${String(copy.groupMembers)}`}</span>}
          {locked ? <span className="wf-node__lock-badge" title={lockHint}>🔒</span> : null}
        </div>
        {dropTarget ? <div className="wf-group__drop-hint">{String(copy.groupDropHint)}</div> : null}
        <div className="wf-node__label">{String(node.data.label ?? copy.nodeKinds.group)}</div>
        <div className="wf-group__members">
          {members.length === 0
            ? <div className="wf-hint">{String(node.data.dynamic === true ? copy.dynamicTeamHint : copy.groupMemberHint)}</div>
            : members.map((member) => (
                <button
                  key={member.id}
                  type="button"
                  className={`wf-group__member${member.highlighted ? ' is-highlighted' : ''}${member.dimmed ? ' is-runtime-dimmed' : ''}`}
                  data-wf-node-id={member.id}
                  onPointerDown={(event) => { event.stopPropagation() }}
                  onClick={(event) => { event.stopPropagation(); onMemberSelect(member.id) }}
                >
                  <span className="wf-group__member-name">{member.label || member.id}</span>
                  {member.locked ? <span className="wf-node__lock-badge" title={lockHint}>🔒</span> : null}
                  {member.status ? (
                    <span className="wf-group__member-status">
                      <span className={`wf-status-dot is-${member.status}`} />
                      <span className="wf-hint">{statusLabelOf(copy, member.status)}</span>
                    </span>
                  ) : null}
                  {/* 组内成员仅数据库/上下文入点，无流程接点（流程由 Team 卡片承担）；
                      成员输出上下文可在连线侧栏配置，迷你卡保持紧凑 */}
                  <span
                    className={`wf-graph__handle is-in wf-graph__handle--target wf-graph__handle--mini wf-graph__handle--member-db-in${connectedHandles?.includes(`|${member.id}:db-in:left|`) ? ' is-connected' : ''}`}
                    data-handle="db-in"
                    title="db-in"
                    onPointerDown={(event) => { event.stopPropagation(); onHandlePointerDown(event, member.id, 'db-in') }}
                  />
                  <span
                    className={`wf-graph__handle is-in wf-graph__handle--target wf-graph__handle--mini wf-graph__handle--member-ctx-in${connectedHandles?.includes(`|${member.id}:ctx-in:left|`) ? ' is-connected' : ''}`}
                    data-handle="ctx-in"
                    title="ctx-in"
                    onPointerDown={(event) => { event.stopPropagation(); onHandlePointerDown(event, member.id, 'ctx-in') }}
                  />
                </button>
              ))}
        </div>
        {(['left', 'top', 'right', 'bottom'] as const).map(portEl)}
        <div
          className="wf-group__resize is-se"
          onPointerDown={(event) => onResizeStart(event, node.id, 'se')}
        />
      </div>
    </div>
  )
})
