// src/client/components/panels/inspector/subgraph-form.tsx
//
// 子图节点属性：名称、说明、内部结构概要和从已有工作流模板导入。
// 子图的内部图不做逐字段表单编辑——完整图在模板库中搭建后导入，避免在狭窄的
// 属性栏里复制一整套画布编辑器；展开按钮提供全屏只读预览。

import { useState } from 'react'
import type { WorkflowTemplate } from '../../../../host/shared/graph-model.js'
import type { Dict } from '../../../i18n.js'
import { Field } from '../form-field.js'
import { NameField } from './form-primitives.js'
import { ExpandableTextArea } from './text-expand.js'
import { defaultSubgraphGraph, importSubgraphFromTemplate, subgraphCompleteness, subgraphGraphOf } from '../../../lib/subgraph.js'

export function SubgraphForm({ data, copy, mode, flowTemplates, onPatch }: {
  data: Record<string, unknown>
  copy: Dict
  mode: 'mode1' | 'mode2'
  flowTemplates: WorkflowTemplate[]
  onPatch(patch: Record<string, unknown>): void
}) {
  const graph = subgraphGraphOf({ kind: 'subgraph', data })
  const completeness = subgraphCompleteness(graph)
  const candidates = flowTemplates.filter((template) => template.mode === mode)
  const [selected, setSelected] = useState(candidates[0]?.id ?? '')
  const [error, setError] = useState('')

  const importTemplate = (): void => {
    const template = candidates.find((item) => item.id === selected)
    if (!template) return
    try {
      onPatch({ graph: importSubgraphFromTemplate(template, mode), sourceTemplateId: template.id })
      setError('')
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : String(cause))
    }
  }

  return (
    <div>
      <h3>{copy.nodeKinds.subgraph}</h3>
      <NameField data={data} copy={copy} onPatch={onPatch} />
      <Field label={copy.subgraphDescription}>
        <ExpandableTextArea
          label={copy.subgraphDescription}
          value={data.description}
          placeholder={copy.subgraphDescriptionHint}
          minHeight={80}
          onChange={(value) => onPatch({ description: value })}
        />
      </Field>

      <Field label={copy.subgraphStructure}>
        <div className="wf-form-stack">
          <div className="wf-pathbox">
            <span className="wf-pathbox__label">{copy.subgraphNodeCount}</span>
            <span className="wf-pathbox__value">{graph?.nodes.length ?? 0}{graph ? ` · ${copy.subgraphLineCount} ${graph.lines.length}` : ''}</span>
          </div>
          {!completeness.ok
            ? <span className="wf-hint is-warning">{completeness.starts !== 1 ? copy.subgraphNoStart : copy.subgraphNoEnd}</span>
            : null}
          <span className="wf-hint">{copy.subgraphStructureHint}</span>
          <div className="wf-form-row">
            <select
              aria-label={copy.subgraphImportTemplate}
              value={selected}
              onChange={(event) => setSelected(event.target.value)}
              disabled={candidates.length === 0}
            >
              {candidates.length === 0
                ? <option value="">{copy.subgraphNoTemplates}</option>
                : candidates.map((template) => <option key={template.id} value={template.id}>{template.name || template.id}</option>)}
            </select>
            <button type="button" className="wf-btn" onClick={importTemplate} disabled={!selected}>
              {copy.subgraphImport}
            </button>
          </div>
          <span className="wf-hint">{copy.subgraphImportTemplateHint}</span>
          {/* 子图的内部起止结构可以重置；交互编辑请先在模板库中搭建，再导入 */}
          <div className="wf-form-row">
            <button type="button" className="wf-btn" onClick={() => onPatch({ graph: defaultSubgraphGraph(mode), sourceTemplateId: undefined })}>
              {copy.subgraphReset}
            </button>
          </div>
          {error ? <span className="wf-hint is-warning">{error}</span> : null}
        </div>
      </Field>
    </div>
  )
}
