// src/client/lib/run-status-map.ts
//
// 运行快照 → 画布视图投影：节点状态映射与「当前运行节点」高亮清单。
// 纯函数：只读快照，不读时钟与全局状态。

import type { RunSnapshot } from '../../host/shared/types.js'

export interface CanvasStatusNode {
  id: string
  kind: string
  data?: Record<string, unknown>
}

/** 子图内部节点在运行快照中的展开 id（必须与 host 的 subgraphChildIdPrefix 同源）。 */
function subgraphChildId(subgraphId: string, childId: string): string {
  return `${subgraphId}__${childId}`
}

function innerNodeIds(node: CanvasStatusNode): string[] {
  const graph = node.data?.graph as { nodes?: Array<{ id?: unknown }> } | undefined
  return (graph?.nodes ?? []).map((inner) => String(inner.id ?? '')).filter(Boolean).map((id) => subgraphChildId(node.id, id))
}

/**
 * 运行快照 → 节点状态映射（画布回显用）。
 * 传入画布节点时，把子图内部节点的状态聚合回折叠节点：running 优先，其次 fail，
 * 只有全部内部节点都产出后才显示 ok。这样折叠后的子图也能看到运行进度。
 */
export function runStatusMap(
  snapshot: RunSnapshot | null | undefined,
  nodes?: CanvasStatusNode[],
): Record<string, { status: string; attempts: number; outputSummary: string }> {
  const map: Record<string, { status: string; attempts: number; outputSummary: string }> = {}
  for (const node of snapshot?.nodes ?? []) {
    if (node?.nodeId) map[node.nodeId] = { status: node.status, attempts: node.attempts, outputSummary: node.outputSummary }
  }
  for (const node of nodes ?? []) {
    if (node.kind !== 'subgraph') continue
    const inner = innerNodeIds(node)
    if (inner.length === 0) continue
    const entries = inner.map((id) => map[id]).filter((entry): entry is { status: string; attempts: number; outputSummary: string } => entry !== undefined)
    if (entries.length === 0) continue
    const attempts = Math.max(...entries.map((entry) => entry.attempts))
    const outputSummary = entries.map((entry) => entry.outputSummary).filter(Boolean).join(' · ')
    if (entries.some((entry) => entry.status === 'running')) map[node.id] = { status: 'running', attempts, outputSummary }
    else if (entries.some((entry) => entry.status === 'fail')) map[node.id] = { status: 'fail', attempts, outputSummary }
    else if (inner.every((id) => map[id] !== undefined && ['ok', 'react-capped', 'armed'].includes(map[id].status))) map[node.id] = { status: 'ok', attempts, outputSummary }
  }
  return map
}

/** 运行中节点 id 列表（「当前运行节点高亮」；画布高亮数据源，防回环只写视图）。 */
export function runningNodeIds(
  snapshot: RunSnapshot | null | undefined,
  nodes?: CanvasStatusNode[],
): string[] {
  if (snapshot?.status !== 'running') return []
  const ids = (snapshot?.nodes ?? [])
    .filter((node) => node?.nodeId && node.status === 'running')
    .map((node) => node.nodeId as string)
  const set = new Set(ids)
  for (const node of nodes ?? []) {
    if (node.kind !== 'subgraph') continue
    if (innerNodeIds(node).some((id) => set.has(id))) set.add(node.id)
  }
  return [...set]
}
