// src/client/components/panels/inspector/node-forms.tsx
//
// 阶段 / Team / 虚拟节点表单。

import type { Dict } from '../../../i18n.js'
import { Field } from '../form-field.js'
import { NameField } from './form-primitives.js'
import { ExpandableTextArea } from './text-expand.js'

/** 阶段属性只读（无描述字段，无保存按钮）；名称由调用方按界面语言注入。 */
export function StageForm({ copy, nodeLabel }: { copy: Dict; nodeLabel: string }) {
  return (
    <div>
      <h3>{nodeLabel}</h3>
      <div className="wf-pathbox">
        <span className="wf-pathbox__label">{copy.label}</span>
        <span className="wf-pathbox__value">{nodeLabel}</span>
      </div>
      <span className="wf-hint">{copy.stageReadonlyHint}</span>
    </div>
  )
}

/** Team（名称/协作 Prompt/成员列表删除）。模板态无成员（成员在画布内拖入登记），隐藏成员区。 */
export function GroupForm({ data, copy, members, onPatch, onLoadMd, onRemoveMember, maxActiveSubagents = 8 }: {
  data: Record<string, unknown>
  copy: Dict
  members?: Array<{ id: string; label: string }>
  onPatch(patch: Record<string, unknown>): void
  onLoadMd(): void
  onRemoveMember(memberId: string): void
  /** Host-side live child-agent parallelism limit; used for the dynamic-team warning. */
  maxActiveSubagents?: number
}) {
  return (
    <div>
      <h3>{copy.nodeKinds.group}</h3>
      <NameField data={data} copy={copy} onPatch={onPatch} />
      <Field label={copy.collabPrompt}>
        <div className="wf-form-stack">
          <ExpandableTextArea
            label={copy.collabPrompt}
            value={data.collabPrompt}
            placeholder={copy.collabPromptHint}
            onChange={(value) => onPatch({ collabPrompt: value })}
          />
          <div className="wf-form-row">
            <button type="button" className="wf-btn" title={copy.loadMdTitle} onClick={onLoadMd}>{copy.loadMd}</button>
          </div>
        </div>
      </Field>
      <div className="wf-form-check wf-form-check--section">
        <input
          type="checkbox"
          className="wf-form-check__box"
          checked={data.dynamic === true}
          onChange={(event) => onPatch({ dynamic: event.target.checked, ...(event.target.checked ? {} : { memberRolePrompt: '' }) })}
        />
        <span title={String(copy.dynamicTeamHint)}>{String(copy.dynamicTeam)}</span>
      </div>
      {data.dynamic === true ? (
        <div className="wf-form-stack wf-dynamic-team-fields">
          <Field label={String(copy.dynamicTeamLimit)}>
            <input
              type="number"
              min={1}
              max={64}
              value={String(data.maxMembers ?? 4)}
              title={String(copy.dynamicTeamLimitHint)}
              onChange={(event) => onPatch({ maxMembers: Math.max(1, Math.min(64, Number(event.target.value) || 1)) })}
            />
          </Field>
          <Field label={String(copy.memberRoleTemplate)}>
            <ExpandableTextArea
              label={String(copy.memberRoleTemplate)}
              value={data.memberRolePrompt}
              placeholder={String(copy.memberRoleTemplateHint)}
              minHeight={220}
              onChange={(value) => onPatch({ memberRolePrompt: value })}
            />
          </Field>
          {Number(data.maxMembers ?? 4) > maxActiveSubagents ? (
            <span className="wf-hint wf-dynamic-team-warning">
              {String(copy.dynamicTeamLimitExceeds).replace('{max}', String(data.maxMembers ?? 4)).replace('{limit}', String(maxActiveSubagents))}
            </span>
          ) : null}
        </div>
      ) : null}
      {members !== undefined ? (
        <Field label={copy.groupMembers}>
          <div className="wf-check-list">
            {members.length === 0 ? (
              <span className="wf-hint">{copy.groupMemberHint}</span>
            ) : (
              members.map((member) => (
                <label key={member.id} className="wf-check-list__row">
                  <span>{member.label || member.id}</span>
                  <button type="button" className="wf-btn is-danger wf-btn--xs" onClick={() => onRemoveMember(member.id)}>✕</button>
                </label>
              ))
            )}
          </div>
        </Field>
      ) : null}
    </div>
  )
}

/**
 * 虚拟节点表单：引用主节点只读，另可编辑显示名（画布上替代节点种类名）。
 */
export function ProxyForm({ data, copy, onPatch, mainLabel }: {
  data: Record<string, unknown>
  copy: Dict
  onPatch(patch: Record<string, unknown>): void
  mainLabel: string
}) {
  return (
    <div>
      <h3>{copy.nodeKinds.proxy}</h3>
      <div className="wf-pathbox">
        <span className="wf-pathbox__label">{copy.proxyMainLabel}</span>
        <span className="wf-pathbox__value">{mainLabel || String(data.proxySourceId ?? '—')}</span>
      </div>
      <Field label={String(copy.proxyLabel)}>
        <input
          type="text"
          value={String(data.label ?? '')}
          placeholder={String(copy.proxyLabelHint)}
          onChange={(event) => onPatch({ label: event.target.value })}
        />
      </Field>
      <span className="wf-hint">{copy.proxyReadonlyHint}</span>
    </div>
  )
}
