// src/client/lib/compact-layout.ts

import { groupCardSizeOf, GROUP_MEMBER_LIST_TOP, GROUP_MEMBER_ROW_H } from './card-geometry.js'
import { layoutGraph, toLayoutInputs } from './layout.js'
import type { Line } from '../../host/shared/graph-model.js'
import type { LayoutBoxNode, LayoutLineLike } from './layout-fit.js'
import { forwardLayoutLines } from './layout-forward.js'

/** Keep clear authored hierarchies; arrange unfinished graphs left-to-right with vertical parallel branches. */
export function compactLayout<T extends LayoutBoxNode>(nodes: T[], lines: LayoutLineLike[]): T[] {
  const groups = new Map<string, T>()
  for (const node of nodes) if (node.kind === 'group') for (const id of (node.data?.memberIds as string[] | undefined) ?? []) groups.set(id, node)
  const visible = nodes.filter(n => !groups.has(n.id)), owner = (id: string): string => groups.get(id)?.id ?? id
  const flowLines = forwardLayoutLines(visible, lines, owner) as Line[]
  const byId = new Map(visible.map(n => [n.id, n]))
  const incomingCount = new Map<string, number>()
  for (const line of lines) incomingCount.set(owner(line.target), (incomingCount.get(owner(line.target)) ?? 0) + 1)
  const horizontalCount = flowLines.filter(line => (byId.get(owner(line.target))?.position.x ?? 0) > (byId.get(owner(line.source))?.position.x ?? 0) + 64).length
  const authored = horizontalCount >= flowLines.length * 0.8
    && visible.every(n => Number.isFinite(n.position?.x) && Number.isFinite(n.position?.y) && (n.position.x !== 0 || n.position.y !== 0))
    && visible.every((a, i) => visible.slice(i + 1).every(b => {
      const sa = groupCardSizeOf(a), sb = groupCardSizeOf(b)
      return a.position.x + sa.w <= b.position.x || b.position.x + sb.w <= a.position.x || a.position.y + sa.h <= b.position.y || b.position.y + sb.h <= a.position.y
    }))
    && flowLines.every(line => {
      const source = byId.get(owner(line.source)), target = byId.get(owner(line.target))
      if (!source || !target) return true
      const size = groupCardSizeOf(source)
      const pressure = incomingCount.get(target.id) ?? 0
      const gap = pressure >= 5 ? Math.min(224, 96 + pressure * 10) : 64
      return target.position.x >= source.position.x + size.w + gap
        || (Math.abs(target.position.x - source.position.x) < 48 && target.position.y >= source.position.y + size.h + 8)
    })
    && lines.every(line => {
      const source = byId.get(owner(line.source)), target = byId.get(owner(line.target))
      if (!source || !target || (source.kind !== 'task' && source.kind !== 'database')) return true
      const gap = target.position.y - source.position.y - groupCardSizeOf(source).h
      return Math.abs(source.position.x - target.position.x) >= 48 || gap < 0 || gap >= 64
    })
  // Rerouting a clear diagram must preserve the author's columns, branch order and spacing.
  if (authored) return nodes

  const participating = new Set(flowLines.flatMap(l => [owner(l.source), owner(l.target)]))
  const base = layoutGraph(toLayoutInputs(nodes, groupCardSizeOf), flowLines)
  const rankOf = new Map<string, number>()
  const main = new Map<number, T[]>(), headers = new Map<number, T[]>(), footers = new Map<number, T[]>()
  const add = (columns: Map<number, T[]>, rank: number, node: T): void => {
    columns.set(rank, [...(columns.get(rank) ?? []), node]); rankOf.set(node.id, rank)
  }
  for (const node of visible.filter(n => participating.has(n.id))) add(main, base.colOf.get(node.id) ?? 0, node)
  const support = visible.filter(n => !participating.has(n.id))
  for (const node of support.filter(n => n.kind === 'task' || n.kind === 'database')) {
    const linked = lines.filter(l => l.source === node.id && rankOf.has(owner(l.target)))
    // Phase-specific task cards stay near their phase; their additional Leader copy must not stack every task at the left.
    const phaseTargets = linked.filter(line => byId.get(owner(line.target))?.kind !== 'parent')
    const targets = (phaseTargets.length ? phaseTargets : linked).map(line => rankOf.get(owner(line.target))!)
    add(headers, targets.length ? Math.min(...targets) - 1 : -1, node)
  }
  for (const node of support.filter(n => n.kind !== 'task' && n.kind !== 'database')) {
    const incoming = lines.filter(l => owner(l.target) === node.id).flatMap(l => rankOf.has(owner(l.source)) ? [rankOf.get(owner(l.source))!] : [])
    const rank = incoming.length ? Math.min(...incoming) + 1 : 0
    const reviewOnly = lines.some(line => owner(line.target) === node.id && line.sourceHandle === 'flow-out')
    add(node.kind === 'parent' ? headers : reviewOnly ? footers : main, rank, node)
  }
  for (const column of main.values()) column.sort((a, b) => (base.positions.get(a.id)?.y ?? 0) - (base.positions.get(b.id)?.y ?? 0) || a.id.localeCompare(b.id))
  const ranks = [...new Set([...main.keys(), ...headers.keys(), ...footers.keys()])].sort((a, b) => a - b)
  const height = (column: T[], gap: number): number => column.reduce((sum, node) => sum + groupCardSizeOf(node).h, 0) + Math.max(0, column.length - 1) * gap
  const mainHeight = Math.max(0, ...[...main.values()].map(column => height(column, 56)))
  const headerHeight = Math.max(0, ...[...headers.values()].map(column => height(column, 80)))
  const axis = 60 + headerHeight + (headerHeight ? 80 : 0) + mainHeight / 2
  const poses = new Map<string, { x: number; y: number }>()
  let left = 70
  for (const [columnIndex, rank] of ranks.entries()) {
    const flow = main.get(rank) ?? [], data = headers.get(rank) ?? [], review = footers.get(rank) ?? [], column = [...flow, ...data, ...review]
    const width = Math.max(...column.map(n => groupCardSizeOf(n).w))
    let top = 60
    for (const node of data) {
      const size = groupCardSizeOf(node)
      poses.set(node.id, { x: left + (width - size.w) / 2, y: top }); top += size.h + 80
    }
    top = axis - height(flow, 56) / 2
    for (const node of flow) {
      const size = groupCardSizeOf(node)
      poses.set(node.id, { x: left + (width - size.w) / 2, y: top }); top += size.h + 56
    }
    // Recovery and human-decision cards sit below the success path without nudging its centerline.
    top = axis + height(flow, 56) / 2 + 56
    for (const node of review) {
      const size = groupCardSizeOf(node)
      poses.set(node.id, { x: left + (width - size.w) / 2, y: top }); top += size.h + 56
    }
    const nextColumn = [...(main.get(ranks[columnIndex + 1]) ?? []), ...(headers.get(ranks[columnIndex + 1]) ?? []), ...(footers.get(ranks[columnIndex + 1]) ?? [])]
    const fan = Math.max(0, ...column.map(n => lines.filter(l => owner(l.source) === n.id || owner(l.target) === n.id).length), ...nextColumn.map(n => incomingCount.get(n.id) ?? 0))
    left += width + Math.min(224, 96 + fan * 10)
  }
  return nodes.map(node => {
    const group = groups.get(node.id)
    if (group) {
      const pose = poses.get(group.id), index = ((group.data?.memberIds as string[]) ?? []).indexOf(node.id)
      return pose ? { ...node, position: { x: pose.x + 20, y: pose.y + GROUP_MEMBER_LIST_TOP + index * GROUP_MEMBER_ROW_H } } : node
    }
    const pose = poses.get(node.id)
    if (!pose) return node
    return { ...node, position: { x: Math.round(pose.x), y: Number(pose.y.toFixed(2)) }, data: { ...node.data, ...(node.kind === 'group' ? { size: groupCardSizeOf(node) } : {}) } }
  })
}
