// src/client/components/canvas/use-edge-routes.ts

import { useEffect, useMemo, useRef, useState } from 'react'
import type { CanvasEdge, CanvasNode } from '../../lib/canvas-model.js'
import type { LineLabelCopy } from '../../lib/graph-edges.js'
import type { OrthogonalRoute } from '../../lib/orthogonal-routing.js'
import { edgeRoutingScene, routedEdgeGeometry } from './geometry.js'
import type { MemberGroupIndex } from './geometry.js'
import { rebaseRoute } from '../../lib/route-rebase.js'

declare const __WF_ROUTING_WORKER_SOURCE__: string

/** Keep routing off the pointer/render thread; coalesce requests and discard obsolete graph results. */
export function useEdgeRoutes(edges: CanvasEdge[], byId: Map<string, CanvasNode>, members: MemberGroupIndex, labels: LineLabelCopy, documentKey = '', dragging = false, routingRevision = 0): { routes: Map<string, OrthogonalRoute>; connectedPorts: string[]; isRouting: boolean } {
  const enabled = typeof Worker !== 'undefined' && typeof __WF_ROUTING_WORKER_SOURCE__ === 'string'
  const [result, setResult] = useState<{ routes: Map<string, OrthogonalRoute>; documentKey: string; scene: ReturnType<typeof edgeRoutingScene> } | null>(null)
  const [failed, setFailed] = useState(false)
  const workerRef = useRef<Worker | null>(null), revision = useRef(0), active = useRef(false)
  const latest = useRef<{ revision: number; documentKey: string; routingRevision: number; scene: ReturnType<typeof edgeRoutingScene> } | null>(null)
  const sent = useRef<typeof latest.current>(null)
  const synchronous = useRef(new Map<string, OrthogonalRoute>())
  const synchronousKey = useRef({ documentKey, routingRevision })
  const emptyRoutes = useRef(new Map<string, OrthogonalRoute>())
  const displayedRef = useRef(emptyRoutes.current)
  const idleScene = useRef<ReturnType<typeof edgeRoutingScene> | null>(null)
  const draggingRef = useRef(dragging); draggingRef.current = dragging
  const routes = result?.documentKey === documentKey ? result.routes : emptyRoutes.current
  const interaction = useMemo(() => dragging ? { routes: displayedRef.current, scene: idleScene.current } : null, [dragging, documentKey])
  const routingEdges = useMemo(() => {
    if (!interaction?.scene) return edges
    const inputs = new Map(interaction.scene.inputs.map(i => [i.id, i]))
    return edges.map(e => { const i = inputs.get(e.id); return i ? { ...e, appearance: { ...e.appearance, sourceSide: i.startAxis === 1 ? 'bottom' as const : 'right' as const, targetSide: i.endAxis === 1 ? 'top' as const : 'left' as const } } : e })
  }, [edges, interaction])
  const scene = useMemo(() => edgeRoutingScene(routingEdges, byId, members, labels), [routingEdges, byId, members, labels.pass, labels.fail, labels.content, routingRevision])
  if (!dragging) idleScene.current = scene
  const sendLatest = (): void => {
    if (!draggingRef.current && !active.current && latest.current && workerRef.current) {
      active.current = true
      sent.current = latest.current
      workerRef.current.postMessage({ revision: latest.current.revision, documentKey: latest.current.documentKey, routingRevision: latest.current.routingRevision, ...latest.current.scene })
    }
  }
  useEffect(() => {
    if (!enabled) return
    let alive = true
    const url = URL.createObjectURL(new Blob([__WF_ROUTING_WORKER_SOURCE__], { type: 'text/javascript' }))
    try {
      const worker = new Worker(url, { type: 'module' }); workerRef.current = worker
      worker.onmessage = (event: MessageEvent<{ revision: number; documentKey: string; routes?: Array<[string, OrthogonalRoute]>; error?: string }>) => {
        if (!alive) return
        active.current = false
        if (event.data.error) { setFailed(true); worker.terminate(); workerRef.current = null; return }
        if (event.data.documentKey === latest.current?.documentKey && event.data.routes && sent.current?.revision === event.data.revision && sent.current.routingRevision === latest.current.routingRevision) setResult({ routes: new Map(event.data.routes), documentKey: event.data.documentKey, scene: sent.current.scene })
        if (latest.current && latest.current.revision > event.data.revision) sendLatest()
      }
      worker.onerror = () => { if (alive) { setFailed(true); worker.terminate(); workerRef.current = null; active.current = false } }
      sendLatest()
    } catch { setFailed(true) }
    return () => { alive = false; workerRef.current?.terminate(); workerRef.current = null; active.current = false; URL.revokeObjectURL(url) }
  }, [enabled])
  useEffect(() => {
    latest.current = { revision: ++revision.current, scene, documentKey, routingRevision }
    sendLatest()
  }, [scene, documentKey, dragging, routingRevision])
  const displayed = useMemo(() => {
    if (enabled && !failed) {
      const base = interaction?.routes ?? routes
      const current = new Map(base)
      // Follow current ports immediately while a coalesced worker request is in flight.
      for (const input of scene.inputs) {
        const existing = base.get(input.id)
        if (existing?.points[0].x === input.start.x && existing.points[0].y === input.start.y && existing.points.at(-1)!.x === input.end.x && existing.points.at(-1)!.y === input.end.y) continue
        if (existing) { current.set(input.id, rebaseRoute(existing, input)); continue }
        const a = { x: input.start.x + (input.startAxis === 1 ? 0 : 32), y: input.start.y + (input.startAxis === 1 ? 32 : 0) }
        const b = { x: input.end.x - (input.endAxis === 1 ? 0 : 32), y: input.end.y - (input.endAxis === 1 ? 32 : 0) }
        const points = [input.start, a, ...(input.startAxis === 1 && input.endAxis === 1 ? [{ x: a.x, y: (a.y + b.y) / 2 }, { x: b.x, y: (a.y + b.y) / 2 }] : input.startAxis === 1 ? [{ x: a.x, y: b.y }] : input.endAxis === 1 ? [{ x: b.x, y: a.y }] : [{ x: (a.x + b.x) / 2, y: a.y }, { x: (a.x + b.x) / 2, y: b.y }]), b, input.end]
        current.set(input.id, { points, path: '', label: { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }, labelWidth: 0 })
      }
      return current
    }
    // Environments without workers retain the same routing rules and incremental cache.
    if (synchronousKey.current.documentKey !== documentKey || synchronousKey.current.routingRevision !== routingRevision) {
      synchronous.current = new Map()
      synchronousKey.current = { documentKey, routingRevision }
    }
    const next = routedEdgeGeometry(edges, byId, members, labels, synchronous.current)
    synchronous.current = next
    return next
  }, [enabled, failed, routes, scene, edges, byId, members, labels.pass, labels.fail, labels.content, interaction, documentKey, routingRevision])
  displayedRef.current = displayed
  return { routes: displayed, connectedPorts: scene.connectedPorts, isRouting: enabled && !failed && (result?.scene !== scene || result.documentKey !== documentKey) }
}
