// src/client/components/canvas/EdgeEditToolbar.tsx

import type { Dict } from '../../i18n.js'
import type { LineAppearance } from '../../../host/shared/graph-model.js'

export function EdgeEditToolbar({ value, x, y, copy, onChange, onClose, onDelete }: { value: LineAppearance; x: number; y: number; copy: Dict; onChange(patch: LineAppearance): void; onClose?(): void; onDelete?(): void }) {
  return <div className="wf-edge-toolbar" role="toolbar" aria-label={String(copy.editConnection)} style={{ left: x, top: y }} onPointerDown={event => event.stopPropagation()}>
    <div className="wf-edge-toolbar__types" role="group" aria-label={String(copy.connectionStyle)}>
      <button type="button" aria-pressed={(value.type ?? 'rounded') === 'rounded'} onClick={() => onChange({ type: 'rounded' })}>{copy.roundedConnection}</button>
      <button type="button" aria-pressed={value.type === 'bezier'} onClick={() => onChange({ type: 'bezier' })}>{copy.bezierConnection}</button>
    </div>
    <button type="button" onClick={() => onChange({ waypoints: [], anchorMode: 'auto', sourceSide: undefined, targetSide: undefined })}>{copy.resetConnection}</button>
    {onDelete ? <button type="button" onClick={onDelete}>{copy.inspectorDelete}</button> : null}
    <button type="button" className="wf-edge-toolbar__close" aria-label={String(copy.closeConnection)} onClick={onClose}>×</button>
    <span>{copy.dragConnectionHint}</span>
  </div>
}
