// src/client/lib/edge-segment.ts

import type { RoutePoint } from './orthogonal-routing.js'

export interface SegmentDrag {
  waypoints: RoutePoint[]
  index: number
  axis: 'x' | 'y'
}

/** Interior straight sections translate along their normal, leaving terminal anchors attached. */
export function edgeSegmentDrag(points: RoutePoint[], index: number): SegmentDrag | null {
  if (index < 0 || index + 1 >= points.length) return null
  let a = points[index], b = points[index + 1]
  if (a.x !== b.x && a.y !== b.y) return null
  const dx = Math.sign(b.x - a.x), dy = Math.sign(b.y - a.y)
  if (index === 0) a = { x: a.x + dx * 32, y: a.y + dy * 32 }
  if (index === points.length - 2) b = { x: b.x - dx * 32, y: b.y - dy * 32 }
  if ((b.x - a.x) * dx + (b.y - a.y) * dy <= 0) return null
  if (Math.hypot(a.x - b.x, a.y - b.y) < 48) return null
  const waypoints = points.slice(1, -1).map(p => ({ ...p }))
  if (index === 0) waypoints.unshift(a)
  if (index === points.length - 2) waypoints.push(b)
  return { waypoints, index: Math.max(0, index - 1), axis: a.y === b.y ? 'y' : 'x' }
}

export function translateEdgeSegment(drag: SegmentDrag, delta: RoutePoint): RoutePoint[] {
  return drag.waypoints.map((p, index) => index === drag.index || index === drag.index + 1
    ? { ...p, [drag.axis]: Math.round(p[drag.axis] + delta[drag.axis]) }
    : { ...p })
}
