// src/client/lib/graph-handles.ts
//
// 连接点表与阶段节点标签（纯数据 + 纯函数）：节点种类 → 可用入/出连接点，
// 以及阶段节点（启动/结束/暂停）在两种模式下的显示名与模板清单。
// 连接点表是 Host graph/model.ts 的客户端镜像（渲染与本地校验共用）。

import type { NodeKind } from '../../host/shared/graph-model.js'

export type HandleSpec = { inputs: string[]; outputs: string[] }

// Physical sockets share these channels; purpose is chosen when drawing or editing an edge.
export const HANDLES: Record<string, HandleSpec> = {
  parent: { inputs: ['db-in', 'ctx-in', 'flow-in'], outputs: ['ctx-out', 'flow-out'] },
  agent: { inputs: ['db-in', 'ctx-in', 'flow-in'], outputs: ['ctx-out', 'flow-out'] },
  proxy: { inputs: ['db-in', 'ctx-in', 'flow-in'], outputs: ['ctx-out', 'flow-out'] },
  task: { inputs: [], outputs: ['ctx-out'] },
  step: { inputs: ['flow-in'], outputs: ['flow-out'] },
  database: { inputs: [], outputs: ['db-out'] },
  // 输入/输出节点仅保留一个流程连接点（连接点多了，应当只有一个；
  // 外部问题已自动注入输入节点，流式返回不依赖输出节点 ctx 连线）
  start: { inputs: [], outputs: ['flow-out'] },
  end: { inputs: ['flow-in'], outputs: [] },
  pause: { inputs: ['flow-in'], outputs: ['flow-out'] },
  // ctx-in 表示「团队整体任务」：由父代理读图理解，不注入成员；flow-in 仍排在末位，
  // 使省略 handle 的默认入点保持为 flow-in（不得因数组顺序误连上下文通道）。
  group: { inputs: ['ctx-in', 'flow-in'], outputs: ['flow-out'] },
  subgraph: { inputs: ['flow-in'], outputs: ['flow-out'] },
}

export interface StageLabelCopy {
  start: string
  end: string
  pause: string
  input: string
  output: string
}

/** Stage labels are injected by UI callers so this pure graph helper stays locale-agnostic. */
function stageLabels(mode: string, copy: StageLabelCopy): { start: string; end: string; pause: string } {
  const isMode2 = mode === 'mode2'
  return {
    start: isMode2 ? copy.input : copy.start,
    end: isMode2 ? copy.output : copy.end,
    pause: copy.pause,
  }
}

/** 单个阶段节点在当前模式与界面语言下的显示名（存储值仍是中文规范值）。 */
export function stageNodeLabelOf(
  mode: string,
  kind: 'start' | 'end' | 'pause',
  copy: StageLabelCopy,
): string {
  if (kind === 'pause') return copy.pause
  return stageLabels(mode, copy)[kind]
}

/** Stage nodes available in each mode (mode 2 has no pause node). */
export function stageTemplateKinds(mode: string, copy: StageLabelCopy): Array<{ kind: NodeKind; label: string }> {
  const labels = stageLabels(mode, copy)
  const out: Array<{ kind: NodeKind; label: string }> = [
    { kind: 'start', label: labels.start },
    { kind: 'end', label: labels.end },
  ]
  if (mode !== 'mode2') out.push({ kind: 'pause', label: labels.pause })
  return out
}

export function defaultOutputHandle(kind: string): string {
  const def = HANDLES[kind] ?? HANDLES.agent
  return def.outputs[def.outputs.length - 1] ?? 'flow-out'
}

export function defaultInputHandle(kind: string): string {
  const def = HANDLES[kind] ?? HANDLES.agent
  return def.inputs[def.inputs.length - 1] ?? 'flow-in'
}
