// src/client/lib/node-collision.ts

import type { RouteBox, RoutePoint } from './orthogonal-routing.js'

function collides(a: RouteBox, b: RouteBox, gap: number): boolean {
  return a.id !== b.id && a.x < b.x + b.w + gap && a.x + a.w + gap > b.x && a.y < b.y + b.h + gap && a.y + a.h + gap > b.y
}

/** Align near-matching flow centers instead of introducing tiny orthogonal steps. */
export function snapConnectedCenter(box: RouteBox, neighbors: RouteBox[], tolerance = 12): RoutePoint {
  let x = box.x, y = box.y, nearestX = tolerance + 1, nearestY = tolerance + 1
  for (const neighbor of neighbors) {
    const dx = neighbor.x + neighbor.w / 2 - box.x - box.w / 2
    const dy = neighbor.y + neighbor.h / 2 - box.y - box.h / 2
    if (Math.abs(dx) < nearestX && Math.abs(dy) > (box.h + neighbor.h) / 2) { x = box.x + dx; nearestX = Math.abs(dx) }
    if (Math.abs(dy) < nearestY && Math.abs(dx) > (box.w + neighbor.w) / 2) { y = box.y + dy; nearestY = Math.abs(dy) }
  }
  return { x, y }
}

/** Project a dragged card to the nearest free boundary, preserving the previous position if surrounded. */
export function constrainNodePosition(box: RouteBox, obstacles: RouteBox[], previous: RoutePoint, gap = 36): RoutePoint {
  const hits = obstacles.filter(b => collides(box, b, gap))
  if (!hits.length) return { x: box.x, y: box.y }
  const candidates = hits.flatMap(b => [
    { x: b.x - box.w - gap, y: box.y }, { x: b.x + b.w + gap, y: box.y },
    { x: box.x, y: b.y - box.h - gap }, { x: box.x, y: b.y + b.h + gap },
  ]).sort((a, b) => (a.x - box.x) ** 2 + (a.y - box.y) ** 2 - (b.x - box.x) ** 2 - (b.y - box.y) ** 2)
  return candidates.find(p => !obstacles.some(b => collides({ ...box, ...p }, b, gap))) ?? previous
}

/** Newly created cards have no previous safe position: search outward instead of stacking them. */
export function vacantNodePosition(box: RouteBox, obstacles: RouteBox[], gap = 36): RoutePoint {
  const nearest = constrainNodePosition(box, obstacles, box, gap)
  if (!obstacles.some(obstacle => collides({ ...box, ...nearest }, obstacle, gap))) return nearest
  const stepX = box.w + gap, stepY = box.h + gap
  for (let radius = 1; radius <= Math.ceil(Math.sqrt(obstacles.length + 1)) + 2; radius++) {
    const candidates: RoutePoint[] = []
    for (let x = -radius; x <= radius; x++) for (let y = -radius; y <= radius; y++) {
      if (Math.abs(x) === radius || Math.abs(y) === radius) candidates.push({ x: box.x + x * stepX, y: box.y + y * stepY })
    }
    candidates.sort((a, b) => Math.hypot(a.x - box.x, a.y - box.y) - Math.hypot(b.x - box.x, b.y - box.y))
    const free = candidates.find(point => !obstacles.some(obstacle => collides({ ...box, ...point }, obstacle, gap)))
    if (free) return free
  }
  return { x: Math.max(box.x, ...obstacles.map(obstacle => obstacle.x + obstacle.w)) + gap, y: box.y }
}
