// src/client/components/canvas/FlowNode.tsx
//
// 画布节点卡片：角色（父/子代理）/ 任务 / 数据库 / 阶段 / 虚拟节点。
// 运行状态徽标（pending/running/ok/fail）回显；虚拟节点虚线边框 + 「↻ 引用」角标。
//
// 渲染约束：
//   - 角色卡元信息两行：模型：<model> / 组合：<模式或组合名>；
//   - 任务节点卡：显示任务描述（超两行省略）；
//   - 虚拟节点「↻ 引用」徽标只渲染一处；
//   - 输入/输出节点各只保留一个连接点（模式二：输入=flow-out、输出=flow-in）；
//   - 角色卡输出端点同时承载流程与上下文，连线用途独立于曲线形状；
//   - 四侧端口居中，同侧语义通道共用物理端点；未连接端口仅在编辑交互中显示。

import { memo } from 'react'
import type { Dict } from '../../i18n.js'
import type { CanvasNode } from '../../studio/studio-state.js'
import { HANDLES } from '../../lib/graph-handles.js'
import { nodeSizeOf } from '../../lib/card-geometry.js'
import { statusLabelOf } from '../../lib/status-label.js'

interface FlowNodeProps {
  node: CanvasNode
  copy: Dict & { modeName(id: string | null | undefined): string }
  mode: 'mode1' | 'mode2'
  selected: boolean
  highlighted: boolean
  dimmed?: boolean
  dragging: boolean
  runStatus: { status: string; attempts: number } | null
  /** 运行中锁定（已完成/执行中）：显示锁角标 + 悬停提示；不影响拖动移动。 */
  locked?: boolean
  /** 锁定时显示的悬停说明（已完成/执行中文案不同）。 */
  lockHint?: string
  /** P4：该节点是最近一次**父代理补丁**（origin='agent'）改动的节点 → 显示「AI 调整」角标。 */
  agentPatched?: boolean
  connectedHandles?: string
  onPointerDown(event: React.PointerEvent, id: string): void
  onHandlePointerDown(event: React.PointerEvent, id: string, handle: string): void
  /** 子图节点：点击卡片上的展开按钮，打开全屏预览。 */
  onOpenSubgraph?(id: string): void
}

/**
 * 连接点（按模式裁剪：输入/输出节点仅保留流程连接点；
 * 接点方向固定为左上输入、右下输出）。
 */
function nodeHandles(kind: string, mode: 'mode1' | 'mode2'): { left: string[]; right: string[] } {
  const def = HANDLES[kind] ?? HANDLES.agent
  // 启动/输入：仅右出 flow-out；结束/输出：仅左入 flow-in（原 ctx 连接点裁剪，
  // 外部问题已自动注入输入节点产出，流式返回亦不依赖输出节点 ctx-in 连线）
  if (kind === 'start') return { left: [], right: ['flow-out'] }
  if (kind === 'end') return { left: ['flow-in'], right: [] }
  const inputs = (def.inputs ?? []).filter((handle) => !(mode === 'mode1' && kind === 'end' && handle === 'ctx-in'))
  const outputs = def.outputs ?? []
  // 左上输入，右下输出；语义通道由同一个物理接点承载。
  const left = [...inputs].reverse()
  const right = [...outputs].reverse()
  return { left, right }
}

/** 截断文本（按字符数；中文友好）。 */
function clip(text: string, limit: number): string {
  const value = String(text ?? '')
  return value.length > limit ? `${value.slice(0, limit)}…` : value
}

/** 节点元信息行（每行独立渲染；角色卡为「模型 / 组合」两行）。 */
function metaLinesOf(node: CanvasNode, copy: Dict & { modeName(id: string | null | undefined): string }): string[] {
  const kind = node.kind
  const data = node.data
  const out: string[] = []
  if (kind === 'proxy') {
    // 虚拟节点：不在此处重复渲染「↻ 引用」徽标（label 行已有）
    return out
  }
  if (kind === 'parent' || kind === 'agent') {
    // 格式：模型：deepseek（换行）组合：（显示选择的模式或组合）
    const modelLabel = String(copy.nodeMetaModel)
    const presetLabel = String(copy.nodeMetaPreset)
    out.push(`${modelLabel}：${String(data.model ?? '').trim() || '—'}`)
    out.push(`${presetLabel}：${copy.modeName((data.presetId as string | null) ?? null)}`)
  } else if (kind === 'task') {
    // 任务节点：显示任务描述（不显示类型），超出两行省略
    const content = clip(String(data.content ?? ''), 56)
    if (content.trim()) out.push(content)
  } else if (kind === 'subgraph') {
    const graph = data.graph as { nodes?: unknown[]; lines?: unknown[] } | undefined
    out.push(`${String(copy.subgraphNodeCount)}：${graph?.nodes?.length ?? 0} · ${String(copy.subgraphLineCount)}：${graph?.lines?.length ?? 0}`)
  } else if (kind === 'step') {
    out.push(`${String(copy.nodeKinds.step)}：${String(data.content ?? '')}`)
  } else if (kind === 'database') {
    out.push(data.dbType === 'server' ? `${String(data.dbKind ?? 'mysql')} · ${String(copy.dbTypeServer)}` : String(copy.dbLocalLabel))
    if (data.vectorSource === 'bm25') out.push(String(copy.dbBm25Badge))
  }
  return out.filter((line) => String(line ?? '').trim())
}

/**
 * 节点卡片以 memo 包住：父组件拖拽/平移/缩放等本地渲染态变化时，未变的节点不重渲染
 * （回调由 GraphCanvas 以 useCallback 固定引用，节点对象与运行状态对象保持原引用）。
 */
export const FlowNode = memo(function FlowNode({ node, copy, mode, selected, highlighted, dimmed = false, dragging, runStatus, locked, lockHint, agentPatched, connectedHandles, onPointerDown, onHandlePointerDown, onOpenSubgraph }: FlowNodeProps) {
  const kind = node.kind
  const isProxy = kind === 'proxy'
  const isStage = kind === 'start' || kind === 'end' || kind === 'pause'
  const displayKind = isProxy ? node.data.referencedRoleKind === 'parent' ? 'parent' : 'agent' : kind
  // 阶段名称在渲染期按界面语言取词典；存储值保持中文规范值（validateFlow 锁定该值）。
  const labelKind = (mode === 'mode2' && kind === 'start' ? 'input'
    : mode === 'mode2' && kind === 'end' ? 'output' : displayKind) as keyof Dict['nodeKinds']
  // 名称回退：label 为空（含空白）时显示节点种类名（避免虚拟节点显示为空白卡片）
  const nodeLabel = isStage ? copy.nodeKinds[labelKind]
    : String(node.data.label ?? '').trim() || String(copy.nodeKinds[displayKind as keyof Dict['nodeKinds']] ?? '')
  const handles = nodeHandles(displayKind, mode)
  const status = runStatus?.status ?? null
  const statusText = statusLabelOf(copy, status)
  const metaLines = metaLinesOf(node, copy)
  // 每行独立元信息（角色卡「模型 / 组合」两行显示；CSS white-space:pre-wrap 生效）
  const metaText = metaLines.join('\n')
  const size = nodeSizeOf(node)
  const cls = [
    'wf-node',
    `wf-node--${displayKind}`,
    selected ? 'is-selected' : '',
    highlighted ? 'is-highlighted' : '',
    isProxy ? 'is-proxy' : '',
    locked ? 'is-locked' : '',
  ].filter(Boolean).join(' ')

  // One physical socket per side carries compatible semantic channels.
  const handleEl = (available: string[], side: 'left' | 'right' | 'top' | 'bottom'): React.ReactNode => {
    if (!available.length) return null
    const handle = available.find(h => h.startsWith('flow-')) ?? available[0]
    const dir = handle.endsWith('-out') ? 'out' : 'in'
    const connected = available.some(h => connectedHandles?.includes(`|${node.id}:${h}:${side}|`))
    const style: React.CSSProperties = side === 'top' || side === 'bottom'
      ? { left: '50%', [side]: -6 }
      : { top: '50%', [side]: -6 }
    return (
      <span key={side} className={`wf-graph__handle is-side-${side} is-${dir}${connected ? ' is-connected' : ''}`}
        style={style} data-handle={handle} data-handles={available.join(' ')} data-port-side={side}
        title={dir === 'in' ? String(copy.nodeKinds.input) : String(copy.nodeKinds.output)}
        onPointerDown={event => onHandlePointerDown(event, node.id, handle)} />
    )
  }

  return (
    <div
      className={`wf-graph__node${dragging ? ' is-dragging' : ''}${dimmed ? ' is-runtime-dimmed' : ''}`}
      data-wf-node-id={node.id}
      style={{ left: node.position.x, top: node.position.y, width: size.w, height: size.h }}
      onPointerDown={(event) => onPointerDown(event, node.id)}
    >
      <div className={cls} title={locked ? lockHint : undefined}>
        <div className="wf-node__kind">
          <span>{String(copy.nodeKinds[labelKind] ?? labelKind)}</span>
          {kind === 'subgraph' && onOpenSubgraph
            ? <button type="button" className="wf-node__subgraph-open" title={String(copy.subgraphOpen)} onPointerDown={(event) => event.stopPropagation()} onClick={(event) => { event.stopPropagation(); onOpenSubgraph(node.id) }}>{String(copy.subgraphOpen)}</button>
            : null}
          {statusText ? <span className={`wf-status-dot is-${status}`} /> : null}
          {statusText ? <span className="wf-hint">{statusText}</span> : null}
          {/* 运行中锁定角标（已完成/执行中流程不可修改、不可删除；仍可拖动移动） */}
          {locked ? <span className="wf-node__lock-badge" title={lockHint}>🔒</span> : null}
          {/* P4：最近一次父代理补丁改动的节点（帮助用户理解画布为何变了） */}
          {agentPatched ? <span className="wf-node__agent-badge" title={String(copy.agentPatchedBadge)}>{String(copy.agentPatchedBadge)}</span> : null}
        </div>
        <div className="wf-node__label">
          {isProxy ? <span className="wf-node__proxy-badge">{String(copy.proxyBadge)}</span> : null}
          {nodeLabel}
        </div>
        {metaLines.length > 0 ? <div className="wf-node__prompt">{metaText}</div> : null}
        {handleEl(handles.left, 'left')}
        {handleEl(handles.right, 'right')}
        {handleEl(handles.left, 'top')}
        {handleEl(handles.right, 'bottom')}
      </div>
    </div>
  )
})
