// src/client/hooks/useRunProgress.ts
// Restore instance progress on document entry and after an active run settles.
import { useEffect } from 'react'
import type { Dispatch } from 'react'
import type { RunSnapshot } from '../../host/shared/types.js'
import type { StudioAction } from '../studio/studio-state.js'
import type { RemoteFace } from './useRemote.js'
import { EP } from '../lib/remote.js'

export function useRunProgress(
  flow: { id: string; sessionId: string } | null,
  trackedRunId: string | null,
  dispatch: Dispatch<StudioAction>,
  remote: RemoteFace,
): void {
  const flowId = flow?.id, sessionId = flow?.sessionId
  useEffect(() => {
    if (!flowId || !sessionId || trackedRunId) return
    const control = new AbortController()
    void (async () => {
      const history = await remote.call(EP.EP_RUN_HISTORY, { sessionId, flowId }, { signal: control.signal }) as RunSnapshot[]
      if (control.signal.aborted || !Array.isArray(history)) return
      const latest = history.find(run => run.flowId === flowId && run.sessionId === sessionId)
      if (latest) dispatch({ type: 'RUN_SNAPSHOT', snapshot: latest })
    })().catch(() => {
      // History restoration is auxiliary; the run endpoint still selects the authoritative checkpoint.
    })
    return () => control.abort()
  }, [dispatch, remote, flowId, sessionId, trackedRunId])
}
