// src/client/components/canvas/CanvasEdges.tsx
//
// 画布连线层（SVG）：贝塞尔连线、条件标签、运行/锁定态样式、方向箭头定义与连线草稿。
// 从 GraphCanvas 拆出——连线渲染与节点交互是两个独立的变更原因。
//
// 渲染边界：本组件以 memo 包住，派生视图用 useMemo 收敛。父组件因拖拽/平移/缩放等本地
// 渲染态重渲染时，只要连线输入（节点、边、索引、选中项、回调引用）未变，连线层与逐边
// 几何计算整体跳过——拖拽每帧不应重算全部连线几何。
//
// 两层渲染：base 是卡片下方的常规连线；overlay 只画成员入线进入 Team 卡片后的短段
// （卡片背景会遮挡 base 层，短段需抬到卡片之上、接点之下）。

import { memo, useMemo, useId } from 'react'
import type { Dict } from '../../i18n.js'
import type { CanvasEdge, CanvasNode } from '../../studio/studio-state.js'
import { conditionLabel, lineColorClass } from '../../lib/graph-edges.js'
import { edgeGeometry, memberInboundStubPath, type MemberGroupIndex } from './geometry.js'
import type { OrthogonalRoute } from '../../lib/orthogonal-routing.js'
import { edgeDisplayPath } from '../../lib/edge-path.js'
import { edgeSegmentDrag } from '../../lib/edge-segment.js'
import { bezierRoutePath, sampleBezier } from '../../lib/bezier-path.js'
import { nodeSizeOf } from '../../lib/card-geometry.js'
import type { RoutePoint } from '../../lib/orthogonal-routing.js'
import { relatedNodeIds } from '../../lib/graph-selection.js'
import { isWorkingEdge } from '../../lib/graph-run-focus.js'

/** 连线层：base = 卡片下方的常规连线；overlay = 抬到 Team 卡片之上的成员入线内段。 */
export type CanvasEdgeLayer = 'base' | 'overlay'

export interface CanvasEdgesProps {
  nodes: CanvasNode[]
  edges: CanvasEdge[]
  byId: Map<string, CanvasNode>
  /** 成员 → 组 预建索引（所属组反查 O(1)，由 GraphCanvas 按节点集 memo 化）。 */
  memberGroups: MemberGroupIndex
  selectedEdge: string | null
  selectedNode: string | null
  routes: Map<string, OrthogonalRoute>
  /** Present only while the displayed document is running; an empty set means no step is working. */
  activeNodeIds?: ReadonlySet<string>
  isLockedEdge(id: string): boolean
  copy: Dict
  onEdgeSelect(id: string): void
  onEdgePointerDown?(event: React.PointerEvent, id: string, waypointIndex?: number, segmentIndex?: number, curveAnchors?: RoutePoint[]): void
  onAnchorRemove?(id: string, index: number, anchors: RoutePoint[]): void
  onAnchorContext?(event: React.MouseEvent, id: string, index: number, anchors: RoutePoint[]): void
  /** 连线草稿路径（拖拽连线中）。 */
  draftPath: string | null
  /** 渲染层（缺省 base）；overlay 只画成员入线进入卡片后的短段。 */
  layer?: CanvasEdgeLayer
}

export const CanvasEdges = memo(function CanvasEdges(props: CanvasEdgesProps) {
  const { nodes, edges, byId, memberGroups, selectedEdge, selectedNode, routes, activeNodeIds, isLockedEdge, copy, onEdgeSelect, onEdgePointerDown, onAnchorRemove, onAnchorContext, draftPath, layer = 'base' } = props
  const markerPrefix = useId().replace(/:/g, '')
  const curveObstacles = useMemo(() => [...byId.values()].filter(n => !memberGroups.has(n.id)).map(n => ({ id: n.id, ...n.position, ...nodeSizeOf(n) })), [byId, memberGroups])
  const relatedIds = useMemo(() => activeNodeIds ?? relatedNodeIds(nodes, selectedNode), [nodes, selectedNode, activeNodeIds])
  const relates = (edge: CanvasEdge): boolean => relatedIds.has(edge.source) || relatedIds.has(edge.target)
  const focusClass = (edge: CanvasEdge): string => relates(edge) ? ` is-related${activeNodeIds ? ' is-runtime-related' : ''}` : activeNodeIds || selectedNode ? ' is-dimmed' : ''

  const edgeViews = useMemo(() => {
    if (nodes.length === 0) return []
    const bundleArrows = new Map<string, string>()
    for (const edge of [...edges].sort((a, b) => Number(isWorkingEdge(b, activeNodeIds)) - Number(isWorkingEdge(a, activeNodeIds)) || a.id.localeCompare(b.id))) {
      const key = routes.get(edge.id)?.targetBundle
      if (key && !bundleArrows.has(key)) bundleArrows.set(key, edge.id)
    }
    if (layer === 'overlay') {
      // 成员入线进入 Team 卡片后的短段：卡片背景绘制在连线层之上，必须抬到覆盖层，
      // 线端才能落到卡片内部的成员接点上（覆盖层位于卡片之上、接点之下）。
      return edges.map((edge) => {
        const stub = memberInboundStubPath(edge, byId, memberGroups, routes.get(edge.id))
        if (!stub) return null
        const isSelected = edge.id === selectedEdge
        const isRunning = isWorkingEdge(edge, activeNodeIds)
        const isLocked = isLockedEdge(edge.id)
        const lineType = lineColorClass(edge)
        return (
          <path
            key={edge.id}
            data-edge-id={edge.id}
            className={`wf-graph__edge${isSelected ? ' is-selected' : ''}${focusClass(edge)}${lineType ? ` ${lineType}` : ''}${isRunning ? ' is-running' : ''}${isLocked ? ' is-locked' : ''}`}
            d={stub}
          />
        )
      })
    }
    return edges.map((edge) => {
      const geometry = routes.get(edge.id) ?? edgeGeometry(edge, byId, memberGroups)
      if (!geometry) return null
      const isSelected = edge.id === selectedEdge
      const isRunning = isWorkingEdge(edge, activeNodeIds)
      // 运行中锁定连线：属于已完成流程或执行中节点的左入口 → 灰化虚线、点击不选中（属性栏不展开）
      const isLocked = isLockedEdge(edge.id)
      // 连线颜色 class 与 lib/graph-edges.lineColorClass 同源（条件优先 + 通道回退）
      const lineType = lineColorClass(edge)
      // 条件标签文案取自词典（英文界面不再出现中文标签）
      const label = conditionLabel(edge.condition, { pass: copy.lineTypePass, fail: copy.lineTypeFail, content: copy.lineTypeContent })
      // 流程通道有向（箭头）；上下文/数据库线无方向要求
      const channel = lineType.startsWith('is-') ? lineType.slice(3) : ''
      const bundle = routes.get(edge.id)?.targetBundle
      const markerEnd = bundle && bundleArrows.get(bundle) !== edge.id ? undefined : `url(#${markerPrefix}-wf-arrow-${channel === '' ? 'flow' : channel})`
      const labelWidth = routes.get(edge.id)?.labelWidth ?? (label ? Math.min(150, Math.max(34, label.length * 7 + 16)) : 0)
      const route = routes.get(edge.id)
      const curveBoxes = memberGroups.has(edge.target) ? curveObstacles.filter(n => memberGroups.get(edge.target)?.id !== n.id) : curveObstacles
      const curve = route && edge.appearance?.type === 'bezier' ? bezierRoutePath(route.points, edge.appearance.waypoints, curveBoxes, edge.appearance.anchorMode === 'manual') : null
      const displayPath = curve?.path ?? (route ? edgeDisplayPath(route.points) : geometry.path)
      const controls = curve?.anchors ?? edge.appearance?.waypoints ?? []
      const curveLabelAnchor = curve?.spans.flatMap(span => Array.from({ length: 9 }, (_, i) => sampleBezier(span, i / 8)))
        .sort((a, b) => Math.hypot(a.x - geometry.label.x, a.y - geometry.label.y) - Math.hypot(b.x - geometry.label.x, b.y - geometry.label.y))[0]
      const labelAnchor = curveLabelAnchor && Math.hypot(curveLabelAnchor.x - geometry.label.x, curveLabelAnchor.y - geometry.label.y) > 8 ? curveLabelAnchor : route?.labelAnchor
      return (
        <g key={edge.id} data-edge-id={edge.id} className={`${isLocked ? 'is-locked' : ''}${focusClass(edge)}`}>
          <title>{label || (channel === 'ctx' ? copy.lineTypeContext : channel === 'db' ? copy.lineTypeDatabase : copy.lineTypeFlow)}</title>
          {/* 被锁连线不可选中/编辑（用户裁决：锁定的内容不展开属性面板，故无需 toast） */}
          {isLocked ? <title>{String(copy.lockedEdgeHint)}</title> : null}
          <path
            className={`wf-graph__edge-hit${isSelected ? ' is-selected' : ''}`}
            d={displayPath}
            onPointerDown={(event) => {
              event.stopPropagation()
              if (isLocked) return
              onEdgeSelect?.(edge.id)
              onEdgePointerDown?.(event, edge.id)
            }}
          />
          <path
            className={`wf-graph__edge${isSelected ? ' is-selected' : ''}${focusClass(edge)}${lineType ? ` ${lineType}` : ''}${isRunning ? ' is-running' : ''}${isLocked ? ' is-locked' : ''}`}
            d={displayPath}
            markerEnd={markerEnd}
          />
          {label && labelWidth ? (
            <g className="wf-edge-label-group">
              {labelAnchor ? <path className="wf-graph__label-leader" d={`M ${labelAnchor.x} ${labelAnchor.y} L ${geometry.label.x} ${geometry.label.y}`} /> : null}
              <rect className="wf-graph__label-bg" x={geometry.label.x - labelWidth / 2} y={geometry.label.y - 11} width={labelWidth} height={22} rx={7} />
              <text className="wf-graph__label" x={geometry.label.x} y={geometry.label.y}>{label}</text>
            </g>
          ) : null}
          {isSelected && !isLocked ? controls.map((point, index) => <circle key={index} className="wf-edge-control" cx={point.x} cy={point.y} r={6} tabIndex={0} role="button" aria-label={String(copy.anchorHint)}
            onPointerDown={event => { event.stopPropagation(); event.currentTarget.focus(); onEdgePointerDown?.(event, edge.id, index, undefined, curve?.anchors) }}
            onDoubleClick={event => { event.stopPropagation(); onAnchorRemove?.(edge.id, index, controls) }}
            onContextMenu={event => { event.preventDefault(); event.stopPropagation(); onAnchorContext?.(event, edge.id, index, controls) }}
            onKeyDown={event => { if (event.key === 'Delete' || event.key === 'Backspace') { event.preventDefault(); event.stopPropagation(); onAnchorRemove?.(edge.id, index, controls) } }} />) : null}
          {isSelected && !isLocked && route && !curve ? route.points.slice(0, -1).map((point, index) => {
            const segment = edgeSegmentDrag(route.points, index)
            if (!segment) return null
            const next = route.points[index + 1], horizontal = segment.axis === 'y'
            return <rect key={`segment-${index}`} className={`wf-edge-segment is-${horizontal ? 'horizontal' : 'vertical'}`} data-segment-index={index}
              x={(point.x + next.x) / 2 - (horizontal ? 8 : 4)} y={(point.y + next.y) / 2 - (horizontal ? 4 : 8)} width={horizontal ? 16 : 8} height={horizontal ? 8 : 16} rx={3}
              aria-label={String(copy.edgeMoveSegment)} onPointerDown={event => { event.stopPropagation(); onEdgePointerDown?.(event, edge.id, undefined, index) }} />
          }) : null}
        </g>
      )
    })
  }, [nodes, edges, byId, memberGroups, selectedEdge, selectedNode, relatedIds, activeNodeIds, routes, isLockedEdge, copy, onEdgeSelect, onEdgePointerDown, onAnchorRemove, onAnchorContext, layer, markerPrefix, curveObstacles])

  if (layer === 'overlay') {
    return <svg className="wf-graph__edges is-overlay" width="100%" height="100%">{edgeViews}</svg>
  }

  return (
    <svg className="wf-graph__edges" width="100%" height="100%">
      {/* 有向线段箭头（流程通道：流程/通过/不通过/内容；上下文/数据库线无方向要求） */}
      <defs>
        {['flow', 'ctx', 'db', 'pass', 'fail', 'content'].map(channel => (
          <marker key={channel} id={`${markerPrefix}-wf-arrow-${channel}`} viewBox="0 0 12 12" refX="12" refY="6" markerUnits="userSpaceOnUse" markerWidth="12" markerHeight="12" orient="auto-start-reverse">
            <path d="M 0 1 L 12 6 L 0 11 Z" className={`wf-arrow-head is-${channel}`} />
          </marker>
        ))}
      </defs>
      {edgeViews}
      {draftPath ? <path className="wf-graph__connection" d={draftPath} /> : null}
    </svg>
  )
})
