// src/client/hooks/useCanvasActions.ts
//
// 画布编辑操作面：节点放置（模板深拷贝/父代理/阶段/Team/入组）、连线
// 校验与增删、删除级联、整理布局、清空画布、虚拟节点复制与 Team 成员
// 移除。变更统一走 dispatch；涉及图标量变化前先 history.remember()。
//
// 本次改造（用户裁决）：
//   - 画布节点删除不再二次确认（直接删除）；
//   - 清空画布不再二次确认（运行中由工具栏禁用按钮拦截）；
//   - 运行中实例画布锁定（run-locks）：已完成/执行中流程不可删除、不可改线；
//   - 纯 XY 拖动 / Team 卡片缩放 = 几何改动 → 防抖自动保存（不弹确认、静默落盘）。

import { useCallback, useEffect, useMemo, useRef } from 'react'
import type { Dispatch } from 'react'
import type { StudioAction, StudioState, CanvasNode, CanvasEdge } from '../studio/studio-state.js'
import { currentFlowOf, currentFlowTemplateOf, currentServiceOf } from '../studio/studio-state.js'
import type { RoleAssetDetail } from '../../host/shared/asset-types.js'
import type { GraphHistoryFace } from './useGraphHistory.js'
import type { ToastFace } from './useToast.js'
import type { SaveCanvasOptions } from './useDocumentActions.js'
import type { RunLockSet } from '../lib/run-locks.js'
import type { Dict } from '../i18n.js'
import { STAGE_LABELS } from '../../host/shared/protocol.js'
import { blankNode, duplicateNodes } from '../lib/manual-nodes.js'
import type { NodeKind } from '../../host/shared/graph-model.js'
import type { LineAppearance } from '../../host/shared/graph-model.js'
import { connectionProblem, connectionProblemMessage } from '../lib/connection-rules.js'
import { channelHandles, type ConnectionChannel } from '../lib/manual-connection.js'
import { TEAM_MEMBER_LIMIT_FALLBACK, consolidateGroups, dropNodeFlowLines, joinNodeToGroup } from '../lib/group-members.js'
import { layoutNodes, layoutBoxesOf } from '../lib/layout-fit.js'
import { autoLayoutGraph, type AutoLayoutGraphOptions } from '../lib/auto-layout-graph.js'
import { autoRouteEdges } from '../lib/auto-route-edges.js'
import { groupCardSizeOf } from '../lib/card-geometry.js'
import { constrainNodePosition, snapConnectedCenter, vacantNodePosition } from '../lib/node-collision.js'
import { stageTemplateKinds } from '../lib/graph-handles.js'
import { templateToNodeData } from '../lib/template-to-node.js'
import { roleAssetNodeKind, roleAssetToNodeData } from '../lib/asset-to-node.js'

/** 几何拖动（节点拖动 / Team 卡片缩放）自动保存的防抖窗口（毫秒）。 */
export const GEOMETRY_AUTOSAVE_DEBOUNCE_MS = 400

/**
 * 词典 → 字符串词条表：连线错误文案只消费字符串词条，而词典里还有数组/嵌套词条。
 * 按值类型投影，避免为「只读字符串」对整个词典做断言（断言会把非字符串词条一起骗过类型）。
 */
function stringEntriesOf(dict: Dict): Record<string, string> {
  return Object.fromEntries(Object.entries(dict).filter((entry): entry is [string, string] => typeof entry[1] === 'string'))
}

/** 画布编辑面的外部依赖注入（锁定判定 + 自动保存 + 宿主下发的成员上限）。 */
export interface CanvasActionsOptions {
  /** 运行中实例画布锁定判定集（模式一 running；未启用时全部解锁）。 */
  locks: RunLockSet
  /** 画布保存入口（纯几何改动的防抖自动保存用；auto:true = 静默落库）。 */
  saveCanvas(options?: SaveCanvasOptions): Promise<unknown>
  /**
   * 宿主下发的 Team 成员上限（部署层 agent-team.maxMembers 的镜像）。
   * 缺省回退 TEAM_MEMBER_LIMIT_FALLBACK：入组交互据此拒绝超限，避免画布放得下而运行期排不进。
   */
  teamMemberLimit?: number
}

export interface CanvasActionsFace {
  rememberGraph(): void
  moveNode(id: string, position: { x: number; y: number }): void
  onNodeDragStart(): void
  onConnect(connection: { source: string; target: string; sourceHandle: string; targetHandle: string; appearance?: LineAppearance }): void
  setEdgeAppearance(id: string, patch: LineAppearance): void
  setEdgeChannel(id: string, channel: ConnectionChannel): void
  onConnectionRejected(): void
  tidyGraph(options?: AutoLayoutGraphOptions): CanvasNode[]
  routeGraph(): void
  clearGraph(): void
  removeSelected(): void
  removeNodeNow(id: string): void
  removeLine(id: string): void
  placeTemplateNode(kind: 'role' | 'task' | 'database', templateId: string, position: { x: number; y: number }): void
  /** 角色资产拖入画布：生成内联角色节点并写入来源资产 id（sourceAssetId）。 */
  placeRoleAssetNode(detail: RoleAssetDetail, position: { x: number; y: number }): void
  placeParentNode(templateId: string, position: { x: number; y: number }): void
  placeStageNode(kind: string, position: { x: number; y: number }): void
  placeGroupNode(position: { x: number; y: number }): void
  /** Team 模板拖入画布：按模板名称/协作 Prompt 生成 Team 节点。 */
  placeGroupFromTemplate(templateId: string, position: { x: number; y: number }): void
  placeTemplateIntoGroup(kind: 'role', templateId: string, groupId: string, position: { x: number; y: number }): void
  onGroupResize(id: string, size: { w: number; h: number }): void
  addNodeToGroup(nodeId: string, groupId: string): void
  copyToProxy(): void
  duplicateSelected(): void
  placeBasicNode(kind: NodeKind, position: { x: number; y: number }, sourceId?: string): void
  removeGroupMember(memberId: string): void
  /** 交换节点左右连接点（节点属性 swapPorts 取反；可撤销）。 */
  swapNodePorts(id: string): void
}

/** 画布编辑面（remember 需在变更 dispatch 前调用；远端 IO 仅几何自动保存一处）。 */
export function useCanvasActions(
  state: StudioState,
  dispatch: Dispatch<StudioAction>,
  notify: ToastFace['toast'],
  history: GraphHistoryFace,
  t: Dict,
  options: CanvasActionsOptions,
): CanvasActionsFace {
  const { locks, saveCanvas } = options
  const teamMemberLimit = options.teamMemberLimit ?? TEAM_MEMBER_LIMIT_FALLBACK
  /** 几何自动保存防抖计时器（跨渲染保持；卸载时清理，避免迟到保存）。 */
  const autoSaveTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const saveCanvasRef = useRef(saveCanvas)
  saveCanvasRef.current = saveCanvas

  // 事件回调读 state 的最新切片：经 ref 取当前渲染的 state，使下面的回调身份
  // 与整个 state 解耦——否则每次状态变化都重建 moveNode/onGroupResize，
  // 下游以 face 为依赖的 effect（keydown/pointermove 监听）会反复重挂（D08-07）。
  const stateRef = useRef(state)
  stateRef.current = state

  /** 当前画布对象是否可自动保存（无对象/本地草稿态跳过——草稿须手动保存/创建实例）。 */
  const canAutoSave = useCallback((): boolean => {
    const current = stateRef.current
    if (!current.currentId) return false
    // 资产态：内容变更必须显式「登记新版本」（版本是显式动作，T6 接线的保存入口负责），
    // 不做几何防抖自动保存——否则拖动即静默产生版本。
    if (current.currentKind === 'flowAsset') return false
    const doc = current.currentKind === 'flowTemplate'
      ? currentFlowTemplateOf(current)
      : current.currentKind === 'workflow'
        ? currentFlowOf(current)
        : current.currentKind === 'service'
          ? currentServiceOf(current)
          : null
    if (!doc) return false
    return (doc as { _draft?: boolean })._draft !== true
  }, [])

  /** 纯几何改动（拖动/缩放）→ 防抖自动保存（静默落库；草稿态不自动落库）。 */
  const scheduleGeometryAutoSave = useCallback((): void => {
    if (!canAutoSave()) return
    if (autoSaveTimer.current) clearTimeout(autoSaveTimer.current)
    autoSaveTimer.current = setTimeout(() => {
      autoSaveTimer.current = null
      void saveCanvasRef.current({ auto: true })
    }, GEOMETRY_AUTOSAVE_DEBOUNCE_MS)
  }, [canAutoSave])

  useEffect(() => () => {
    if (autoSaveTimer.current) clearTimeout(autoSaveTimer.current)
  }, [])

  // ---------- 画布操作 ----------
  const rememberGraph = useCallback(() => {
    history.remember()
  }, [history])

  const moveNode = useCallback((id: string, position: { x: number; y: number }) => {
    const nodes = stateRef.current.canvas.nodes, node = nodes.find(n => n.id === id)
    const boxes = layoutBoxesOf(nodes, groupCardSizeOf)
    const neighbors = new Set(stateRef.current.canvas.edges.filter(e => e.sourceHandle === 'flow-out' && (e.source === id || e.target === id)).flatMap(e => [e.source, e.target]))
    const snapped = node ? snapConnectedCenter({ id, ...position, ...groupCardSizeOf(node) }, boxes.filter(b => b.id !== id && neighbors.has(b.id))) : position
    const constrained = node ? constrainNodePosition({ id, ...snapped, ...groupCardSizeOf(node) }, boxes, node.position) : position
    dispatch({ type: 'NODE_MOVED', id, position: constrained })
    scheduleGeometryAutoSave()
  }, [dispatch, scheduleGeometryAutoSave])

  const onNodeDragStart = useCallback(() => {
    history.remember()
  }, [history])

  const onConnect = useCallback((connection: { source: string; target: string; sourceHandle: string; targetHandle: string; appearance?: LineAppearance }) => {
    // 运行中锁定：已完成节点不得再接出线，已完成/执行中节点不得再接左入口线
    // （反馈沿用既有「无效连线」toast，用户裁决）
    if (!locks.canConnect(connection.source, connection.target)) {
      notify('error', t.invalidConnection)
      return
    }
    const current = stateRef.current
    const existing = current.canvas.edges.find(edge => edge.source === connection.source && edge.target === connection.target && edge.sourceHandle === connection.sourceHandle && edge.targetHandle === connection.targetHandle)
    if (existing) { dispatch({ type: 'SELECT_EDGE', id: existing.id }); return }
    const problem = connectionProblem(current.canvas.nodes, current.canvas.edges, connection)
    if (!problem.valid) {
      notify('error', connectionProblemMessage(problem, stringEntriesOf(t)))
      return
    }
    history.remember()
    const edge: CanvasEdge = {
      id: `e-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
      source: connection.source,
      target: connection.target,
      sourceHandle: connection.sourceHandle as CanvasEdge['sourceHandle'],
      targetHandle: connection.targetHandle as CanvasEdge['targetHandle'],
      ...(connection.appearance ? { appearance: connection.appearance } : {}),
    }
    dispatch({ type: 'EDGE_ADDED', edge })
    dispatch({ type: 'SELECT_EDGE', id: edge.id })
    scheduleGeometryAutoSave()
  }, [dispatch, history, locks, notify, scheduleGeometryAutoSave, t])

  const setEdgeAppearance = useCallback((id: string, patch: LineAppearance): void => {
    if (locks.isEdgeLocked(id)) return
    const edge = stateRef.current.canvas.edges.find(e => e.id === id)
    if (!edge) return
    dispatch({ type: 'EDGE_PATCH', id, patch: { appearance: { ...edge.appearance, ...patch } } })
    scheduleGeometryAutoSave()
  }, [dispatch, locks, scheduleGeometryAutoSave])

  const setEdgeChannel = useCallback((id: string, channel: ConnectionChannel): void => {
    const current = stateRef.current
    const edge = current.canvas.edges.find(item => item.id === id)
    if (!edge || locks.isEdgeLocked(id)) return
    const handles = channelHandles(channel)
    if (edge.sourceHandle === handles.sourceHandle && edge.targetHandle === handles.targetHandle) return
    const problem = connectionProblem(current.canvas.nodes, current.canvas.edges, { ...edge, ...handles, lineId: id })
    if (!problem.valid) {
      notify('error', connectionProblemMessage(problem, stringEntriesOf(t)))
      return
    }
    history.remember()
    // Conditions belong only to flow. Preserve identity and manual geometry during conversion.
    dispatch({ type: 'EDGE_PATCH', id, patch: { ...handles, condition: undefined } })
    scheduleGeometryAutoSave()
  }, [dispatch, history, locks, notify, scheduleGeometryAutoSave, t])

  const onConnectionRejected = useCallback(() => {
    notify('error', t.invalidConnection)
  }, [notify, t.invalidConnection])

  const tidyGraph = useCallback((options: AutoLayoutGraphOptions = {}) => {
    history.remember()
    const current = stateRef.current
    const running = current.run.snapshot?.status === 'running' || current.activeRuns.some(run => run.flowId === current.currentId && run.status === 'running')
    // Running layouts remain geometric: adding/removing aliases changes topology and is design-time only.
    const arranged = running ? { nodes: layoutNodes(current.canvas.nodes, current.canvas.edges), edges: current.canvas.edges }
      : autoLayoutGraph(current.canvas.nodes, current.canvas.edges, options)
    const next = arranged.nodes, edges = arranged.edges
    dispatch({ type: 'GRAPH_REPLACED', nodes: next, edges, dirty: true })
    // Save the complete layout edit atomically, including optional local aliases and edge endpoints.
    scheduleGeometryAutoSave()
    notify('success', t.toastTidy)
    return next
  }, [dispatch, history, notify, scheduleGeometryAutoSave, t.toastTidy])

  /** Route on the user's existing layout without replacing cards, references or execution semantics. */
  const routeGraph = useCallback(() => {
    const current = stateRef.current
    if (!current.canvas.edges.length) return
    history.remember()
    dispatch({ type: 'GRAPH_REPLACED', nodes: current.canvas.nodes, edges: autoRouteEdges(current.canvas.edges), dirty: true })
    scheduleGeometryAutoSave()
    notify('success', t.toastAutoRoute)
  }, [dispatch, history, notify, scheduleGeometryAutoSave, t.toastAutoRoute])

  /** 清空画布：无二次确认（用户裁决）；运行中由工具栏禁用入口，此处不重复拦截。 */
  const clearGraph = useCallback(() => {
    history.remember()
    dispatch({ type: 'GRAPH_REPLACED', nodes: [], edges: [], dirty: true })
    dispatch({ type: 'CLEAR_SELECTION' })
    notify('info', t.toastCleared)
  }, [dispatch, history, notify, t.toastCleared])

  const removeNodeNow = useCallback((id: string) => {
    // 运行中锁定（防御性二次拦截：调用点可能不止 removeSelected）
    if (locks.isNodeLocked(id)) return
    history.remember()
    // 组内成员离开 Team：清除成员关系
    const node = state.canvas.nodes.find((item) => item.id === id)
    if (node?.kind === 'group' && state.canvas.nodes.some(member => member.data.groupId === id && locks.isNodeLocked(member.id))) return
    const groupId = node?.kind === 'parent' || node?.kind === 'agent' ? (node.data.groupId as string | null | undefined) : null
    // 级联删除集合：主节点 + 其全部虚拟引用节点
    const removed = new Set<string>([id])
    if (node && (node.kind === 'parent' || node.kind === 'agent')) {
      for (const item of state.canvas.nodes) {
        if (item.kind === 'proxy' && (item as { proxySourceId?: unknown }).proxySourceId === id) removed.add(item.id)
      }
    }
    if (groupId) {
      dispatch({
        type: 'GRAPH_REPLACED',
        nodes: state.canvas.nodes.filter((item) => !removed.has(item.id)).map((item) => item.kind === 'group' && ((item.data.memberIds as string[] | undefined) ?? []).includes(id)
          ? { ...item, data: { ...item.data, memberIds: (item.data.memberIds as string[]).filter((memberId) => memberId !== id) } }
          : item),
        edges: state.canvas.edges.filter((edge) => !removed.has(edge.source) && !removed.has(edge.target)),
        dirty: true,
      })
    } else {
      // NODE_REMOVED reducer 已实现同级联删除（虚拟引用随主节点一并移除）
      dispatch({ type: 'NODE_REMOVED', id })
    }
    dispatch({ type: 'CLEAR_SELECTION' })
    notify('info', t.toastDeleted)
    scheduleGeometryAutoSave()
  }, [dispatch, history, locks, notify, scheduleGeometryAutoSave, state.canvas.edges, state.canvas.nodes, t.toastDeleted])

  /** 删除选中节点：无二次确认（用户裁决）；运行中锁定项静默忽略。 */
  const removeSelected = useCallback(() => {
    if (!state.selection.nodeId) return
    const id = state.selection.nodeId
    const node = state.canvas.nodes.find((item) => item.id === id)
    if (!node) return
    // 运行中锁定：已完成/执行中的节点不可删除（静默忽略；无 toast，用户裁决）
    if (locks.isNodeLocked(id)) return
    removeNodeNow(id)
  }, [locks, removeNodeNow, state.canvas.nodes, state.selection.nodeId])

  const removeLine = useCallback((id: string) => {
    // 运行中锁定：已完成流程的连线与执行中节点左入口连线不可删除（静默忽略）
    if (locks.isEdgeLocked(id)) return
    history.remember()
    dispatch({ type: 'EDGE_REMOVED', id })
    dispatch({ type: 'CLEAR_SELECTION' })
    notify('info', t.toastDeleted)
    scheduleGeometryAutoSave()
  }, [dispatch, history, locks, notify, scheduleGeometryAutoSave, t.toastDeleted])

  // ---------- 画布节点放置（模板深拷贝） ----------
  const placeTemplateNode = useCallback((kind: 'role' | 'task' | 'database', templateId: string, position: { x: number; y: number }) => {
    if (!state.currentId) return
    const template = state.templates[kind].find((item) => item.id === templateId)
    if (!template) return
    const data = templateToNodeData(kind, template) ?? {}
    const nodeKind = kind === 'role' ? 'agent' : kind
    const node: CanvasNode = {
      id: `${nodeKind}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
      kind: nodeKind as CanvasNode['kind'],
      position,
      data,
    }
    history.remember()
    dispatch({ type: 'NODE_ADDED', node })
    dispatch({ type: 'SELECT_NODE', id: node.id })
    notify('success', t.toastNodeAdded)
  }, [dispatch, history, notify, state.currentId, state.templates, t.toastNodeAdded])

  /**
   * 角色资产拖入画布（资产态）：生成**内联**角色节点（深拷贝解耦），
   * data.sourceAssetId 登记来源资产 id——仍是内联节点，不建立运行时引用。
   * 父代理资产沿用「每画布最多一个父代理」约束（与父子代理模板同口径）。
   */
  const placeRoleAssetNode = useCallback((detail: RoleAssetDetail, position: { x: number; y: number }) => {
    if (!state.currentId) return
    const nodeKind = roleAssetNodeKind(detail)
    if (nodeKind === 'parent' && state.canvas.nodes.some((item) => item.kind === 'parent')) {
      notify('error', t.parentDuplicatedHint)
      return
    }
    const node: CanvasNode = {
      id: `${nodeKind}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
      kind: nodeKind,
      position,
      data: roleAssetToNodeData(detail),
    }
    history.remember()
    dispatch({ type: 'NODE_ADDED', node })
    dispatch({ type: 'SELECT_NODE', id: node.id })
    notify('success', t.toastNodeAdded)
  }, [dispatch, history, notify, state.canvas.nodes, state.currentId, t.parentDuplicatedHint, t.toastNodeAdded])

  /** 放置父代理节点（每画布最多一个）。 */
  const placeParentNode = useCallback((templateId: string, position: { x: number; y: number }) => {
    if (!state.currentId) return
    if (state.canvas.nodes.some((item) => item.kind === 'parent')) {
      notify('error', t.parentDuplicatedHint)
      return
    }
    const template = state.templates.role.find((item) => item.id === templateId)
    const data = templateToNodeData('role', template) ?? {}
    const node: CanvasNode = {
      id: `parent-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
      kind: 'parent',
      position,
      data,
    }
    history.remember()
    dispatch({ type: 'NODE_ADDED', node })
    dispatch({ type: 'SELECT_NODE', id: node.id })
    notify('success', t.toastNodeAdded)
  }, [dispatch, history, notify, state.canvas.nodes, state.currentId, state.templates.role, t.parentDuplicatedHint, t.toastNodeAdded])

  /**
   * 放置阶段节点：启动节点全图唯一；结束节点允许布置多个——
   * 拓扑交叉的分流可以各自收口到自己的结束节点，避免为汇合而拉出交叉连线。
   */
  const placeStageNode = useCallback((kind: string, position: { x: number; y: number }) => {
    if (!state.currentId) return
    if (kind === 'start' && state.canvas.nodes.some((item) => item.kind === 'start')) {
      notify('error', t.stageDuplicatedHint)
      return
    }
    const labels = stageTemplateKinds(state.mode, t.nodeKinds)
    const label = labels.find((item) => item.kind === kind)?.label ?? kind
    const node: CanvasNode = {
      id: `${kind}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
      kind: kind as CanvasNode['kind'],
      position,
      data: { label },
    }
    history.remember()
    dispatch({ type: 'NODE_ADDED', node })
    dispatch({ type: 'SELECT_NODE', id: node.id })
    notify('success', t.toastNodeAdded)
  }, [dispatch, history, notify, state.canvas.nodes, state.currentId, state.mode, t.nodeKinds, t.stageDuplicatedHint, t.toastNodeAdded])

  /** 放置 Team 节点。 */
  const placeGroupNode = useCallback((position: { x: number; y: number }) => {
    if (!state.currentId) return
    const node: CanvasNode = {
      id: `group-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
      kind: 'group',
      position,
      data: { label: String(t.groupDefaultName), collabPrompt: '', memberIds: [], size: { w: 300, h: 220 } },
    }
    history.remember()
    dispatch({ type: 'NODE_ADDED', node })
    dispatch({ type: 'SELECT_NODE', id: node.id })
    notify('success', t.toastNodeAdded)
  }, [dispatch, history, notify, state.currentId, t.groupDefaultName, t.toastNodeAdded])

  /** Team 模板拖入画布：按模板内容生成 Team 节点（用户批注：Team 模板列表）。 */
  const placeGroupFromTemplate = useCallback((templateId: string, position: { x: number; y: number }) => {
    if (!state.currentId) return
    const template = state.templates.group.find((item) => item.id === templateId)
    const data = template
      ? {
          label: String((template as unknown as { name?: unknown }).name ?? ''),
          collabPrompt: String((template as unknown as { collabPrompt?: unknown }).collabPrompt ?? ''),
          memberIds: [],
          size: { w: 300, h: 220 },
        }
      : { label: String(t.groupDefaultName), collabPrompt: '', memberIds: [], size: { w: 300, h: 220 } }
    const node: CanvasNode = {
      id: `group-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
      kind: 'group',
      position,
      data,
    }
    history.remember()
    dispatch({ type: 'NODE_ADDED', node })
    dispatch({ type: 'SELECT_NODE', id: node.id })
    notify('success', t.toastNodeAdded)
  }, [dispatch, history, notify, state.currentId, state.templates.group, t.groupDefaultName, t.toastNodeAdded])

  /** 左栏角色模板拖入 Team：生成节点并直接登记为组内成员。 */
  const placeTemplateIntoGroup = useCallback((kind: 'role', templateId: string, groupId: string, _position: { x: number; y: number }) => {
    if (!state.currentId) return
    const template = state.templates[kind].find((item) => item.id === templateId)
    const group = state.canvas.nodes.find((item) => item.id === groupId)
    if (!template || !group || group.kind !== 'group') return
    const members = (group.data.memberIds as string[] | undefined) ?? []
    if (members.length >= teamMemberLimit) {
      notify('error', t.groupMemberLimitHint)
      return
    }
    const data = templateToNodeData(kind, template) ?? {}
    const node: CanvasNode = {
      id: `${kind === 'role' ? 'agent' : kind}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
      kind: 'agent',
      position: { x: group.position.x + 10, y: group.position.y + 10 },
      data: { ...data, groupId },
    }
    history.remember()
    // 原子入组：一次变更同时写 node.groupId + 组 memberIds（追加去重），杜绝「卡有成员/列表空/只显示一个」
    const nodes = joinNodeToGroup([...state.canvas.nodes, node], node.id, groupId)
    dispatch({ type: 'GRAPH_REPLACED', nodes, edges: dropNodeFlowLines(state.canvas.edges, node.id), dirty: true })
    dispatch({ type: 'SELECT_NODE', id: node.id })
    notify('success', t.toastGroupMemberAdded)
  }, [dispatch, history, notify, state.canvas.edges, state.canvas.nodes, state.currentId, state.templates, t.groupMemberLimitHint, t.toastGroupMemberAdded, teamMemberLimit])

  const onGroupResize = useCallback((id: string, size: { w: number; h: number }) => {
    dispatch({ type: 'NODE_DATA_PATCH', id, patch: { size } })
    // 卡片缩放属纯几何改动：防抖自动保存（不弹运行中确认、不构成编排变更）
    scheduleGeometryAutoSave()
  }, [dispatch, scheduleGeometryAutoSave])

  /** 角色节点拖入 Team：成员标记 groupId + 组 memberIds 登记（原子追加，防止不一致）。 */
  const addNodeToGroup = useCallback((nodeId: string, groupId: string) => {
    // 运行中锁定：已完成/执行中节点入组会断开其原有流程连线（dropNodeFlowLines），
    // 等于改写已跑完/执行中的流程 → 直接忽略
    if (locks.isNodeLocked(nodeId)) return
    const group = state.canvas.nodes.find((item) => item.id === groupId)
    if (!group || group.kind !== 'group') return
    const node = state.canvas.nodes.find((item) => item.id === nodeId)
    if (!node || (node.kind !== 'parent' && node.kind !== 'agent')) return
    const members = (group.data.memberIds as string[] | undefined) ?? []
    if (members.includes(nodeId)) return
    if (members.length >= teamMemberLimit) {
      notify('error', t.groupMemberLimitHint)
      return
    }
    history.remember()
    // 入组时自动断开该节点原有的流程连线（组内成员仅上下文/数据库线）
    dispatch({ type: 'GRAPH_REPLACED', nodes: joinNodeToGroup(state.canvas.nodes, nodeId, groupId), edges: dropNodeFlowLines(state.canvas.edges, nodeId), dirty: true })
    notify('success', t.toastGroupMemberAdded)
  }, [dispatch, history, locks, notify, state.canvas.edges, state.canvas.nodes, t.groupMemberLimitHint, t.toastGroupMemberAdded, teamMemberLimit])

  // New cards use the current graph's model selection and avoid existing boxes.
  const placeBasicNode = useCallback((kind: NodeKind, position: { x: number; y: number }, sourceId?: string): void => {
    const current = stateRef.current
    if (!current.currentId) return
    if ((kind === 'parent' || kind === 'start') && current.canvas.nodes.some(node => node.kind === kind)) {
      notify('error', kind === 'parent' ? t.parentDuplicatedHint : t.stageDuplicatedHint); return
    }
    const source = sourceId ? current.canvas.nodes.find(node => node.id === sourceId) : undefined
    if (kind === 'proxy' && (!source || (source.kind !== 'agent' && source.kind !== 'parent'))) return
    const id = `${kind}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`
    const model = current.canvas.nodes.find(node => node.kind === 'parent') ?? current.canvas.nodes.find(node => node.kind === 'agent')
    const label = (STAGE_LABELS[current.mode] as Record<string, string>)[kind] ?? t.nodeKinds[kind]
    const node = blankNode(kind, id, label, position, model?.data, current.mode)
    if (source) { node.proxySourceId = source.id; node.data = {} }
    node.position = vacantNodePosition({ id, ...position, ...groupCardSizeOf(node) }, layoutBoxesOf(current.canvas.nodes, groupCardSizeOf))
    history.remember()
    dispatch({ type: 'NODE_ADDED', node })
    dispatch({ type: 'SELECT_NODE', id })
    scheduleGeometryAutoSave()
  }, [dispatch, history, notify, scheduleGeometryAutoSave, t])

  const copyToProxy = useCallback((): void => {
    const current = stateRef.current
    const node = current.canvas.nodes.find(item => item.id === current.selection.nodeId)
    const main = node?.kind === 'proxy' ? current.canvas.nodes.find(item => item.id === node.proxySourceId) : node
    if (!main || (main.kind !== 'parent' && main.kind !== 'agent') || !node) return
    placeBasicNode('proxy', { x: node.position.x + 270, y: node.position.y + 160 }, main.id)
    notify('info', t.toastProxyCreated)
  }, [notify, placeBasicNode, t.toastProxyCreated])

  const duplicateSelected = useCallback((): void => {
    const current = stateRef.current
    const source = current.canvas.nodes.find(node => node.id === current.selection.nodeId)
    if (!source || source.kind === 'parent' || source.kind === 'start') return
    const position = { x: source.position.x + groupCardSizeOf(source).w + 64, y: source.position.y + 40 }
    const copies = duplicateNodes(source, current.canvas.nodes, () => `node-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`, `${String(source.data.label || t.nodeKinds[source.kind])} · ${t.nodeCopySuffix}`, position)
    copies[0].position = vacantNodePosition({ id: copies[0].id, ...position, ...groupCardSizeOf(copies[0]) }, layoutBoxesOf(current.canvas.nodes, groupCardSizeOf))
    for (const member of copies.slice(1)) member.position = { x: member.position.x + copies[0].position.x - position.x, y: member.position.y + copies[0].position.y - position.y }
    history.remember()
    dispatch({ type: 'GRAPH_REPLACED', nodes: [...current.canvas.nodes, ...copies], edges: current.canvas.edges, dirty: true })
    dispatch({ type: 'SELECT_NODE', id: copies[0].id })
    scheduleGeometryAutoSave()
  }, [dispatch, history, scheduleGeometryAutoSave, t])

  // ---------- Team 成员移除 ----------
  // 先合并重复 Team 节点（memberIds 并集，且对每个组去重），得到**唯一**权威组；
  // 再从去重后的成员列表里移除该成员（一次只删一个，即使历史数据里该 id 重复出现），
  // 同时只清空目标成员的 groupId —— 杜绝「删 1 个却移出多个 / 无论点哪个都移出 2 个」。
  const removeGroupMember = useCallback((memberId: string) => {
    // 运行中锁定：已完成/执行中成员退出 Team 会改变已跑完/执行中的协作结构 → 忽略
    if (locks.isNodeLocked(memberId)) return
    const base = consolidateGroups(state.canvas.nodes)
    const member = base.find((item) => item.id === memberId)
    const groupId = member && (member.kind === 'parent' || member.kind === 'agent')
      ? (member.data.groupId as string | null | undefined) ?? null
      : null
    if (!groupId) return
    const group = base.find((item) => item.id === groupId && item.kind === 'group')
    if (!group) return
    history.remember()
    const deduped = [...new Set(Array.isArray(group.data.memberIds) ? group.data.memberIds as string[] : [])]
    const nextMembers = deduped.filter((item) => item !== memberId)
    const nodes = base.map((n) => {
      if (n.id === groupId && n.kind === 'group') return { ...n, data: { ...n.data, memberIds: nextMembers } }
      if (n.id === memberId) return { ...n, data: { ...n.data, groupId: null } }
      return n
    })
    dispatch({ type: 'GRAPH_REPLACED', nodes, edges: state.canvas.edges, dirty: true })
  }, [dispatch, history, locks, state.canvas.edges, state.canvas.nodes])

  // ---------- 交换节点左右连接点（用户批注：美化布线防交叉；状态随节点持久化） ----------
  const swapNodePorts = useCallback((id: string) => {
    const node = stateRef.current.canvas.nodes.find((item) => item.id === id)
    if (!node) return
    history.remember()
    dispatch({ type: 'NODE_DATA_PATCH', id, patch: { swapPorts: (node.data as { swapPorts?: unknown }).swapPorts !== true } })
  }, [dispatch, history])

  // face 身份固定（同 useRemote）：回调本身已按各自依赖 useCallback，
  // 这里只把「字面量每次渲染都是新对象」这一点消掉，让下游 effect 依赖保持稳定。
  return useMemo<CanvasActionsFace>(() => ({
    rememberGraph, moveNode, onNodeDragStart, onConnect, onConnectionRejected,
    tidyGraph, routeGraph, clearGraph, removeSelected, removeNodeNow, removeLine,
    placeTemplateNode, placeRoleAssetNode, placeParentNode, placeStageNode, placeGroupNode, placeGroupFromTemplate, placeTemplateIntoGroup,
    onGroupResize, addNodeToGroup, copyToProxy, duplicateSelected, placeBasicNode, removeGroupMember, swapNodePorts, setEdgeAppearance, setEdgeChannel,
  }), [
    addNodeToGroup, clearGraph, copyToProxy, duplicateSelected, placeBasicNode, moveNode, onConnect, onConnectionRejected,
    onGroupResize, onNodeDragStart, placeGroupFromTemplate, placeGroupNode, placeParentNode,
    placeRoleAssetNode, placeStageNode, placeTemplateIntoGroup, placeTemplateNode,
    rememberGraph, removeGroupMember, removeLine, removeNodeNow, removeSelected,
    swapNodePorts, tidyGraph, routeGraph, setEdgeAppearance, setEdgeChannel,
  ])
}
