// src/client/hooks/useRunControl.ts
//
// 运行控制：启动（run 端点，存在断点自动续跑）/ 停止（runStop）。
// 工作台全局化改版：运行唯一逻辑 = 运行当前实例——run 会话即实例绑定的会话
// （不再支持运行期新会话；「开启新会话」只在创建实例时经 createSession 完成）。

import type { RunSnapshot } from '../../host/shared/types.js'
import { useCallback, useEffect, useRef } from 'react'
import type { Dispatch } from 'react'
import type { StudioAction } from '../studio/studio-state.js'
import type { RemoteFace } from './useRemote.js'
import { EP } from '../lib/remote.js'

export interface RunControlFace {
  /** 运行当前实例（会话 = 实例绑定的会话；存在断点自动续跑）。 */
  startRun(sessionId: string, flowId: string): Promise<string | null>
  /** 停止运行：携带实例归属会话 id 供后端归属校验（越权会话不得停止他人运行）。 */
  stopRun(sessionId: string, runId: string): Promise<void>
}

/** 运行控制面（远端失败抛错，由调用方 toast）。 */
export function useRunControl(dispatch: Dispatch<StudioAction>, remote: RemoteFace): RunControlFace {
  const alive = useRef(true)
  const pendingStops = useRef(new Map<string, { controller: AbortController; promise: Promise<void> }>())
  useEffect(() => {
    alive.current = true
    return () => {
      alive.current = false
      for (const request of pendingStops.current.values()) request.controller.abort()
      pendingStops.current.clear()
    }
  }, [])
  const startRun = useCallback(async (sessionId: string, flowId: string) => {
    const result = await remote.call(EP.EP_RUN, { sessionId, flowId }) as { runId?: unknown; sessionId?: unknown }
    const runId = String(result?.runId ?? '')
    if (runId) {
      // runSessionId：恒等于实例绑定的会话（新逻辑 run 与实例同会话）；
      // 轮询/停止/恢复都按它归属。
      dispatch({ type: 'RUN_STARTED', runId, runSessionId: String(result?.sessionId ?? sessionId) })
    }
    return runId || null
  }, [dispatch, remote])

  const stopRun = useCallback((sessionId: string, runId: string): Promise<void> => {
    const key = `${sessionId}\u0000${runId}`
    const pending = pendingStops.current.get(key)
    if (pending) return pending.promise
    const controller = new AbortController()
    dispatch({ type: 'RUN_STOP_REQUESTED', sessionId, runId })
    const promise = (async () => {
      await remote.call(EP.EP_RUN_STOP, { sessionId, runId }, { signal: controller.signal })
      if (controller.signal.aborted) return
      const snapshot = await remote.call(EP.EP_RUN_STATUS, { sessionId, runId }, { signal: controller.signal }) as RunSnapshot
      if (alive.current && !controller.signal.aborted) dispatch({ type: 'RUN_SNAPSHOT', snapshot })
    })().finally(() => {
      pendingStops.current.delete(key)
      if (alive.current) dispatch({ type: 'RUN_STOP_SETTLED', sessionId, runId })
    })
    pendingStops.current.set(key, { controller, promise })
    return promise
  }, [dispatch, remote])

  return { startRun, stopRun }
}
