// src/client/components/canvas/NodeEditToolbar.tsx

import type { Dict } from '../../i18n.js'

export function NodeEditToolbar({ copy, x, y, canCopy, canReference, locked, onCopy, onReference, onDelete, onClose }: {
  copy: Dict; x: number; y: number; canCopy: boolean; canReference: boolean; locked: boolean
  onCopy(): void; onReference(): void; onDelete(): void; onClose(): void
}) {
  return <div className="wf-node-toolbar" role="toolbar" aria-label={copy.nodeQuickActions} style={{ left: x, top: y }} onPointerDown={event => event.stopPropagation()}>
    <button type="button" disabled={!canCopy} onClick={onCopy}>{copy.nodeDuplicate}</button>
    <button type="button" disabled={!canReference} onClick={onReference}>{copy.nodeReference}</button>
    <button type="button" className="is-danger" disabled={locked} onClick={onDelete}>{copy.inspectorDelete}</button>
    <button type="button" aria-label={copy.closeNodeActions} onClick={onClose}>×</button>
  </div>
}
