// src/client/components/toolbar/Toolbar.tsx
//
// 画布控制栏：
// 撤销 / 重做 / 清空 / 整理布局 / 保存 / 运行·停止（模式二 = 启动·停止服务 + 状态指示）/ 运行历史。
//
// 画布上方「保存」按钮按当前对象态动态命名——模板态 = 「创建实例/创建服务」
// （将画布内容保存为新实例，模板不变），实例态 = 「保存实例/保存服务」（保存到当前实例）。
//
// 工作台全局化改版：「开启新会话」仅实例来源态显示。工作区路径不再由工作流模板设置，
// 统一在具体实例的设置侧栏（会话工作目录）中维护，避免模板级路径与实际实例漂移。

import type { Dict } from '../../i18n.js'
import { useEffect, useId, useRef, useState } from 'react'
import type { AutoLayoutGraphOptions } from '../../lib/auto-layout-graph.js'

export interface ToolbarProps {
  copy: Dict
  mode: 'mode1' | 'mode2'
  /** 两侧侧栏是否都已折叠（顶部一键折叠/展开按钮用；批注：折叠时不显示拖动线）。 */
  panelsCollapsed: boolean
  /** 顶部一键折叠/展开左右侧栏回调。 */
  onTogglePanels(): void
  /** 当前画布对象态（模板态显示「创建实例/创建服务」；实例态显示「保存实例/保存服务」）。 */
  saveLabel: string
  onUndo(): void
  onRedo(): void
  onClear(): void
  canClear: boolean
  /** 「清空」按钮悬停说明（运行中禁用时提示先停止运行）。 */
  clearTitle: string
  onTidy(options?: AutoLayoutGraphOptions): void
  canTidy: boolean
  onRoute(): void
  canRoute: boolean
  hasAutomaticReferences?: boolean
  onSave(): void
  canSave: boolean
  running: boolean
  stopping?: boolean
  canContinue?: boolean
  onStop(): void
  onRun(): void
  onOpenHistory(): void
  canHistory: boolean
  serviceStatus: { port?: number; status?: string } | null
  /** 「开启新会话」是否显示（仅实例来源态；实例态不显示——实例只认绑定会话运行）。 */
  showNewSession: boolean
  /** 「开启新会话」选项：模板态来自模板持久化字段；资产态为一次性临时选项（路径恒空）。 */
  instanceOptions: { newSession: boolean; workspacePath?: string }
  /** 临时选项/模板配置变更回调（模板态由上层立即保存模板，资产态写临时状态）。 */
  onInstanceOptionsChange(patch: { newSession?: boolean; workspacePath?: string }): void
  onEditWorkingDirectory?(): void
}

export function Toolbar(props: ToolbarProps) {
  const {
    copy: t, mode, panelsCollapsed, onTogglePanels, saveLabel, onUndo, onRedo, onClear, canClear, clearTitle, onTidy, canTidy,
    onRoute, canRoute, onSave, canSave, running, stopping, canContinue, onStop, onRun, onOpenHistory, canHistory, serviceStatus,
    showNewSession, instanceOptions, onInstanceOptionsChange, onEditWorkingDirectory,
  } = props
  const isMode2 = mode === 'mode2'
  const [autoReferences, setAutoReferences] = useState(Boolean(props.hasAutomaticReferences))
  const layoutBubbleId = useId()
  const layoutBubbleRef = useRef<HTMLDivElement>(null)
  const bubbleTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const cancelBubbleClose = (): void => { if (bubbleTimer.current) clearTimeout(bubbleTimer.current); bubbleTimer.current = null }
  const showLayoutBubble = (): void => { cancelBubbleClose(); layoutBubbleRef.current?.showPopover?.() }
  const closeLayoutBubble = (): void => { cancelBubbleClose(); layoutBubbleRef.current?.hidePopover?.() }
  const scheduleBubbleClose = (): void => {
    cancelBubbleClose()
    bubbleTimer.current = setTimeout(() => { bubbleTimer.current = null; layoutBubbleRef.current?.hidePopover?.() }, 160)
  }
  useEffect(() => () => { if (bubbleTimer.current) clearTimeout(bubbleTimer.current) }, [])
  // 运行状态指示（控制栏最右侧）：模式二含服务状态（停止/启动中/运行中·端口/崩溃）
  const statusText = isMode2 && serviceStatus
    ? serviceStatus.status === 'running'
      ? (serviceStatus.port ? `${t.serviceRunning} · ${serviceStatus.port}` : t.serviceStarting)
      : serviceStatus.status === 'crashed'
        ? t.serviceCrashed
        : t.serviceStopped
    : null
  const statusRunning = serviceStatus?.status === 'running'

  return (
    <div className="wf-toolbar">
      {/* 批注：顶部一键折叠/展开左右侧栏（两侧联动；折叠时隐藏拖动线、不能拖出，展开后才可拖宽） */}
      <button
        type="button"
        className={`wf-btn wf-iconbtn is-ghost wf-toolbar__panels${panelsCollapsed ? ' is-collapsed' : ''}`}
        title={t.togglePanels}
        aria-label={t.togglePanels}
        onClick={onTogglePanels}
      >
        <svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true" style={{ color: 'currentColor' }}>
          <path fill="none" stroke="currentColor" strokeWidth="2" d="M4 5h16a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1z" />
          <path fill="none" stroke="currentColor" strokeWidth="2" d="M9 5v14M15 5v14" />
        </svg>
      </button>
      <button type="button" className="wf-btn wf-iconbtn is-ghost" title={`${t.undo} · Ctrl/Cmd+Z`} aria-label={t.undo} onClick={onUndo}>↶</button>
      <button type="button" className="wf-btn wf-iconbtn is-ghost" title={`${t.redo} · Ctrl/Cmd+Shift+Z`} aria-label={t.redo} onClick={onRedo}>↷</button>
      <button type="button" className="wf-btn is-ghost" title={clearTitle} onClick={onClear} disabled={!canClear}>{t.clear}</button>
      <div className="wf-layout-control" onPointerEnter={showLayoutBubble} onPointerLeave={scheduleBubbleClose}
        onBlurCapture={event => { if (!event.currentTarget.contains(event.relatedTarget as Node | null)) scheduleBubbleClose() }}
        onKeyDown={event => { if (event.key === 'Escape') { event.stopPropagation(); closeLayoutBubble() } }}>
        <button type="button" className="wf-btn is-ghost wf-layout-anchor" title={t.tidy} aria-controls={layoutBubbleId}
          onFocus={showLayoutBubble} onClick={() => onTidy({ autoReferences: autoReferences && !running })} disabled={!canTidy}>{t.tidy}</button>
        <div id={layoutBubbleId} ref={layoutBubbleRef} className="wf-layout-popover" popover="manual" role="group" aria-label={t.autoLayoutOptions}
          onPointerEnter={cancelBubbleClose} onPointerLeave={scheduleBubbleClose}>
          <label className="wf-layout-options" title={t.autoLayoutReferencesHint}>
            <input type="checkbox" checked={autoReferences} onChange={event => setAutoReferences(event.target.checked)} disabled={running || !canTidy} />
            <span>{t.autoLayoutReferences}</span>
          </label>
        </div>
      </div>
      <button type="button" className="wf-btn is-ghost" title={t.autoRouteHint} onClick={onRoute} disabled={!canRoute}>{t.autoRoute}</button>
      <button type="button" className="wf-btn" onClick={onSave} disabled={!canSave}>{saveLabel}</button>
      {running || stopping
        ? <button type="button" className="wf-btn is-danger" onClick={onStop} disabled={stopping} aria-busy={Boolean(stopping)}>{stopping ? t.stoppingRun : t.stop}</button>
        : <button type="button" className="wf-btn is-primary" onClick={onRun} disabled={!canSave}>{isMode2 ? t.startService : canContinue ? t.continueRun : t.run}</button>}
      <button type="button" className="wf-btn is-ghost" onClick={onOpenHistory} disabled={!canHistory}>{t.history}</button>
      {onEditWorkingDirectory ? <button type="button" className="wf-btn is-ghost" onClick={onEditWorkingDirectory}><svg width="14" height="14" viewBox="0 0 24 24" aria-hidden="true"><path fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" d="M3 8V5a2 2 0 0 1 2-2h4l2 3h8a2 2 0 0 1 2 2v2M3 8h18l-3 12H5L2 10a2 2 0 0 1 1-2Z" /></svg><span>{t.sessionWorkingDirectory}</span></button> : null}
      {statusText ? <span className={`wf-status${statusRunning ? ' is-running' : ''}`}>{statusText}</span> : null}
      {/* 开启新会话（仅实例来源态显示）：模板态 = 模板级持久化配置（随模板保存/删除）；
          资产态 = 一次性临时选项（资产无持久化归属，无路径选择）。实例态不显示：
          实例运行只认实例绑定的会话，无「新会话」概念 */}
      {showNewSession
        ? (
            <label className="wf-toolbar__switch" title={t.newSessionHint}>
              <input
                type="checkbox"
                checked={instanceOptions.newSession}
                onChange={(event) => onInstanceOptionsChange({ newSession: event.target.checked })}
              />
              <span>{t.newSession}</span>
            </label>
          )
        : null}
    </div>
  )
}
