// src/client/components/panels/inspector/Inspector.tsx
//
// 右侧属性面板：
// 所见即所操作——点击模板编辑模板、点击画布节点编辑节点实例、点击连线编辑连线；
// 底部保存/删除作用于当前选中对象；阶段无保存（只读）；虚拟节点只读。
// 底部按钮分录（用户裁决）：模版态 = 保存/删除/入库；资产态 = 保存/归档（历史资产为
// 「恢复」）/回滚；提示词资产 = 保存/回滚（必须保持活跃，无归档/恢复）；
// 经验 = 保存/归档（已归档为「恢复」），**没有回滚**（经验无版本控制）；
// 其余（实例/服务/节点/连线）= 保存/删除（+ 角色节点的复制、实例的另存为模板）。
//
// 按钮职责（用户批注，本文件是唯一判定点）：
//   - 「归档 / 恢复」管**状态转换**（资产与经验同口径）：活跃 → 归档、已归档 → 恢复；
//   - 「回滚」只管**版本与 Active 指针**：因此只对活跃资产（与绑定来源资产的画布角色节点）
//     显示；历史资产不再提供回滚入口（恢复后再回滚），经验无版本故永不显示。

import { useState } from 'react'
import type { Dict } from '../../../i18n.js'
import type { EditorData, StudioState } from '../../../studio/studio-state.js'
import type { WorkflowTemplate } from '../../../../host/shared/graph-model.js'
import { RoleForm } from './role-form.js'
import { TaskForm } from './task-form.js'
import { DatabaseForm } from './database-form.js'
import { GroupForm, ProxyForm, StageForm } from './node-forms.js'
import { SubgraphForm } from './subgraph-form.js'
import { LinePanel, WorkflowForm } from './flow-forms.js'
import { AssetVersions } from './asset-versions.js'
import { ExperienceForm } from './experience-form.js'
import { PromptAssetForm } from './prompt-asset-form.js'
import { stageNodeLabelOf } from '../../../lib/graph-handles.js'

export interface InspectorProps {
  copy: Dict
  open: boolean
  width: number
  editorData: EditorData | null
  presets: Array<{ id: string; name?: string }>
  models: Array<{ provider: string; model: string; efforts?: Array<{ id: string; name: string }> }>
  combos: Array<{ id: string; name: string; tools?: string[]; mcpServers?: string[] }>
  flowMeta: { nodeCount: number; revision: number }
  /** 模板列表：子图属性栏从已有工作流模板导入内部结构。 */
  flowTemplates?: WorkflowTemplate[]
  onPatch(patch: Record<string, unknown>): void
  onDelete(): void
  onSave(): void
  /** 侧栏左下角收起按钮；不传则隐藏。 */
  onCollapse?(): void
  /** 宿主当前子智能体并行上限（动态团队提示用）。 */
  maxActiveSubagents?: number
  /** 实例 → 模板（另存为模板）。 */
  onSaveAsTemplate?(): void
  /** 工作流模板 → 复制为新模板。 */
  onDuplicateTemplate?(): void
  /** 模版 → 资产入库（工作流模版 / 角色模版；先保存模版，失败即中止）。 */
  onPromote?(): void
  /** 入库按钮锁定：已入库且模版内容未再修改（纯函数判定由调用方给出）。 */
  promoteLocked?: boolean
  /** 打开资产版本上拉列表（资产态回滚选择）。 */
  onOpenVersions?(): void
  /** 回滚 Active 指针到所选历史版本。 */
  onRollbackVersion?(versionId: number): void
  /** 收起版本列表（清空版本数据面）。 */
  onCloseVersions?(): void
  /** 已装载的版本列表（null = 未打开/装载中）。 */
  assetVersions?: StudioState['assetVersions']
  onCopyProxy(): void
  onRemoveMember(memberId: string): void
  onFilesPicked(files: File[]): void
  onLoadMd(): void
  /** 协作 Prompt 从 .md 加载（与角色 System Prompt 一致）。 */
  onLoadGroupMd(): void
  onTestDb(): void
  saveDisabled: boolean
  importBusy: boolean
}

export function Inspector(props: InspectorProps) {
  const {
    copy: t, open, width, editorData, presets, models, combos, flowMeta, flowTemplates = [],
    onPatch, onDelete, onSave, onCollapse, maxActiveSubagents, onSaveAsTemplate, onDuplicateTemplate, onPromote, promoteLocked, onOpenVersions, onRollbackVersion, onCloseVersions, assetVersions,
    onCopyProxy, onRemoveMember, onFilesPicked, onLoadMd, onLoadGroupMd, onTestDb,
    saveDisabled, importBusy,
  } = props
  // 版本上拉列表的展开/收起属瞬时渲染态（数据面在状态机；收起不丢业务事实）。
  // 记住「为哪个资产展开」：切换编辑对象后列表自动视为收起，避免展示上一个资产的版本。
  const [versionsAssetId, setVersionsAssetId] = useState<string | null>(null)

  let content: React.ReactNode
  if (!editorData) {
    content = <div className="wf-empty">{t.inspectorEmpty}</div>
  } else {
    const data = editorData.data
    switch (editorData.kind) {
      case 'workflow':
      case 'service':
        content = <WorkflowForm data={data} copy={t} isService={editorData.kind === 'service'} flowMeta={flowMeta} onPatch={onPatch} />
        break
      case 'role':
        // 父代理属性：模板层与画布节点都可编辑属性，不再显示「父代理模板无独立属性」空态。
        // 模式（presetId）下拉对父/子代理一律可编辑：官方只在工作流运行开始前读取该选择，
        // 运行中改动不影响行为（用户裁决），故不锁死。两件独立的事：
        //   - 谁可编辑 presetId：父代理与子代理都可编辑；
        //   - 谁可见 combo（工具组合）：只有子代理（父代理只能用官方 preset）。
        content = (
          <RoleForm
            data={data}
            copy={t}
            presets={presets}
            models={models}
            combos={combos}
            onPatch={onPatch}
            onLoadMd={onLoadMd}
            isParent={editorData.isParent === true}
            showCombos={editorData.isParent !== true}
          />
        )
        break
      case 'task':
        content = <TaskForm data={data} copy={t} onPatch={onPatch} onFilesPicked={onFilesPicked} contentLabel={String(t.promptContent)} />
        break
      case 'step':
        content = <TaskForm data={data} copy={t} onPatch={onPatch} onFilesPicked={onFilesPicked} heading={String(t.nodeKinds.step)} contentLabel={String(t.stepContent)} />
        break
      case 'database':
        content = <DatabaseForm data={data} copy={t} onPatch={onPatch} onTest={onTestDb} />
        break
      case 'group':
        content = <GroupForm data={data} copy={t} members={editorData.members} onPatch={onPatch} onLoadMd={onLoadGroupMd} onRemoveMember={onRemoveMember} maxActiveSubagents={maxActiveSubagents} />
        break
      case 'stage': {
        // 阶段名按当前界面语言渲染；存储值仍是中文规范值（由保存路径保证）。
        const stageLabel = editorData.stageKind
          ? stageNodeLabelOf(editorData.mode ?? 'mode1', editorData.stageKind, t.nodeKinds)
          : String(data.label ?? '')
        content = <StageForm copy={t} nodeLabel={stageLabel} />
        break
      }
      case 'proxy':
        content = <ProxyForm data={data} copy={t} onPatch={onPatch} mainLabel={editorData.mainLabel ?? ''} />
        break
      case 'subgraph':
        content = <SubgraphForm data={data} copy={t} mode={editorData.mode ?? 'mode1'} flowTemplates={flowTemplates} onPatch={onPatch} />
        break
      case 'edge':
        content = <LinePanel data={data} copy={t} onPatch={onPatch} />
        break
      case 'experience':
        content = <ExperienceForm data={data} copy={t} onPatch={onPatch} />
        break
      case 'prompt':
        content = <PromptAssetForm data={data} copy={t} onPatch={onPatch} />
        break
      default:
        content = <div className="wf-empty">{t.inspectorEmpty}</div>
    }
  }

  // 底部按钮规则（所见即所操作）
  /**
   * 可回滚对象 id：资产自身（属性栏编辑的资产），或**画布角色节点**绑定的来源角色资产。
   * 画布节点是该资产的画布内联副本（data.sourceAssetId 是绑定事实），批注要求它与左侧栏
   * 角色资产具备同样的回滚能力；未绑定来源资产的内联节点没有版本可回滚，故不显示回滚按钮。
   * 计算放在渲染分支之外：版本列表的显示判据也要用它。
   */
  const nodeSourceAssetId = editorData?.sourceAssetId ?? ''
  const rollbackAssetId = (editorData?.assetId ?? '') !== '' ? editorData!.assetId! : nodeSourceAssetId
  /** 经验编辑对象：经验没有版本控制，一切与版本相关的按钮（回滚 / 版本列表）都不出现。 */
  const isExperienceEditor = editorData?.experience === true
  /** 提示词资产编辑对象：只有正文可编辑；可保存新版本与回滚，但没有归档 / 恢复入口。 */
  const isPromptEditor = editorData?.promptAsset === true
  /** 已归档（历史资产 / 非活跃经验）：状态按钮翻转为「恢复」，版本列表一律收起。 */
  const isRetiredEditor = editorData?.retired === true

  const footer: React.ReactNode[] = []
  if (editorData) {
    const kind = editorData.kind
    const isStage = kind === 'stage'
    // 资产态（工作流 / 角色 / 提示词资产）：保存 = 登记新版本；经验：保存 = 就地更新（无版本）
    const isAsset = editorData.asset === true || editorData.roleAsset === true || isPromptEditor
    // 归档 / 恢复只管状态转换，回滚只管版本与指针：历史资产与经验都不给回滚入口
    const canRollback = !isExperienceEditor && !isRetiredEditor && rollbackAssetId !== ''
      && (isAsset || (kind === 'role' && editorData.template !== true && nodeSourceAssetId !== ''))
    // 展开态只在「仍编辑着同一个回滚对象」时成立（编辑器切换即自动收起）
    const versionsOpen = versionsAssetId !== null && versionsAssetId === rollbackAssetId
    // 复制按钮：画布角色节点（含父代理节点）可创建虚拟节点；
    // 模板与父代理模板不可复制，角色资产与经验（都不在画布上）同样不可复制
    const canCopyProxy = kind === 'role' && !editorData.template && !isAsset
    // 入库：仅工作流模版与角色模版（任务/数据库/Team 模板不显示；资产态与经验不显示）
    const canPromote = !isAsset && !isExperienceEditor && editorData.template === true && (kind === 'workflow' || kind === 'role') && onPromote !== undefined
    if (!isStage) {
      footer.push(
        <button key="save" type="button" className="wf-btn is-primary" onClick={onSave} disabled={importBusy || saveDisabled}>
          {t.inspectorSave}
        </button>,
      )
    }
    // 工作流模板复制：模板态新增的显式入口（与实例「另存为模板」互补）。
    const canCopyTemplate = !isAsset && !isExperienceEditor && editorData.template === true && kind === 'workflow' && onDuplicateTemplate !== undefined
    if (canCopyTemplate) {
      footer.push(
        <button key="copy-template" type="button" className="wf-btn" onClick={onDuplicateTemplate} disabled={importBusy}>
          {t.copyTemplate}
        </button>,
      )
    }
    if (isAsset || isExperienceEditor) {
      // 状态转换按钮（唯一入口）：活跃 → 归档；已归档 → 恢复。两种状态都可点，不再置灰。
      // 提示词资产必须保持活跃，故不提供该按钮，也不回落到「删除」。
      if (!isPromptEditor) {
        footer.push(
          <button
            key="retire"
            type="button"
            className={`wf-btn${isRetiredEditor ? '' : ' is-danger'}`}
            onClick={onDelete}
            disabled={importBusy}
            title={isExperienceEditor
              ? (isRetiredEditor ? t.experienceRestoreHint : t.experienceArchiveHint)
              : (isRetiredEditor ? t.assetRestoreHint : t.assetArchiveHint)}
          >
            {isRetiredEditor ? t.assetRestore : t.assetArchive}
          </button>,
        )
      }
    } else {
      footer.push(
        <button key="delete" type="button" className="wf-btn is-danger" onClick={onDelete} disabled={importBusy}>
          {t.inspectorDelete}
        </button>,
      )
    }
    if (canPromote) {
      footer.push(
        <button
          key="promote"
          type="button"
          className="wf-btn"
          onClick={onPromote}
          disabled={importBusy || promoteLocked === true}
          title={promoteLocked === true ? t.assetPromoteLockedHint : t.assetPromoteHint}
        >
          {t.assetPromote}
        </button>,
      )
    }
    // 回滚（展开版本列表）：活跃资产与「绑定来源资产的画布角色节点」显示；历史资产、经验、模版态不显示
    if (canRollback && onOpenVersions) {
      footer.push(
        <button
          key="rollback"
          type="button"
          className="wf-btn"
          onClick={() => {
            if (versionsOpen) {
              setVersionsAssetId(null)
              onCloseVersions?.()
              return
            }
            setVersionsAssetId(rollbackAssetId)
            onOpenVersions()
          }}
          disabled={importBusy}
          title={t.assetRollbackHint}
        >
          {t.assetRollback}
        </button>,
      )
    }
    if (canCopyProxy) {
      footer.push(
        <button key="copy" type="button" className="wf-btn" onClick={onCopyProxy} disabled={importBusy}>
          {t.inspectorCopy}
        </button>,
      )
    }
    // 实例态（工作流/服务实例）提供「另存为模板」——当前实例内容
    // 复制为全局共享的工作流模板（模板库 + 号也能新建空白模板，二者均可）。
    if ((kind === 'workflow' || kind === 'service') && !editorData.template && !isAsset && onSaveAsTemplate) {
      footer.push(
        <button key="save-as-template" type="button" className="wf-btn" onClick={onSaveAsTemplate} disabled={importBusy}>
          {String(t.saveAsTemplate)}
        </button>,
      )
    }
  }

  // 版本列表只在「活跃资产 / 绑定来源资产的画布角色节点」上出现：经验无版本，
  // 已归档对象的状态转换走「恢复」，两者都不在此列出（与回滚按钮同判据）。
  const showVersions = !isExperienceEditor && !isRetiredEditor
    && versionsAssetId !== null && rollbackAssetId !== '' && versionsAssetId === rollbackAssetId
    && (editorData?.asset === true || editorData?.roleAsset === true || editorData?.promptAsset === true
      || editorData?.sourceAssetId !== undefined)

  const collapseButton = onCollapse
    ? (
        <button
          key="collapse"
          type="button"
          className="wf-inspector__collapse"
          title={String(t.inspectorCollapse)}
          aria-label={String(t.inspectorCollapse)}
          onClick={onCollapse}
        >
          ›
        </button>
      )
    : null

  return (
    <aside className={`wf-inspector${open ? '' : ' is-collapsed'}`} style={{ width: open ? width : undefined }}>
      <div className="wf-inspector__scroll">{content}</div>
      {footer.length > 0 || collapseButton
        ? (
            <div className="wf-inspector__footer">
              {collapseButton}
              {footer}
              {showVersions
                ? (
                    <AssetVersions
                      copy={t}
                      versions={assetVersions ?? null}
                      assetId={rollbackAssetId}
                      onClose={() => { setVersionsAssetId(null); onCloseVersions?.() }}
                      onRollback={(versionId) => { setVersionsAssetId(null); onRollbackVersion?.(versionId) }}
                    />
                  )
                : null}
            </div>
          )
        : null}
    </aside>
  )
}

