// src/client/lib/bezier-path.ts

import { simplifyRoute } from './orthogonal-routing.js'
import type { RouteBox, RoutePoint } from './orthogonal-routing.js'

export interface BezierSpan { start: RoutePoint; c1: RoutePoint; c2: RoutePoint; end: RoutePoint }
export interface BezierRoute { path: string; anchors: RoutePoint[]; spans: BezierSpan[] }

const distance = (a: RoutePoint, b: RoutePoint): number => Math.hypot(a.x - b.x, a.y - b.y)
const midpoint = (a: RoutePoint, b: RoutePoint): RoutePoint => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 })

function lineHits(a: RoutePoint, b: RoutePoint, box: RouteBox): boolean {
  let low = 0, high = 1
  for (const [origin, delta, minimum, maximum] of [[a.x, b.x - a.x, box.x, box.x + box.w], [a.y, b.y - a.y, box.y, box.y + box.h]]) {
    if (Math.abs(delta) < 0.0001) { if (origin <= minimum || origin >= maximum) return false; continue }
    const p = (minimum - origin) / delta, q = (maximum - origin) / delta
    low = Math.max(low, Math.min(p, q)); high = Math.min(high, Math.max(p, q))
    if (low >= high - 0.0001) return false
  }
  return high > 0.0001 && low < 0.9999
}

/** Subdivision checks the entire curve; control points alone do not establish collision freedom. */
function curveHits(span: BezierSpan, box: RouteBox, depth = 0): boolean {
  const points = [span.start, span.c1, span.c2, span.end]
  const left = Math.min(...points.map(p => p.x)), right = Math.max(...points.map(p => p.x))
  const top = Math.min(...points.map(p => p.y)), bottom = Math.max(...points.map(p => p.y))
  if (right <= box.x || left >= box.x + box.w || bottom <= box.y || top >= box.y + box.h) return false
  if (depth >= 9 || Math.max(right - left, bottom - top) < 0.5) return lineHits(span.start, span.end, box)
  const a = midpoint(span.start, span.c1), b = midpoint(span.c1, span.c2), c = midpoint(span.c2, span.end)
  const d = midpoint(a, b), e = midpoint(b, c), m = midpoint(d, e)
  return curveHits({ start: span.start, c1: a, c2: d, end: m }, box, depth + 1)
    || curveHits({ start: m, c1: e, c2: c, end: span.end }, box, depth + 1)
}

function terminal(a: RoutePoint, b: RoutePoint): RoutePoint {
  const length = distance(a, b), tail = Math.min(24, length / 3)
  return length ? { x: a.x + (b.x - a.x) * tail / length, y: a.y + (b.y - a.y) * tail / length } : a
}

/** Interpolating cubic spans run across the full connection, with only two straight terminal shafts. */
export function bezierRoutePath(raw: RoutePoint[], manual: RoutePoint[] = [], obstacles: RouteBox[] = [], manualMode = false): BezierRoute {
  const route = simplifyRoute(raw)
  if (route.length < 2) return { path: route.length ? `M ${route[0].x} ${route[0].y}` : '', anchors: [], spans: [] }
  const first = route[0], last = route.at(-1)!
  const start = terminal(first, route[1]), end = terminal(last, route.at(-2)!)
  const boxes = obstacles.map(b => ({ ...b, x: b.x - 3, y: b.y - 3, w: b.w + 6, h: b.h + 6 }))
  const free = (a: RoutePoint, b: RoutePoint): boolean => boxes.every(box => !lineHits(a, b, box))
  // Explicit anchors own the curve when their connecting corridor is clear.
  const explicit = [start, ...manual, end]
  let anchors: RoutePoint[]
  if ((manual.length || manualMode) && explicit.slice(1).every((p, i) => free(explicit[i], p))) anchors = explicit
  else {
    const core = [start, ...route.slice(1, -1), end]
    anchors = [start]
    for (let i = 1; i < core.length - 1; i++) {
      const a = core[i - 1], p = core[i], b = core[i + 1]
      const fixed = manual.some(m => distance(m, p) < 0.5)
      const candidate = fixed ? p : { x: (a.x + p.x * 2 + b.x) / 4, y: (a.y + p.y * 2 + b.y) / 4 }
      anchors.push(free(anchors.at(-1)!, candidate) && free(candidate, b) ? candidate : p)
    }
    anchors.push(end)
  }
  anchors = anchors.filter((p, i) => !i || distance(p, anchors[i - 1]) > 0.1)
  if (!manual.length && !manualMode) for (let i = 1; i < anchors.length - 1; i++) {
    const a = anchors[i - 1], p = anchors[i], b = anchors[i + 1]
    const dx = b.x - a.x, dy = b.y - a.y, length = Math.hypot(dx, dy)
    const projection = ((p.x - a.x) * dx + (p.y - a.y) * dy) / (length * length || 1)
    const deviation = Math.abs((p.x - a.x) * dy - (p.y - a.y) * dx) / (length || 1)
    if (projection >= 0 && projection <= 1 && (deviation < 8 || distance(a, p) < 28 || distance(p, b) < 28) && free(a, b)) { anchors.splice(i, 1); i = Math.max(0, i - 1) }
  }
  if (!manualMode && anchors.length === 2 && distance(start, end) > 48) anchors.splice(1, 0, midpoint(start, end))
  const tangents = anchors.map((p, i) => {
    const previous = anchors[i - 1] ?? first, next = anchors[i + 1] ?? last
    let v = i === 0 ? { x: p.x - first.x, y: p.y - first.y } : i === anchors.length - 1 ? { x: last.x - p.x, y: last.y - p.y } : { x: next.x - previous.x, y: next.y - previous.y }
    const length = Math.hypot(v.x, v.y), extent = Math.min(distance(p, previous), distance(p, next)) / 2
    const scale = length ? Math.min(extent, distance(previous, next) / 6) / length : 0
    v = { x: v.x * scale, y: v.y * scale }; return v
  })
  const factors = anchors.map(() => 1)
  const spanOf = (index: number): BezierSpan => ({ start: anchors[index], end: anchors[index + 1],
    c1: { x: anchors[index].x + tangents[index].x * factors[index], y: anchors[index].y + tangents[index].y * factors[index] },
    c2: { x: anchors[index + 1].x - tangents[index + 1].x * factors[index + 1], y: anchors[index + 1].y - tangents[index + 1].y * factors[index + 1] } })
  // Share each anchor's tangent between adjacent spans, preserving a smooth join while tightening clearance.
  for (let attempt = 0; attempt < 10; attempt++) {
    let changed = false
    for (let i = 0; i < anchors.length - 1; i++) if (boxes.some(box => curveHits(spanOf(i), box))) {
      factors[i] *= 0.4; factors[i + 1] *= 0.4; changed = true
    }
    if (!changed) break
  }
  const spans = anchors.slice(1).map((_, i) => spanOf(i))
  const path = [`M ${first.x} ${first.y}`, `L ${start.x} ${start.y}`, ...spans.map(s => `C ${s.c1.x} ${s.c1.y} ${s.c2.x} ${s.c2.y} ${s.end.x} ${s.end.y}`), `L ${last.x} ${last.y}`].join(' ')
  return { path, anchors: manualMode ? manual : anchors.slice(1, -1), spans }
}

export function sampleBezier(span: BezierSpan, t: number): RoutePoint {
  const u = 1 - t
  return { x: u ** 3 * span.start.x + 3 * u * u * t * span.c1.x + 3 * u * t * t * span.c2.x + t ** 3 * span.end.x,
    y: u ** 3 * span.start.y + 3 * u * u * t * span.c1.y + 3 * u * t * t * span.c2.y + t ** 3 * span.end.y }
}
