// src/client/lib/edge-path.ts

import type { RoutePoint } from './orthogonal-routing.js'
import { simplifyRoute } from './orthogonal-routing.js'
import { bezierRoutePath } from './bezier-path.js'

/** One continuous path: remove duplicate/reversing collinear points before rounding corners. */
export function edgeDisplayPath(raw: RoutePoint[], type: 'rounded' | 'bezier' = 'rounded'): string {
  if (type === 'bezier') return bezierRoutePath(raw).path
  const points = simplifyRoute(raw)
  if (!points.length) return ''
  const text: string[] = [`M ${points[0].x} ${points[0].y}`]
  const radius = 10
  for (let i = 1; i < points.length - 1; i++) {
    const a = points[i - 1], b = points[i], c = points[i + 1]
    const incoming = Math.hypot(b.x - a.x, b.y - a.y), outgoing = Math.hypot(c.x - b.x, c.y - b.y)
    // Preserve a visible straight shaft behind the 12px arrow, also on broad Bezier corners.
    const r = Math.max(0, Math.min(radius, incoming / 2, outgoing / 2, i === 1 ? incoming - 24 : Infinity, i === points.length - 2 ? outgoing - 24 : Infinity))
    const before = { x: b.x + (a.x - b.x) * r / incoming, y: b.y + (a.y - b.y) * r / incoming }
    const after = { x: b.x + (c.x - b.x) * r / outgoing, y: b.y + (c.y - b.y) * r / outgoing }
    text.push(`L ${before.x} ${before.y}`)
    text.push(`Q ${b.x} ${b.y} ${after.x} ${after.y}`)
  }
  const last = points.at(-1)!; text.push(`L ${last.x} ${last.y}`)
  return text.join(' ')
}
