// src/client/lib/subgraph.ts
//
// 子图节点的客户端辅助：默认起止图、模板结构导入、图结构读取。
// 纯函数（除随机 id 生成外）：不读 DOM、不读全局状态，便于测试。

import { STAGE_LABELS } from '../../host/shared/protocol.js'
import type { GraphNode, Line, SubgraphNode, WorkflowMode, WorkflowTemplate } from '../../host/shared/graph-model.js'

/** 子图内部图的最小形状。 */
export interface SubgraphGraphSnapshot {
  nodes: GraphNode[]
  lines: Line[]
}

/** 读取节点内部的子图结构（非子图/损坏数据返回 null）。 */
export function subgraphGraphOf(node: { kind?: string; data?: Record<string, unknown> } | null | undefined): SubgraphGraphSnapshot | null {
  if (!node || node.kind !== 'subgraph') return null
  const graph = node.data?.graph as SubgraphGraphSnapshot | undefined
  if (!graph || !Array.isArray(graph.nodes) || !Array.isArray(graph.lines)) return null
  return graph
}

/** 子图是否为合法的最小完整图（恰一个 start，至少一个 end）。 */
export function subgraphCompleteness(graph: SubgraphGraphSnapshot | null): { starts: number; ends: number; ok: boolean } {
  const nodes = graph?.nodes ?? []
  const starts = nodes.filter((node) => node.kind === 'start').length
  const ends = nodes.filter((node) => node.kind === 'end').length
  return { starts, ends, ok: starts === 1 && ends >= 1 }
}

/** 新子图的最小起止图（与 host 工厂保持相同语义；客户端不能 import host 运行时工厂）。 */
export function defaultSubgraphGraph(mode: WorkflowMode): SubgraphGraphSnapshot {
  const startId = `node-${Math.random().toString(36).slice(2, 10)}`
  const endId = `node-${Math.random().toString(36).slice(2, 10)}`
  return {
    nodes: [
      { id: startId, kind: 'start', position: { x: 60, y: 100 }, data: { label: STAGE_LABELS[mode].start } },
      { id: endId, kind: 'end', position: { x: 360, y: 100 }, data: { label: STAGE_LABELS[mode].end } },
    ],
    lines: [{ id: `line-${Math.random().toString(36).slice(2, 10)}`, source: startId, target: endId, sourceHandle: 'flow-out', targetHandle: 'flow-in' }],
  }
}

/**
 * 复制一个工作流模板的图作为子图内容。
 * 所有节点/连线 id 重新生成，并同步重写 groupId / memberIds / proxySourceId；
 * 模板中的阶段标签按目标模式归一，防止 mode2 的「输入/输出」进入 mode1。
 */
export function importSubgraphFromTemplate(template: WorkflowTemplate, mode: WorkflowMode): SubgraphGraphSnapshot {
  if (template.nodes.some((node) => node.kind === 'subgraph')) {
    throw new Error('The template contains a subgraph node; nested subgraphs are not supported.')
  }
  const idMap = new Map<string, string>()
  for (const node of template.nodes) idMap.set(node.id, `node-${Math.random().toString(36).slice(2, 10)}`)
  const nodes = template.nodes.map((node) => {
    const copy = structuredClone(node) as GraphNode
    copy.id = idMap.get(node.id) ?? node.id
    if (copy.kind === 'start' || copy.kind === 'end' || copy.kind === 'pause') {
      copy.data.label = STAGE_LABELS[mode][copy.kind]
    }
    const data = copy.data as Record<string, unknown>
    if (copy.kind === 'parent' || copy.kind === 'agent') {
      data.groupId = typeof data.groupId === 'string' ? (idMap.get(data.groupId) ?? data.groupId) : data.groupId
    }
    if (copy.kind === 'group') {
      data.memberIds = (Array.isArray(data.memberIds) ? data.memberIds : []).map((id) => idMap.get(String(id)) ?? String(id))
    }
    if (copy.kind === 'proxy') {
      copy.proxySourceId = idMap.get(copy.proxySourceId) ?? copy.proxySourceId
    }
    return copy
  })
  const lines = template.lines.map((line) => ({
    ...line,
    id: `line-${Math.random().toString(36).slice(2, 10)}`,
    source: idMap.get(line.source) ?? line.source,
    target: idMap.get(line.target) ?? line.target,
  }))
  return { nodes, lines }
}

/** 子图节点类型收窄（供组件使用）。 */
export function isSubgraphNode(node: { kind?: string } | null | undefined): node is SubgraphNode & { data: SubgraphNode['data'] & { graph: SubgraphGraphSnapshot } } {
  return node?.kind === 'subgraph'
}
