// src/client/sidebar/instance-navigation.ts
/** Navigation carries identities only; the editor loads the authoritative document. */
export interface InstancePreviewRequest { sessionId: string; flowId: string; sequence: number }
export interface InstanceNavigation {
  openInstance(target: { sessionId: string; flowId: string }): void
  pending(): InstancePreviewRequest | null
  acknowledge(sequence: number): void
  subscribe(listener: () => void): () => void
}
/** Hold requests until the persistent editor mounts and acknowledges them. */
export function createInstanceNavigation(): InstanceNavigation {
  let request: InstancePreviewRequest | null = null, sequence = 0
  const listeners = new Set<() => void>()
  const emit = (): void => { for (const listener of listeners) listener() }
  return {
    openInstance(target) { request = { ...target, sequence: ++sequence }; emit() },
    pending: () => request,
    acknowledge(value) { if (request?.sequence === value) { request = null; emit() } },
    subscribe(listener) { listeners.add(listener); return () => { listeners.delete(listener) } },
  }
}
