// src/client/lib/orthogonal-routing.ts

export interface RoutePoint { x: number; y: number }
export interface RouteBox { id: string; x: number; y: number; w: number; h: number }
export interface RouteInput {
  id: string
  start: RoutePoint
  end: RoutePoint
  startDir: number
  endDir: number
  sourceOwner: string
  targetOwner: string
  labelWidth: number
  startAxis?: number
  endAxis?: number
  waypoints?: RoutePoint[]
  sourceBundle?: string
  targetBundle?: string
  sourceTree?: string
  targetTree?: string
  sourceTail?: number
  targetTail?: number
}
export interface OrthogonalRoute {
  points: RoutePoint[]
  path: string
  label: RoutePoint
  labelWidth: number
  labelAnchor?: RoutePoint
  geometryKey?: string
  targetBundle?: string
}
interface Segment { a: RoutePoint; b: RoutePoint; bundles?: string[]; edgeId?: string }
const CLEARANCE = 18
const TAIL = 32
const LANE = 14
const PORT_BUNDLE_RADIUS = 64
const EPSILON = 0.01
const coordinate = (value: number): number => Math.round(value * 1e6) / 1e6
const exactPoint = (p: RoutePoint): RoutePoint => ({ x: coordinate(p.x), y: coordinate(p.y) })

function segmentHits(a: RoutePoint, b: RoutePoint, box: RouteBox): boolean {
  if (a.y === b.y) return a.y > box.y + EPSILON && a.y < box.y + box.h - EPSILON && Math.max(a.x, b.x) > box.x + EPSILON && Math.min(a.x, b.x) < box.x + box.w - EPSILON
  return a.x > box.x + EPSILON && a.x < box.x + box.w - EPSILON && Math.max(a.y, b.y) > box.y + EPSILON && Math.min(a.y, b.y) < box.y + box.h - EPSILON
}

function segmentCost(a: RoutePoint, b: RoutePoint, occupied: Segment[], allowedBundles: string[] = []): number {
  let penalty = 0, sharedLength = 0
  const horizontal = a.y === b.y
  for (const other of occupied) {
    const shared = other.bundles?.some(key => allowedBundles.includes(key))
    const oh = other.a.y === other.b.y
    if (horizontal === oh) {
      const separation = Math.abs(horizontal ? a.y - other.a.y : a.x - other.a.x)
      const overlap = horizontal
        ? Math.min(Math.max(a.x, b.x), Math.max(other.a.x, other.b.x)) - Math.max(Math.min(a.x, b.x), Math.min(other.a.x, other.b.x))
        : Math.min(Math.max(a.y, b.y), Math.max(other.a.y, other.b.y)) - Math.max(Math.min(a.y, b.y), Math.min(other.a.y, other.b.y))
      if (overlap > EPSILON && separation < EPSILON) {
        const sameDirection = (b.x - a.x) * (other.b.x - other.a.x) + (b.y - a.y) * (other.b.y - other.a.y) > 0
        if (shared && sameDirection) { sharedLength = Math.max(sharedLength, overlap); continue }
        return Infinity
      }
      if (overlap > EPSILON && separation < LANE - EPSILON) penalty += overlap * 4
    } else {
      const h = horizontal ? { a, b } : other
      const v = horizontal ? other : { a, b }
      if (v.a.x > Math.min(h.a.x, h.b.x) + EPSILON && v.a.x < Math.max(h.a.x, h.b.x) - EPSILON
        && h.a.y > Math.min(v.a.y, v.b.y) + EPSILON && h.a.y < Math.max(v.a.y, v.b.y) - EPSILON) penalty += shared ? 0 : 80
    }
  }
  return penalty - sharedLength * 0.18
}

class MinQueue {
  private items: Array<{ state: number; score: number }> = []
  push(state: number, score: number): void {
    const value = { state, score }; let i = this.items.length; this.items.push(value)
    while (i > 0) { const parent = (i - 1) >> 1; if (this.items[parent].score <= score) break; this.items[i] = this.items[parent]; i = parent }
    this.items[i] = value
  }
  pop(): { state: number; score: number } | undefined {
    const first = this.items[0], last = this.items.pop(); if (!first || !last || !this.items.length) return first
    let i = 0
    while (i * 2 + 1 < this.items.length) { let child = i * 2 + 1; if (child + 1 < this.items.length && this.items[child + 1].score < this.items[child].score) child++; if (this.items[child].score >= last.score) break; this.items[i] = this.items[child]; i = child }
    this.items[i] = last; return first
  }
}

export function simplifyRoute(points: RoutePoint[]): RoutePoint[] {
  const out: RoutePoint[] = []
  for (const point of points) {
    if (out.length && out[out.length - 1].x === point.x && out[out.length - 1].y === point.y) continue
    while (out.length > 1) {
      const a = out[out.length - 2], b = out[out.length - 1]
      if ((a.x === b.x && b.x === point.x) || (a.y === b.y && b.y === point.y)) out.pop()
      else break
    }
    out.push(point)
  }
  return out
}

export function routePath(points: RoutePoint[]): string {
  return points.map((p, i) => `${i ? 'L' : 'M'} ${p.x} ${p.y}`).join(' ')
}

/** All edges share one obstacle field and reserved lanes; selection never reroutes the graph. */
export function routeOrthogonalEdges(inputs: RouteInput[], boxes: RouteBox[], previousRoutes?: Map<string, OrthogonalRoute>): Map<string, OrthogonalRoute> {
  const result = new Map<string, OrthogonalRoute>()
  if (!inputs.length) return result
  const padded = boxes.map(b => ({ ...b, x: b.x - CLEARANCE, y: b.y - CLEARANCE, w: b.w + CLEARANCE * 2, h: b.h + CLEARANCE * 2 }))
  const byId = new Map(boxes.map(b => [b.id, b]))
  const endpoints = inputs.map(edge => {
    const source = byId.get(edge.sourceOwner), target = byId.get(edge.targetOwner)
    const sourceTail = edge.sourceTail ?? TAIL, targetTail = edge.targetTail ?? TAIL
    return {
      edge,
      start: exactPoint(edge.startAxis === 1
        ? { x: edge.start.x, y: source ? (edge.startDir > 0 ? source.y + source.h + sourceTail : source.y - sourceTail) : edge.start.y + edge.startDir * sourceTail }
        : { x: source ? (edge.startDir > 0 ? source.x + source.w + sourceTail : source.x - sourceTail) : edge.start.x + edge.startDir * sourceTail, y: edge.start.y }),
      end: exactPoint(edge.endAxis === 1
        ? { x: edge.end.x, y: target ? (edge.endDir > 0 ? target.y + target.h + targetTail : target.y - targetTail) : edge.end.y + edge.endDir * targetTail }
        : { x: target ? (edge.endDir > 0 ? target.x + target.w + targetTail : target.x - targetTail) : edge.end.x + edge.endDir * targetTail, y: edge.end.y }),
      waypoints: (edge.waypoints ?? []).filter(p => Number.isFinite(p.x) && Number.isFinite(p.y)).slice(0, 64).map(p => {
        const hits = padded.filter(b => p.x > b.x && p.x < b.x + b.w && p.y > b.y && p.y < b.y + b.h)
        if (!hits.length) return p
        const candidates = hits.flatMap(b => [{ x: b.x - 1, y: p.y }, { x: b.x + b.w + 1, y: p.y }, { x: p.x, y: b.y - 1 }, { x: p.x, y: b.y + b.h + 1 }])
          .sort((a, b) => Math.hypot(a.x - p.x, a.y - p.y) - Math.hypot(b.x - p.x, b.y - p.y))
        return candidates.find(p => !padded.some(b => p.x > b.x && p.x < b.x + b.w && p.y > b.y && p.y < b.y + b.h)) ?? p
      }).map(exactPoint),
    }
  })
  const xs = new Set<number>(), ys = new Set<number>()
  for (const b of padded) for (const offset of [0, LANE]) {
    xs.add(b.x - offset); xs.add(b.x + b.w + offset)
    ys.add(b.y - offset); ys.add(b.y + b.h + offset)
  }
  for (const { edge, start, end, waypoints } of endpoints) for (const p of [start, ...waypoints, end, ...(edge.sourceBundle ? [{ x: edge.start.x - PORT_BUNDLE_RADIUS, y: edge.start.y - PORT_BUNDLE_RADIUS }, { x: edge.start.x + PORT_BUNDLE_RADIUS, y: edge.start.y + PORT_BUNDLE_RADIUS }] : []), ...(edge.targetBundle ? [{ x: edge.end.x - PORT_BUNDLE_RADIUS, y: edge.end.y - PORT_BUNDLE_RADIUS }, { x: edge.end.x + PORT_BUNDLE_RADIUS, y: edge.end.y + PORT_BUNDLE_RADIUS }] : [])]) {
    xs.add(p.x); ys.add(p.y)
    xs.add(p.x - LANE); xs.add(p.x + LANE); ys.add(p.y - LANE); ys.add(p.y + LANE)
  }
  const bounds = { left: Math.min(...xs), right: Math.max(...xs), top: Math.min(...ys), bottom: Math.max(...ys) }
  for (let i = 1; i <= Math.min(inputs.length + 1, 12); i++) {
    xs.add(bounds.left - i * LANE); xs.add(bounds.right + i * LANE)
    ys.add(bounds.top - i * LANE); ys.add(bounds.bottom + i * LANE)
  }
  const x = [...new Set([...xs].map(coordinate))].sort((a, b) => a - b), y = [...new Set([...ys].map(coordinate))].sort((a, b) => a - b)
  const width = x.length, height = y.length, count = width * height
  const point = (index: number): RoutePoint => ({ x: x[index % width], y: y[Math.floor(index / width)] })
  const blocked = new Map<string, boolean>()
  const occupied: Segment[] = []
  // A label must not seal a future edge's terminal escape before that edge is routed.
  const terminalCorridors = endpoints.flatMap(({ edge, start, end }) => [{ a: edge.start, b: start }, { a: end, b: edge.end }])
  const labels: RouteBox[] = []
  const geometryKey = (edge: RouteInput): string => JSON.stringify([edge.startAxis, edge.endAxis, edge.startDir, edge.endDir, edge.waypoints, edge.sourceBundle, edge.targetBundle, edge.sourceTree, edge.targetTree, edge.sourceTail, edge.targetTail, edge.labelWidth])
  const contains = (a: RoutePoint, b: RoutePoint, p: RoutePoint): boolean => ((a.x === b.x && p.x === a.x) || (a.y === b.y && p.y === a.y)) && p.x >= Math.min(a.x, b.x) && p.x <= Math.max(a.x, b.x) && p.y >= Math.min(a.y, b.y) && p.y <= Math.max(a.y, b.y)
  const reserve = (edge: RouteInput, route: OrthogonalRoute, start: RoutePoint, end: RoutePoint): void => {
    for (let i = 1; i < route.points.length; i++) {
      const a = route.points[i - 1], b = route.points[i]
      const bundleCuts = [edge.start, edge.end].flatMap(p => a.y === b.y ? [{ x: p.x - PORT_BUNDLE_RADIUS, y: a.y }, { x: p.x + PORT_BUNDLE_RADIUS, y: a.y }] : [{ x: a.x, y: p.y - PORT_BUNDLE_RADIUS }, { x: a.x, y: p.y + PORT_BUNDLE_RADIUS }])
      const cuts = [a, ...[start, end, ...bundleCuts].filter(p => contains(a, b, p)), b].sort((p, q) => Math.hypot(p.x - a.x, p.y - a.y) - Math.hypot(q.x - a.x, q.y - a.y))
      for (let k = 1; k < cuts.length; k++) {
        const from = cuts[k - 1], to = cuts[k]
        if (from.x === to.x && from.y === to.y) continue
        const mid = { x: (from.x + to.x) / 2, y: (from.y + to.y) / 2 }
        const bundles = [
          edge.sourceTree && Math.max(Math.abs(mid.x - edge.start.x), Math.abs(mid.y - edge.start.y)) <= PORT_BUNDLE_RADIUS ? edge.sourceTree : undefined,
          edge.targetTree && Math.max(Math.abs(mid.x - edge.end.x), Math.abs(mid.y - edge.end.y)) <= PORT_BUNDLE_RADIUS ? edge.targetTree : undefined,
          edge.sourceBundle && Math.max(Math.abs(mid.x - edge.start.x), Math.abs(mid.y - edge.start.y)) <= PORT_BUNDLE_RADIUS ? edge.sourceBundle : undefined,
          edge.targetBundle && Math.max(Math.abs(mid.x - edge.end.x), Math.abs(mid.y - edge.end.y)) <= PORT_BUNDLE_RADIUS ? edge.targetBundle : undefined].filter((key): key is string => !!key)
        occupied.push({ a: from, b: to, bundles, edgeId: edge.id })
      }
    }
  }
  for (const { edge, start, end } of endpoints) {
    const route = previousRoutes?.get(edge.id)
    if (!route || route.geometryKey !== geometryKey(edge) || route.points[0].x !== edge.start.x || route.points[0].y !== edge.start.y || route.points.at(-1)!.x !== edge.end.x || route.points.at(-1)!.y !== edge.end.y) continue
    const valid = route.points.slice(1).every((p, i) => !padded.some(b => {
      if ((i === 0 && b.id === edge.sourceOwner) || (i === route.points.length - 2 && b.id === edge.targetOwner)) return false
      return segmentHits(route.points[i], p, b)
    }))
    if (!valid) continue
    result.set(edge.id, route)
    reserve(edge, route, start, end)
  }
  const canTravel = (from: number, to: number): boolean => {
    const key = from < to ? `${from}:${to}` : `${to}:${from}`
    let hit = blocked.get(key)
    if (hit === undefined) { const a = point(from), b = point(to); hit = padded.some(box => segmentHits(a, b, box)); blocked.set(key, hit) }
    return !hit
  }
  // Short local paths reserve the smallest lanes first; ids make ties independent of input order.
  endpoints.sort((a, b) => Math.abs(a.end.x - a.start.x) + Math.abs(a.end.y - a.start.y) - Math.abs(b.end.x - b.start.x) - Math.abs(b.end.y - b.start.y) || a.edge.id.localeCompare(b.edge.id))
  for (const { edge, start, end, waypoints } of endpoints) {
    if (result.has(edge.id)) continue
    const localOccupied = [...occupied]
    const path: RoutePoint[] = []
    const stops = [start, ...waypoints, end]
    let failed = false
    for (let section = 1; section < stops.length; section++) {
      const from = stops[section - 1], goal = stops[section]
      const startIndex = y.indexOf(from.y) * width + x.indexOf(from.x), endIndex = y.indexOf(goal.y) * width + x.indexOf(goal.x)
      const distance = new Float64Array(count * 2); distance.fill(Infinity)
      const previous = new Int32Array(count * 2); previous.fill(-1)
      const runLength = new Float64Array(count * 2)
      const queue = new MinQueue()
      const heuristic = (p: RoutePoint): number => (Math.abs(p.x - goal.x) + Math.abs(p.y - goal.y)) * 0.82
      const startAxis = section === 1 ? edge.startAxis ?? 0 : path.length > 1 && path.at(-1)!.x === path.at(-2)!.x ? 1 : 0
      distance[startIndex * 2 + startAxis] = 0; runLength[startIndex * 2 + startAxis] = 24; queue.push(startIndex * 2 + startAxis, heuristic(from))
      let terminal = -1
      while (true) {
        const current = queue.pop(); if (!current) break
        const index = Math.floor(current.state / 2), axis = current.state % 2, a = point(index)
        if (current.score > distance[current.state] + heuristic(a) + EPSILON) continue
        if (index === endIndex) { terminal = current.state; break }
        const ix = index % width, iy = Math.floor(index / width)
        for (const [next, nextAxis] of [[ix > 0 ? index - 1 : -1, 0], [ix + 1 < width ? index + 1 : -1, 0], [iy > 0 ? index - width : -1, 1], [iy + 1 < height ? index + width : -1, 1]]) {
          if (next < 0 || !canTravel(index, next)) continue
          const b = point(next)
          // A terminal escape cannot double back along its own tail: this was the source of corner spikes.
          if (section === 1 && index === startIndex && (edge.startAxis === 1 ? b.y - a.y : b.x - a.x) * edge.startDir < 0) continue
          if (section === stops.length - 1 && next === endIndex && (edge.endAxis === 1 ? b.y - a.y : b.x - a.x) * edge.endDir > 0) continue
          const reserved = segmentCost(a, b, localOccupied, [edge.sourceBundle, edge.targetBundle, edge.sourceTree, edge.targetTree].filter((key): key is string => !!key))
          if (!Number.isFinite(reserved)) continue
          const stepLength = Math.abs(a.x - b.x) + Math.abs(a.y - b.y)
          // A crossing is preferable to a little hook that travels away from its terminal and back.
          const retreat = Math.max(0, Math.abs(b.x - goal.x) + Math.abs(b.y - goal.y) - Math.abs(a.x - goal.x) - Math.abs(a.y - goal.y))
          const cost = distance[current.state] + stepLength + retreat * 4 + (axis !== nextAxis ? 64 + Math.max(0, 24 - runLength[current.state]) * 6 : 0) + reserved
          const nextState = next * 2 + nextAxis
          if (cost >= distance[nextState]) continue
          distance[nextState] = cost; previous[nextState] = current.state; runLength[nextState] = Math.min(24, (axis === nextAxis ? runLength[current.state] : 0) + stepLength); queue.push(nextState, cost + heuristic(b))
        }
      }
      if (terminal < 0) { failed = true; break }
      const points: RoutePoint[] = []
      for (let state = terminal; state >= 0; state = previous[state]) points.push(point(Math.floor(state / 2)))
      points.reverse()
      for (let i = 1; i < points.length; i++) localOccupied.push({ a: points[i - 1], b: points[i] })
      path.push(...points.slice(section === 1 ? 0 : 1))
    }
    if (failed) continue
    let core = simplifyRoute(path)
    // Remove unnecessary U-shaped detours once the clear corridors are known.
    if (!waypoints.length) {
      const allowed = [edge.sourceBundle, edge.targetBundle, edge.sourceTree, edge.targetTree].filter((key): key is string => !!key)
      for (let i = 0; i < core.length - 2; i++) for (let j = core.length - 1; j > i + 1; j--) {
        const a = core[i], b = core[j]
        const candidates = a.x === b.x || a.y === b.y ? [[a, b]] : [[a, { x: b.x, y: a.y }, b], [a, { x: a.x, y: b.y }, b]]
        const shortcut = candidates.find(points => {
          if (points.length >= j - i + 1) return false
          if (i === 0 && (edge.startAxis === 1 ? points[1].y - a.y : points[1].x - a.x) * edge.startDir < 0) return false
          if (j === core.length - 1 && (edge.endAxis === 1 ? b.y - points.at(-2)!.y : b.x - points.at(-2)!.x) * edge.endDir > 0) return false
          return points.slice(1).every((p, k) => !padded.some(box => segmentHits(points[k], p, box)) && Number.isFinite(segmentCost(points[k], p, occupied, allowed)))
        })
        if (shortcut) { core = simplifyRoute([...core.slice(0, i), ...shortcut, ...core.slice(j + 1)]); i = Math.max(-1, i - 1); break }
      }
    }
    const pathPoints = simplifyRoute([edge.start, ...core, edge.end])
    const routed: OrthogonalRoute = { points: pathPoints, path: routePath(pathPoints), label: { x: (start.x + end.x) / 2, y: (start.y + end.y) / 2 }, labelWidth: edge.labelWidth, geometryKey: geometryKey(edge), ...(edge.targetBundle ? { targetBundle: edge.targetBundle } : {}) }
    reserve(edge, routed, start, end)
    result.set(edge.id, routed)
  }
  // Labels adapt to completed routes; they must never force a later edge into a tiny hook.
  for (const { edge, start, end } of endpoints) {
    const route = result.get(edge.id)
    if (!route) continue
    const pathPoints = route.points
    let label = { x: (start.x + end.x) / 2, y: (start.y + end.y) / 2 }, labelWidth = edge.labelWidth
    let labelAnchor: RoutePoint | undefined
    if (labelWidth) {
      let best = -Infinity
      for (let i = 1; i < pathPoints.length; i++) {
        const a = pathPoints[i - 1], b = pathPoints[i], horizontal = a.y === b.y
        const length = Math.abs(a.x - b.x) + Math.abs(a.y - b.y)
        for (const fraction of [0.5, 0.3, 0.7]) for (const offset of [0, -24, 24, -42, 42]) {
          const anchor = { x: a.x + (b.x - a.x) * fraction, y: a.y + (b.y - a.y) * fraction }
          const candidate = { x: anchor.x + (horizontal ? 0 : offset), y: anchor.y + (horizontal ? offset : 0) }
          const box = { id: edge.id, x: candidate.x - labelWidth / 2 - 5, y: candidate.y - 13, w: labelWidth + 10, h: 26 }
          const overlap = [...padded, ...labels].some(b => box.x < b.x + b.w && box.x + box.w > b.x && box.y < b.y + b.h && box.y + box.h > b.y)
          const crosses = occupied.some(s => s.edgeId !== edge.id && segmentHits(s.a, s.b, box)) || terminalCorridors.some(s => segmentHits(s.a, s.b, box))
          const leaderBlocked = offset !== 0 && (padded.some(b => segmentHits(anchor, candidate, b)) || segmentCost(anchor, candidate, occupied.filter(s => s.edgeId !== edge.id)) > 0)
          const score = (horizontal ? 200 : 0) + length - (overlap || crosses || leaderBlocked ? 10000 : 0) - Math.abs(fraction - 0.5) * 20 - Math.abs(offset) * 8
          if (score > best) { best = score; label = candidate; labelAnchor = offset ? anchor : undefined }
        }
      }
      if (best < -5000) labelWidth = 0
      else labels.push({ id: edge.id, x: label.x - labelWidth / 2 - 4, y: label.y - 12, w: labelWidth + 8, h: 24 })
    }
    if (route.label.x !== label.x || route.label.y !== label.y || route.labelWidth !== labelWidth || route.labelAnchor?.x !== labelAnchor?.x || route.labelAnchor?.y !== labelAnchor?.y) {
      const { labelAnchor: previousAnchor, ...geometry } = route
      result.set(edge.id, { ...geometry, label, labelWidth, ...(labelAnchor ? { labelAnchor } : {}) })
    }
  }
  return result
}
