// src/client/studio/studio-initial.ts
//
// 工作台状态机的起点：撤销栈上限、初始面板几何与完整初始状态工厂
// （会话 id 由调用方注入）。reducer 的 HISTORY_PUSH 与 hooks 装配消费。

import type { PanelLayout, StudioState } from './studio-types.js'

/** 撤销重做栈上限。 */
export const HISTORY_LIMIT = 60

/** 初始面板几何：默认「左栏展开」（折叠切换循环位置 0），右侧属性栏默认隐藏（由选中推导）。
 *  底栏默认高度 170px，左右两侧栏默认宽度 230px（用户裁决）。 */
export function defaultPanels(): PanelLayout {
  return { mode: 0, leftWidth: 230, rightWidth: 230, bottomHeight: 170 }
}

/** 初始状态（会话 id 由调用方注入）。 */
export function createInitialState(sessionId: string): StudioState {
  return {
    sessionId,
    libTab: 'workflow',
    // 缺省模版态（库来源与画布文档类型默认都是模版）
    librarySource: 'template',
    libSearch: '',
    assets: { workflows: [], roles: [], prompts: [], retiredWorkflows: [], retiredRoles: [] },
    assetDoc: null,
    assetRoleDoc: null,
    promptDoc: null,
    experiences: [],
    experienceDoc: null,
    assetVersions: null,
    mode: 'mode1',
    workflows: [],
    services: [],
    activeRuns: [],
    instanceOptions: { newSession: false },
    flowTemplates: [],
    templates: { role: [], task: [], database: [], group: [] },
    combos: [],
    presets: [],
    models: [],
    currentId: null,
    currentKind: null,
    canvas: { nodes: [], edges: [] },
    selection: { nodeId: null, edgeId: null, lib: null },
    editor: null,
    dirty: false,
    savedGraph: null,
    run: { runId: null, sessionId: null, snapshot: null },
    toasts: [],
    history: { past: [], future: [] },
    panels: defaultPanels(),
    confirm: null,
    historyOpen: false,
    runHistory: [],
    selectedRunId: null,
    comboOpen: false,
    schedulerOpen: false,
  }
}
