// src/client/lib/manual-connection.ts

import type { Handle, LineAppearance, PortSide } from '../../host/shared/graph-model.js'
import type { CanvasEdge, CanvasNode } from './canvas-model.js'
import { connectionProblem } from './connection-rules.js'

export type ConnectionChannel = Handle extends `${infer Channel}-${'in' | 'out'}` ? Channel : never

export function channelHandles(channel: ConnectionChannel): { sourceHandle: Handle; targetHandle: Handle } {
  return { sourceHandle: `${channel}-out`, targetHandle: `${channel}-in` }
}

/** Unsupported purposes stay visible but disabled in the inspector. Duplicates are checked on apply. */
export function availableConnectionChannels(nodes: CanvasNode[], edge: CanvasEdge): ConnectionChannel[] {
  return (['flow', 'ctx', 'db'] as const).filter(channel => connectionProblem(nodes, [], { ...edge, ...channelHandles(channel) }).valid)
}

export interface ConnectionPort { nodeId: string; handles: string[]; side?: PortSide }

/** Physical sockets may carry several channels. Resolve direction and a shared semantic channel. */
export function connectPorts(first: ConnectionPort, second: ConnectionPort, type: LineAppearance['type'], channel?: ConnectionChannel): { source: string; target: string; sourceHandle: string; targetHandle: string; appearance: LineAppearance } | null {
  if (first.nodeId === second.nodeId) return null
  const forward = first.handles.some(handle => handle.endsWith('-out'))
  const source = forward ? first : second, target = forward ? second : first
  // An explicit purpose must never silently fall back to a different runtime channel.
  const candidates = channel ? [channelHandles(channel).sourceHandle] : ['flow-out', 'ctx-out', 'db-out']
  const sourceHandle = candidates.find(handle => source.handles.includes(handle) && target.handles.includes(handle.replace('-out', '-in')))
  if (!sourceHandle) return null
  return { source: source.nodeId, target: target.nodeId, sourceHandle, targetHandle: sourceHandle.replace('-out', '-in'), appearance: { type, sourceSide: source.side ?? 'right', targetSide: target.side ?? 'left' } }
}
