// src/client/lib/manual-nodes.ts

import type { CanvasNode } from './canvas-model.js'
import type { NodeKind } from '../../host/shared/graph-model.js'
import { DEFAULT_OUTPUT_CONTRACT_TEXT, STAGE_LABELS } from '../../host/shared/protocol.js'

/** Blank cards are editable immediately; role tools come from the standard preset. */
export function blankNode(kind: NodeKind, id: string, label: string, position: { x: number; y: number }, selection?: { provider?: unknown; model?: unknown }, mode: 'mode1' | 'mode2' = 'mode1'): CanvasNode {
  const data: Record<string, unknown> = { label }
  if (kind === 'agent' || kind === 'parent') Object.assign(data, { systemPrompt: '', provider: String(selection?.provider ?? ''), model: String(selection?.model ?? ''), presetId: 'standard', retryLimit: 3, reactLimit: null, inputSchema: '', outputSchema: DEFAULT_OUTPUT_CONTRACT_TEXT, injectSystemPrompt: true, injectToolSections: true, groupId: null })
  if (kind === 'task' || kind === 'step') data.content = ''
  if (kind === 'database') Object.assign(data, { description: '', dbType: 'local', dbKind: 'sqlite', localPath: '', vectorSource: 'bm25' })
  if (kind === 'group') Object.assign(data, { memberIds: [], collabPrompt: '', size: { w: 300, h: 220 } })
  if (kind === 'subgraph') {
    const startId = `node-${Math.random().toString(36).slice(2, 10)}`
    const endId = `node-${Math.random().toString(36).slice(2, 10)}`
    data.description = ''
    data.graph = {
      nodes: [
        { id: startId, kind: 'start', position: { x: 60, y: 100 }, data: { label: STAGE_LABELS[mode].start } },
        { id: endId, kind: 'end', position: { x: 360, y: 100 }, data: { label: STAGE_LABELS[mode].end } },
      ],
      lines: [{ id: `line-${Math.random().toString(36).slice(2, 10)}`, source: startId, target: endId, sourceHandle: 'flow-out', targetHandle: 'flow-in' }],
    }
  }
  return { id, kind, position, data }
}

/** Copy configuration without aliasing nested data or borrowing external edges/membership. */
export function duplicateNodes(node: CanvasNode, nodes: CanvasNode[], newId: () => string, label: string, position: { x: number; y: number }): CanvasNode[] {
  const copy = { ...node, id: newId(), position, data: structuredClone(node.data) }
  copy.data.label = label
  if (node.kind === 'agent' || node.kind === 'parent') copy.data.groupId = null
  if (node.kind !== 'group') return [copy]
  const members = nodes.filter(n => (node.data.memberIds as string[] ?? []).includes(n.id)).map(member => ({ ...member, id: newId(), position: { x: position.x + member.position.x - node.position.x, y: position.y + member.position.y - node.position.y }, data: { ...structuredClone(member.data), groupId: copy.id } }))
  copy.data.memberIds = members.map(member => member.id)
  return [copy, ...members]
}
