import type { CanvasEdge } from './canvas-model.js'

/** Release geometric constraints only; retain endpoints, semantic channels, conditions and line shape. */
export function autoRouteEdges(edges: CanvasEdge[]): CanvasEdge[] {
  return edges.map(edge => ({ ...edge, appearance: {
    ...edge.appearance, waypoints: [], anchorMode: 'auto', sourceSide: undefined, targetSide: undefined,
  } }))
}
