// src/client/hooks/use-instance-preview.ts
import { useEffect, useRef } from 'react'
import type { InstanceNavigation, InstancePreviewRequest } from '../sidebar/instance-navigation.js'
import type { WorkflowsFace } from './useWorkflows.js'
import type { UnsavedGuardFace } from './useUnsavedGuard.js'
/** Reuse document loading and the unsaved guard, never change editor state directly. */
export function useInstancePreview(request: InstancePreviewRequest | null | undefined, navigation: InstanceNavigation | undefined, workflows: WorkflowsFace, guard: UnsavedGuardFace, failed: (error: unknown) => void, missingMessage: string, opened?: () => void): void {
  const latest = useRef({ guard, failed, missingMessage, opened })
  latest.current = { guard, failed, missingMessage, opened }
  useEffect(() => {
    if (!request) return
    let active = true
    void workflows.loadWorkflows().then(flows => {
      if (!active) return
      const flow = flows.find(item => item.id === request.flowId && item.sessionId === request.sessionId)
      if (!flow) throw new Error(latest.current.missingMessage)
      latest.current.guard.guard(() => { workflows.openFlow(flow); latest.current.opened?.() })
      navigation?.acknowledge(request.sequence)
    }).catch(error => { if (active) { latest.current.failed(error); navigation?.acknowledge(request.sequence) } })
    return () => { active = false }
  }, [request?.sequence, navigation, workflows])
}
