// src/client/studio/studio-reducer.ts
//
// 工作台状态机主体（纯 reducer，可独立单测）：studioReducer 依
// StudioAction 单向流转状态；openDocument 打开文档（重置选中/编辑器/
// 已保存图快照/历史栈）；sanitizeSelectionAfterCanvas 校验画布恢复后的选中与
// 编辑器引用。所有变更经 dispatch(action) 流入。

import type { StudioState, CanvasNode, CanvasEdge, EditorRef, LibSelKind } from './studio-types.js'
import type { WorkflowTemplate } from '../../host/shared/graph-model.js'
import type { Drafted } from './studio-state.js'
import type { StudioAction } from './studio-actions.js'
import { flowToCanvas, serviceToCanvas } from './studio-projection.js'
import { graphSnapshotOf, graphSnapshotsEqual } from './studio-snapshot.js'
import { HISTORY_LIMIT } from './studio-initial.js'

/** 打开工作流/服务/模板时的选中、编辑器与历史栈重置（可选保留画布选择）。 */
function openDocument(state: StudioState, canvas: { nodes: CanvasNode[]; edges: CanvasEdge[] }, kind: 'workflow' | 'service' | 'flowTemplate', id: string): StudioState {
  const libKind: LibSelKind = kind === 'workflow' ? 'workflow' : kind === 'service' ? 'service' : 'workflowTemplate'
  const editor: EditorRef = kind === 'workflow' ? { source: 'workflow', id } : kind === 'service' ? { source: 'service', id } : { source: 'flowTemplate', id }
  const opened: StudioState = {
    ...state,
    currentKind: kind,
    currentId: id,
    canvas,
    dirty: false,
    savedGraph: graphSnapshotOf({ ...state, canvas }),
    run: { runId: null, sessionId: null, snapshot: null },
    selection: { nodeId: null, edgeId: null, lib: { kind: libKind, id } },
    editor,
    // 历史栈严格绑定当前文档：跨文档残留的快照一旦被 UNDO 取回，会把上一个文档的图
    // 写进当前文档（几何防抖自动保存会立即把错误图静默落库，实例无版本历史不可回滚）。
    history: { past: [], future: [] },
  }
  return opened
}

export function studioReducer(state: StudioState, action: StudioAction): StudioState {
  switch (action.type) {
    case 'SET_SESSION':
      return { ...state, sessionId: action.sessionId }
    case 'SET_MODE':
      return { ...state, mode: action.mode }
    case 'SET_LIB_TAB':
      return { ...state, libTab: action.tab }
    case 'SET_LIBRARY_SOURCE':
      return { ...state, librarySource: action.source }
    case 'SET_LIB_SEARCH':
      return { ...state, libSearch: action.query }
    case 'ASSETS_LOADED':
      return {
        ...state,
        assets: {
          workflows: action.workflows,
          roles: action.roles,
          prompts: action.prompts,
          retiredWorkflows: action.retiredWorkflows,
          retiredRoles: action.retiredRoles,
        },
      }
    case 'ASSET_DOC_LOADED':
      return { ...state, assetDoc: action.detail }
    case 'ROLE_ASSET_LOADED':
      return { ...state, assetRoleDoc: action.detail }
    case 'PROMPT_ASSET_LOADED':
      return { ...state, promptDoc: action.detail }
    case 'OPEN_PROMPT_ASSET':
      return {
        ...state,
        selection: { nodeId: null, edgeId: null, lib: { kind: 'promptAsset', id: action.assetId } },
        editor: { source: 'promptAsset', id: action.assetId },
      }
    case 'PROMPT_ASSET_PATCH':
      // 只允许正文：即使补丁携带 name/description 也不写入详情槽（Host 侧还会再拒绝一次）
      return state.promptDoc && typeof action.patch.prompt === 'string'
        ? { ...state, promptDoc: { ...state.promptDoc, prompt: action.patch.prompt } }
        : state
    case 'EXPERIENCES_LOADED':
      return { ...state, experiences: action.items }
    case 'EXPERIENCE_LOADED': {
      // 列表与详情同源：装载详情时一并把列表里对应条目换成新值，避免两处各留一份旧内容
      const items = state.experiences.some((item) => item.id === action.entry.id)
        ? state.experiences.map((item) => (item.id === action.entry.id ? action.entry : item))
        : state.experiences
      return { ...state, experiences: items, experienceDoc: action.entry }
    }
    case 'OPEN_EXPERIENCE':
      return {
        ...state,
        selection: { nodeId: null, edgeId: null, lib: { kind: 'experience', id: action.experienceId } },
        editor: { source: 'experience', id: action.experienceId },
      }
    case 'EXPERIENCE_PATCH':
      // 属性栏表单实时编辑：字段落 experienceDoc（保存时由保存路径整体投影上报）
      return state.experienceDoc ? { ...state, experienceDoc: { ...state.experienceDoc, ...action.patch } } : state
    case 'OPEN_FLOW_ASSET': {
      // 画布 = assetDoc 的纯投影（与 OPEN_FLOW_TEMPLATE 同口径：打开即重置
      // 选中/编辑器/已保存快照/历史栈）；assetId 不匹配视为陈旧装载，保持原状态。
      const detail = state.assetDoc
      if (!detail || detail.assetId !== action.assetId) return state
      const canvas = flowToCanvas(detail)
      return {
        ...state,
        currentKind: 'flowAsset',
        currentId: detail.assetId,
        canvas,
        dirty: false,
        savedGraph: graphSnapshotOf({ ...state, canvas }),
        run: { runId: null, sessionId: null, snapshot: null },
        selection: { nodeId: null, edgeId: null, lib: { kind: 'flowAsset', id: detail.assetId } },
        editor: { source: 'flowAsset', id: detail.assetId },
        // 「开启新会话」：资产态一次性临时选项，每次打开资产回到「不新开会话」默认
        // （模板态的勾选与路径来自模板持久化字段，与本临时值无关）
        instanceOptions: { newSession: false },
        // 第四处画布身份切换入口：历史栈同样必须清空（否则可撤销回上一个文档的图，
        // 并被几何防抖自动保存写进本资产文档）
        history: { past: [], future: [] },
      }
    }
    case 'OPEN_ROLE_ASSET':
      return {
        ...state,
        selection: { nodeId: null, edgeId: null, lib: { kind: 'roleAsset', id: action.assetId } },
        editor: { source: 'roleAsset', id: action.assetId },
      }
    case 'ROLE_ASSET_PATCH':
      // 属性栏表单实时编辑：字段落 assetRoleDoc（登记新版本时由保存路径整体投影上报）
      return state.assetRoleDoc ? { ...state, assetRoleDoc: { ...state.assetRoleDoc, ...action.patch } } : state
    case 'ASSET_VERSIONS_LOADED':
      return { ...state, assetVersions: { kind: action.kind, assetId: action.assetId, items: action.items } }
    case 'ASSET_VERSIONS_CLOSED':
      return { ...state, assetVersions: null }
    case 'ASSET_CLOSED': {
      // 退役后该资产不再可见：清空其详情槽（其他资产的已装载详情不动）；
      // 正打开在画布（flowAsset）或属性栏（roleAsset）时一并清空，避免界面残留已退役资产。
      const assetId = action.assetId
      const next: StudioState = {
        ...state,
        assetDoc: state.assetDoc?.assetId === assetId ? null : state.assetDoc,
        assetRoleDoc: state.assetRoleDoc?.assetId === assetId ? null : state.assetRoleDoc,
        promptDoc: state.promptDoc?.assetId === assetId ? null : state.promptDoc,
        assetVersions: state.assetVersions?.assetId === assetId ? null : state.assetVersions,
      }
      const closesCanvas = state.currentKind === 'flowAsset' && state.currentId === assetId
      const closesEditor = (state.editor?.source === 'roleAsset' && state.editor.id === assetId)
        || (state.editor?.source === 'flowAsset' && state.editor.id === assetId)
        || (state.editor?.source === 'promptAsset' && state.editor.id === assetId)
      if (!closesCanvas && !closesEditor) return next
      return {
        ...next,
        ...(closesCanvas
          ? {
              currentId: null,
              currentKind: null,
              canvas: { nodes: [], edges: [] },
              dirty: false,
              run: { runId: null, sessionId: null, snapshot: null },
              // 画布身份已消失：历史栈同步清空（同 CLEAR_CANVAS；否则可撤销回已关闭资产的图）
              history: { past: [], future: [] },
            }
          : {}),
        selection: { nodeId: null, edgeId: null, lib: null },
        editor: null,
      }
    }
    case 'WORKFLOWS_LOADED':
      return { ...state, workflows: action.items }
    case 'WORKFLOW_ADDED':
      return { ...state, workflows: [action.flow, ...state.workflows] }
    case 'WORKFLOW_UPDATED':
      return { ...state, workflows: state.workflows.map((flow) => (flow.id === action.flow.id ? action.flow : flow)) }
    case 'WORKFLOW_REMOVED':
      return { ...state, workflows: state.workflows.filter((flow) => flow.id !== action.id) }
    case 'FLOW_TEMPLATES_LOADED':
      return { ...state, flowTemplates: action.items }
    case 'FLOW_TEMPLATES_SYNCED': {
      // 轮询同步：本地未落盘的模板草稿必须存活（服务端列表里没有它们），
      // 否则「新建模板 → 未保存」期间被轮询覆盖会凭空消失。
      const drafts = state.flowTemplates.filter((item) => (item as Drafted<WorkflowTemplate>)._draft === true)
      return { ...state, flowTemplates: [...drafts, ...action.items] }
    }
    case 'FLOW_TEMPLATE_ADDED':
      return { ...state, flowTemplates: [action.template, ...state.flowTemplates] }
    case 'FLOW_TEMPLATE_UPDATED':
      return { ...state, flowTemplates: state.flowTemplates.map((template) => (template.id === action.template.id ? action.template : template)) }
    case 'FLOW_TEMPLATE_REMOVED':
      return { ...state, flowTemplates: state.flowTemplates.filter((template) => template.id !== action.id) }
    case 'SERVICES_LOADED':
      return { ...state, services: action.items }
    case 'SERVICE_UPDATED':
      return { ...state, services: state.services.map((service) => (service.id === action.service.id ? action.service : service)) }
    case 'SERVICE_REMOVED':
      return { ...state, services: state.services.filter((service) => service.id !== action.id) }
    case 'ACTIVE_RUNS_LOADED':
      return { ...state, activeRuns: action.items.filter(item => {
        const known = state.run.snapshot
        // A slower summary request cannot revive a run whose detailed snapshot already settled.
        return !(known && known.id === item.runId && known.sessionId === item.sessionId && known.status !== 'running' && item.status === 'running')
      }) }
    case 'INSTANCE_OPTIONS_SET':
      return { ...state, instanceOptions: { ...state.instanceOptions, ...action.options } }
    case 'TEMPLATES_LOADED':
      return { ...state, templates: { ...state.templates, [action.kind]: action.items } }
    case 'TEMPLATE_ADDED':
      return { ...state, templates: { ...state.templates, [action.kind]: [action.template, ...state.templates[action.kind]] } }
    case 'TEMPLATE_UPDATED':
      return { ...state, templates: { ...state.templates, [action.kind]: state.templates[action.kind].map((item) => (item.id === action.template.id ? action.template : item)) } }
    case 'TEMPLATE_REMOVED':
      return { ...state, templates: { ...state.templates, [action.kind]: state.templates[action.kind].filter((item) => item.id !== action.id) } }
    case 'COMBOS_LOADED':
      return { ...state, combos: action.items }
    case 'PRESETS_LOADED':
      return { ...state, presets: action.items }
    case 'MODELS_LOADED':
      return { ...state, models: action.items }
    case 'OPEN_FLOW': {
      const exists = state.workflows.some((flow) => flow.id === action.flow.id)
      const workflows = exists
        ? state.workflows.map((flow) => (flow.id === action.flow.id ? action.flow : flow))
        : [action.flow, ...state.workflows]
      return openDocument({ ...state, workflows }, flowToCanvas(action.flow), 'workflow', action.flow.id)
    }
    case 'OPEN_SERVICE': {
      const exists = state.services.some((service) => service.id === action.service.id)
      const services = exists
        ? state.services.map((service) => (service.id === action.service.id ? action.service : service))
        : [action.service, ...state.services]
      return openDocument({ ...state, services }, serviceToCanvas(action.service), 'service', action.service.id)
    }
    case 'OPEN_FLOW_TEMPLATE': {
      // 模板打开 = 画布显示模板流程图（编辑态）；「创建实例」后转为实例态。
      // 「开启新会话」的勾选与工作区是模板级持久化配置（模板对象上的
      // startNewSession / workspacePath 字段），UI 经选择器 newSessionOptionsOf 派生，
      // 不在此重置临时选项。
      const exists = state.flowTemplates.some((template) => template.id === action.template.id)
      const flowTemplates = exists
        ? state.flowTemplates.map((template) => (template.id === action.template.id ? action.template : template))
        : [action.template, ...state.flowTemplates]
      return openDocument({ ...state, flowTemplates }, flowToCanvas(action.template), 'flowTemplate', action.template.id)
    }
    case 'CLEAR_CANVAS':
      return {
        ...state,
        currentId: null,
        currentKind: null,
        canvas: { nodes: [], edges: [] },
        selection: { nodeId: null, edgeId: null, lib: null },
        editor: null,
        dirty: false,
        run: { runId: null, sessionId: null, snapshot: null },
        // 画布身份已消失：历史栈同步清空（否则 UNDO 会把清空前的图恢复成「幽灵图」）
        history: { past: [], future: [] },
      }
    case 'GRAPH_REPLACED':
      return { ...state, canvas: { nodes: action.nodes, edges: action.edges }, dirty: action.dirty }
    case 'NODE_ADDED':
      return { ...state, canvas: { ...state.canvas, nodes: [...state.canvas.nodes, action.node] }, dirty: true }
    case 'NODE_MOVED':
      return {
        ...state,
        canvas: { ...state.canvas, nodes: state.canvas.nodes.map((node) => (node.id === action.id ? { ...node, position: action.position } : node)) },
        dirty: true,
      }
    case 'NODE_REMOVED': {
      // 级联删除：删除角色主节点时同时删除其全部
      // 虚拟引用节点，避免画布残留孤儿虚拟节点。
      const removed = new Set<string>([action.id])
      const main = state.canvas.nodes.find((node) => node.id === action.id)
      if (main?.kind === 'group') {
        for (const node of state.canvas.nodes) {
          if (node.data.groupId === main.id || (main.data.memberIds as string[] ?? []).includes(node.id)) removed.add(node.id)
        }
      }
      for (const node of state.canvas.nodes) {
        if (node.kind === 'proxy' && node.proxySourceId && removed.has(node.proxySourceId)) removed.add(node.id)
      }
      return {
        ...state,
        canvas: {
          nodes: state.canvas.nodes.filter((node) => !removed.has(node.id)),
          edges: state.canvas.edges.filter((edge) => !removed.has(edge.source) && !removed.has(edge.target)),
        },
        dirty: true,
      }
    }
    case 'EDGE_ADDED':
      return { ...state, canvas: { ...state.canvas, edges: [...state.canvas.edges, action.edge] }, dirty: true }
    case 'EDGE_REMOVED':
      return { ...state, canvas: { ...state.canvas, edges: state.canvas.edges.filter((edge) => edge.id !== action.id) }, dirty: true }
    case 'SELECT_NODE':
      return { ...state, selection: { nodeId: action.id, edgeId: null, lib: null }, editor: { source: 'node', id: action.id } }
    case 'SELECT_EDGE':
      return { ...state, selection: { nodeId: null, edgeId: action.id, lib: null }, editor: { source: 'edge', id: action.id } }
    case 'SELECT_LIB':
      return { ...state, selection: { nodeId: null, edgeId: null, lib: { kind: action.kind, id: action.id } } }
    case 'SELECT_EDITOR':
      return { ...state, editor: action.editor }
    case 'CLEAR_SELECTION':
      return { ...state, selection: { nodeId: null, edgeId: null, lib: null }, editor: null }
    case 'NODE_DATA_PATCH':
      return {
        ...state,
        canvas: {
          ...state.canvas,
          nodes: state.canvas.nodes.map((node) => (node.id === action.id ? { ...node, data: { ...node.data, ...action.patch } } : node)),
        },
        dirty: true,
      }
    case 'EDGE_PATCH':
      return {
        ...state,
        canvas: {
          ...state.canvas,
          edges: state.canvas.edges.map((edge) => (edge.id === action.id ? { ...edge, ...action.patch } : edge)),
        },
        dirty: true,
      }
    case 'DOC_PATCH':
      // 名/描述经 DOC_PATCH 落文档；undefined 不覆盖。
      // 新会话配置不走本动作：模板态勾选/路径由 setFlowTemplateOptions 立即保存模板，
      // 资产态勾选走 INSTANCE_OPTIONS_SET（一次性临时选项）。
      return state.currentKind === 'workflow'
        ? {
            ...state,
            workflows: state.workflows.map((flow) => (flow.id === state.currentId
              ? {
                  ...flow,
                  ...(action.patch.name !== undefined ? { name: action.patch.name } : {}),
                  ...(action.patch.description !== undefined ? { description: action.patch.description } : {}),
                }
              : flow)),
            dirty: true,
          }
        : state.currentKind === 'flowTemplate'
          ? {
              ...state,
              flowTemplates: state.flowTemplates.map((template) => (template.id === state.currentId
                ? {
                    ...template,
                    ...(action.patch.name !== undefined ? { name: action.patch.name } : {}),
                    ...(action.patch.description !== undefined ? { description: action.patch.description } : {}),
                  }
                : template)),
              dirty: true,
            }
          : state.currentKind === 'service'
            ? {
                ...state,
                services: state.services.map((service) => (service.id === state.currentId
                  ? {
                      ...service,
                      ...(action.patch.name !== undefined ? { name: action.patch.name } : {}),
                      ...(action.patch.description !== undefined ? { description: action.patch.description } : {}),
                    }
                  : service)),
                dirty: true,
              }
            : state.currentKind === 'flowAsset' && state.assetDoc?.assetId === state.currentId
              ? {
                  ...state,
                  // 资产态名/描述编辑落在 assetDoc 上：资产态保存（登记新版本）由 T6
                  // 接线的保存路径统一从 assetDoc + 画布取内容。
                  assetDoc: {
                    ...state.assetDoc,
                    ...(action.patch.name !== undefined ? { name: action.patch.name } : {}),
                    ...(action.patch.description !== undefined ? { description: action.patch.description } : {}),
                  },
                  dirty: true,
                }
              : state
    case 'SET_DIRTY':
      return { ...state, dirty: action.dirty }
    case 'MARK_SAVED':
      return { ...state, dirty: false, savedGraph: graphSnapshotOf(state) }
    case 'RUN_STARTED':
      // Continue creates a new run ID; a settled ID must never be readopted from a stale summary.
      if (state.run.stopping || (state.run.snapshot?.id === action.runId && state.run.snapshot.status !== 'running')) return state
      return { ...state, run: { runId: action.runId, sessionId: action.runSessionId ?? null, snapshot: null } }
    case 'RUN_STOP_REQUESTED':
      if (state.run.runId !== action.runId || state.run.sessionId !== action.sessionId) return state
      return { ...state, run: { ...state.run, stopping: true } }
    case 'RUN_STOP_SETTLED': {
      if (state.run.sessionId !== action.sessionId || (state.run.runId !== action.runId && state.run.snapshot?.id !== action.runId)) return state
      const { stopping: _stopping, ...run } = state.run
      return { ...state, run }
    }
    case 'RUN_SNAPSHOT': {
      const snapshot = action.snapshot
      const flow = state.currentKind === 'workflow' ? state.workflows.find(item => item.id === state.currentId) : null
      if (!flow || snapshot.flowId !== flow.id || snapshot.sessionId !== flow.sessionId) return state
      // A history request started before a new run must not overwrite its progress.
      if (state.run.runId && state.run.runId !== snapshot.id) return state
      if (state.run.snapshot?.id === snapshot.id && state.run.snapshot.status !== 'running' && snapshot.status === 'running') return state
      const activeRuns = snapshot.status === 'running' ? state.activeRuns : state.activeRuns.filter(item => item.runId !== snapshot.id || item.sessionId !== snapshot.sessionId || item.status !== 'running')
      return { ...state, activeRuns, run: { runId: snapshot.status === 'running' ? snapshot.id : null, sessionId: snapshot.sessionId, snapshot, ...(state.run.stopping ? { stopping: true } : {}) } }
    }
    case 'RUN_CLEARED':
      return { ...state, run: { runId: null, sessionId: null, snapshot: null } }
    case 'TOAST_PUSH':
      return { ...state, toasts: [...state.toasts, action.toast] }
    case 'TOAST_DROP':
      return { ...state, toasts: state.toasts.filter((toast) => toast.id !== action.id) }
    case 'HISTORY_PUSH': {
      const past = [...state.history.past, action.snapshot]
      if (past.length > HISTORY_LIMIT) past.shift()
      return { ...state, history: { past, future: [] } }
    }
    case 'UNDO': {
      const previous = state.history.past.at(-1)
      if (!previous) return state
      const next: StudioState = {
        ...state,
        canvas: { nodes: previous.nodes, edges: previous.edges },
        history: { past: state.history.past.slice(0, -1), future: [...state.history.future, graphSnapshotOf(state)] },
      }
      // 撤销后是否「未保存」取决于是否回到已保存快照，
      // 而非一律 true——连续撤销回初始保存状态时不应再弹未保存确认。
      // canvas 变化后校验选中/编辑器引用存在性。
      return { ...next, ...sanitizeSelectionAfterCanvas(next), dirty: !graphSnapshotsEqual(next.canvas, state.savedGraph) }
    }
    case 'REDO': {
      const next = state.history.future.at(-1)
      if (!next) return state
      const applied: StudioState = {
        ...state,
        canvas: { nodes: next.nodes, edges: next.edges },
        history: { past: [...state.history.past, graphSnapshotOf(state)], future: state.history.future.slice(0, -1) },
      }
      // 同 UNDO：重做后同样按「是否回到已保存状态」判定与
      // 选中/编辑器校验。
      return { ...applied, ...sanitizeSelectionAfterCanvas(applied), dirty: !graphSnapshotsEqual(applied.canvas, state.savedGraph) }
    }
    case 'PANELS_SET':
      return { ...state, panels: { ...state.panels, ...action.panels } }
    case 'CONFIRM_SET':
      return { ...state, confirm: action.confirm }
    case 'HISTORY_OPEN':
      return { ...state, historyOpen: action.open }
    case 'RUN_HISTORY_LOADED':
      return { ...state, runHistory: action.items, selectedRunId: action.items[0]?.id ?? state.selectedRunId }
    case 'RUN_HISTORY_SELECT':
      return { ...state, selectedRunId: action.id }
    case 'COMBO_OPEN':
      return { ...state, comboOpen: action.open }
    case 'SCHEDULER_OPEN':
      return { ...state, schedulerOpen: action.open }
    default:
      return state
  }
}

/**
 * 画布变化后的选中/编辑器校验：UNDO/REDO 恢复画布后，selection 与
 * editor 可能仍指向已不存在的节点/连线（如 REDO 一个删除操作后选中残留），
 * 返回清理后的 selection/editor —— 引用失效的项置空，避免键盘删除误删与
 * Inspector 渲染空数据。
 */
function sanitizeSelectionAfterCanvas(state: StudioState): Pick<StudioState, 'selection' | 'editor'> {
  const nodeExists = (id: string | null | undefined): boolean => id != null && state.canvas.nodes.some((node) => node.id === id)
  const edgeExists = (id: string | null | undefined): boolean => id != null && state.canvas.edges.some((edge) => edge.id === id)
  const selection: StudioState['selection'] = {
    nodeId: nodeExists(state.selection.nodeId) ? state.selection.nodeId : null,
    edgeId: edgeExists(state.selection.edgeId) ? state.selection.edgeId : null,
    lib: state.selection.lib,
  }
  let editor = state.editor
  if (editor) {
    if (editor.source === 'node' && !nodeExists(editor.id)) editor = null
    else if (editor.source === 'edge' && !edgeExists(editor.id)) editor = null
  }
  return { selection, editor }
}
