// src/client/components/sidebar/NodePalette.tsx

import { useState } from 'react'
import type { Dict } from '../../i18n.js'
import type { CanvasNode } from '../../lib/canvas-model.js'
import type { NodeKind } from '../../../host/shared/graph-model.js'
import type { DragPayload } from './LeftPanel.js'

export function NodePalette({ copy, nodes, kinds, references = false, query = '', disabled, onPlace, onBeginDrag }: {
  copy: Dict; nodes: CanvasNode[]; kinds: NodeKind[]; references?: boolean; query?: string; disabled: boolean
  onPlace(kind: NodeKind, position?: { x: number; y: number }, sourceId?: string): void
  onBeginDrag(event: React.PointerEvent, payload: DragPayload): void
}) {
  const [referencesOpen, setReferencesOpen] = useState(false)
  const roles = nodes.filter(node => node.kind === 'agent' || node.kind === 'parent')
  const matches = (label: string): boolean => label.toLowerCase().includes(query.trim().toLowerCase())
  return <div className="wf-node-palette">
      {kinds.filter(kind => matches(copy.nodeKinds[kind])).map(kind => <button key={kind} type="button" className="wf-docitem" data-basic-node-kind={kind} title={copy.addCardsHint} disabled={disabled || (kind === 'parent' || kind === 'start') && nodes.some(node => node.kind === kind)}
        onClick={event => { if (event.detail === 0) onPlace(kind) }}
        onPointerDown={event => onBeginDrag(event, { label: copy.nodeKinds[kind], onClick: () => onPlace(kind), onDrop: position => onPlace(kind, position) })}>{copy.nodeKinds[kind]}</button>)}
      {references && (matches(copy.nodeReference) || roles.some(node => matches(String(node.data.label || node.id)))) ? <button type="button" className="wf-docitem" disabled={disabled || !roles.length} title={!roles.length ? copy.referenceRequiresRole : copy.nodeReference} aria-expanded={referencesOpen} onClick={() => setReferencesOpen(!referencesOpen)}>{copy.nodeReference}</button> : null}
    {references && referencesOpen ? <ul className="wf-node-palette__references" aria-label={copy.referenceSource}>
      {roles.filter(node => matches(copy.nodeReference) || matches(String(node.data.label || node.id))).map(node => <li key={node.id}>
        <button type="button" title={String(node.data.label || node.id)} data-reference-id={node.id}
          onClick={event => { if (event.detail === 0) { onPlace('proxy', undefined, node.id); setReferencesOpen(false) } }}
          onPointerDown={event => onBeginDrag(event, { label: String(node.data.label || node.id), onClick: () => { onPlace('proxy', undefined, node.id); setReferencesOpen(false) }, onDrop: position => { onPlace('proxy', position, node.id); setReferencesOpen(false) } })}>{String(node.data.label || node.id)}</button>
      </li>)}
    </ul> : null}
  </div>
}
