// src/client/studio/WorkbenchHost.tsx
//
// 工作台宿主：承载官方右侧 Sidebar 标签页内的**常驻容器**（Studio 因此永不卸载），
// 并解析会话、渲染 Studio、提供运行联动的沉浸式回调。呈现与打开方式全部交给官方
// Sidebar：
//   - 呈现：官方 sidebar.right.pane.tab 插槽内承载本宿主的常驻容器（见
//     sidebar/workbench-tab.tsx 的挂载点注册表），Studio 因此永不卸载；
//   - 打开：官方 sidebar.footer.action 插槽的入口按钮 → ctx.sidebarRight.openTab(kind)
//     （见 sidebar/footer-entry.tsx）。
//
// 本组件职责：
//   ① 解析「当前主会话」（会话树根）并跟随官方 sessions 快照变化 —— 供实例列表「当前」标签、
//      实例创建目标会话、运行轮询会话判定使用（工作台**不按会话隔离**，列表是全部会话的集合）；
//   ② 渲染 <Studio>；
//   ③ 提供运行联动的沉浸式回调（官方右侧 Sidebar 若处于全屏则缩回普通态；非全屏保持原状）。

import { useEffect, useMemo, useState } from 'react'
import { Studio } from './Studio.js'
import { detectLanguage, type Dict } from '../i18n.js'
import { currentSessionOf, rootSessionIdOf, type SessionsServiceLike } from '../sidebar/session-root.js'
import { shrinkOfficialSidebarIfFullscreen } from '../sidebar/workbench-tab.js'
import { createWorkspacePicker } from '../sidebar/workspace-picker.js'
import { createFilePathResolver } from '../sidebar/host-paths.js'
import type { InstanceNavigation } from '../sidebar/instance-navigation.js'

// 会话解析缝继续 re-export（历史导入路径不变；实现已迁至 sidebar/session-root.ts）。
export { currentSessionOf, rootSessionIdOf }

/** 宿主上下文（兼容官方 client 注入的 ctx 最小形状）。 */
export interface WorkbenchHostContext {
  get?(name: string): unknown
  effect?(fn: () => (() => void) | void, label?: string): unknown
  locale?: unknown
}

/** 解析当前会话树根（守卫式读取；服务缺失返回空串）。 */
function rootSessionOf(ctx: WorkbenchHostContext): string {
  return rootSessionIdOf(currentSessionOf(ctx), ctx.get?.('sessions') as SessionsServiceLike | null | undefined)
}

/**
 * 工作台宿主组件。
 * @param ctx - 官方 client 上下文（读取 sessions 快照、组装官方目录选择器接入缝）。
 * @param t - 文案词典（语言切换时由 entry.ts 重渲染传入）。
 */
export function WorkbenchHost({ ctx, t }: { ctx: WorkbenchHostContext; t: Dict }) {
  const navigation = ctx.get?.('visualWorkflowNavigation') as InstanceNavigation | undefined
  const [previewRequest, setPreviewRequest] = useState(() => navigation?.pending() ?? null)
  useEffect(() => {
    const off = navigation?.subscribe(() => setPreviewRequest(navigation.pending()))
    setPreviewRequest(navigation?.pending() ?? null)
    return off
  }, [navigation])
  const [sessionId, setSessionId] = useState(() => rootSessionOf(ctx))
  // 官方目录选择器接入缝（preload 原生接口优先，回退 uiWorkspace.pickDirectory）。
  const workspacePicker = useMemo(() => createWorkspacePicker(ctx), [ctx])
  // 官方桌面文件路径桥接入缝（「选择文件」写入任务描述的绝对路径）。
  const filePathResolver = useMemo(() => createFilePathResolver(), [])
  // 官方 uiWorkspace 服务可能晚于本插件激活：挂载后补一次重渲染，让按钮可用性刷新。
  const [, setTick] = useState(0)
  useEffect(() => {
    const timer = setTimeout(() => { setTick((value) => value + 1) }, 0)
    return () => { clearTimeout(timer) }
  }, [])

  // 会话变化时跟随（仅更新「当前」标签与新建实例的目标会话，不重置界面）
  useEffect(() => {
    const sessions = ctx.get?.('sessions') as SessionsServiceLike | null | undefined
    const off = sessions?.list?.subscribe?.(() => {
      setSessionId(rootSessionOf(ctx))
    })
    return () => {
      off?.()
    }
  }, [ctx])

  const directoryEditor = ctx.get?.('sessionDirectoryEditor') as { edit?(id: string): void } | undefined
  return <Studio previewRequest={previewRequest} instanceNavigation={navigation} language={detectLanguage(ctx.get?.('locale') ?? ctx.locale)} t={t} sessionId={sessionId} onRunImmersive={shrinkOfficialSidebarIfFullscreen} workspacePicker={workspacePicker} filePathResolver={filePathResolver} onEditSessionDirectory={typeof directoryEditor?.edit === 'function' ? (id) => {
    const current = ctx.get?.('sessionDirectoryEditor') as { edit?(id: string): void } | undefined
    current?.edit?.(id)
  } : undefined} />
}
