// src/client/lib/graph-run-focus.ts

import type { CanvasEdge, CanvasNode } from './canvas-model.js'

/** Active references share one execution unit; an active member lights its container, never idle siblings. */
export function workingGraphNodeIds(nodes: CanvasNode[], runningIds: readonly string[]): Set<string> {
  const byId = new Map(nodes.map(node => [node.id, node]))
  const references = new Map<string, string[]>()
  const link = (from: string, to: string): void => {
    const adjacent = references.get(from)
    if (adjacent) adjacent.push(to)
    else references.set(from, [to])
  }
  for (const node of nodes) {
    if (node.kind !== 'proxy' || !node.proxySourceId || !byId.has(node.proxySourceId)) continue
    link(node.id, node.proxySourceId); link(node.proxySourceId, node.id)
  }
  const pending = runningIds.filter(id => byId.has(id)), active = new Set<string>()
  for (let i = 0; i < pending.length; i++) {
    const id = pending[i]
    if (active.has(id)) continue
    active.add(id); pending.push(...references.get(id) ?? [])
  }
  for (const node of nodes) {
    if (active.has(node.id) && typeof node.data.groupId === 'string' && byId.has(node.data.groupId)) active.add(node.data.groupId)
    if (node.kind === 'group' && ((node.data.memberIds as string[] | undefined) ?? []).some(id => active.has(id))) active.add(node.id)
  }
  return active
}

/** Flow animation follows work entering the active step; context/data may operate in either direction. */
export function isWorkingEdge(edge: CanvasEdge, activeIds: ReadonlySet<string> | undefined): boolean {
  if (!activeIds) return false
  if (activeIds.has(edge.target)) return true
  const context = edge.sourceHandle === 'ctx-out' || edge.targetHandle === 'ctx-in'
    || edge.sourceHandle === 'db-out' || edge.targetHandle === 'db-in'
  return context && activeIds.has(edge.source)
}
