// src/client/lib/auto-layout-graph.ts

import type { ProxyNode } from '../../host/shared/graph-model.js'
import type { CanvasEdge, CanvasNode } from './canvas-model.js'
import { compactLayout } from './compact-layout.js'
import { groupCardSizeOf } from './card-geometry.js'
import { layoutBoxesOf } from './layout-fit.js'
import type { LayoutBox } from './layout-fit.js'

export interface AutoLayoutGraphOptions { autoReferences?: boolean }
type Provenance = NonNullable<NonNullable<ProxyNode['data']>['autoLayoutReference']>

/** Rebuild only untouched generated references. User references and manually extended cards remain intact. */
export function removeLayoutReferences(nodes: CanvasNode[], edges: CanvasEdge[]): { nodes: CanvasNode[]; edges: CanvasEdge[] } {
  const byId = new Map(nodes.map(node => [node.id, node])), removed = new Map<string, Provenance>()
  for (const node of nodes) {
    const marker = node.data?.autoLayoutReference as Provenance | undefined
    if (node.kind !== 'proxy' || !marker || !['source', 'target'].includes(marker.endpoint) || !byId.has(marker.originalId)) continue
    const incident = edges.filter(edge => edge.source === node.id || edge.target === node.id)
    if (!incident.length || (incident.length === 1 && incident[0].id === marker.edgeId && incident[0][marker.endpoint] === node.id)) removed.set(node.id, marker)
  }
  const originalIdOf = (id: string): string => {
    let originalId = id
    const seen = new Set<string>()
    while (removed.has(originalId)) {
      // A user may have connected an automatic alias to another alias before requesting a new layout.
      if (seen.has(originalId)) return byId.get(id)?.proxySourceId ?? id
      seen.add(originalId); originalId = removed.get(originalId)!.originalId
    }
    return originalId
  }
  return {
    nodes: nodes.filter(node => !removed.has(node.id)),
    edges: edges.map(edge => ({ ...edge, source: originalIdOf(edge.source), target: originalIdOf(edge.target) })),
  }
}

function verticalSlot(id: string, x: number, y: number, w: number, h: number, boxes: LayoutBox[]): { x: number; y: number } {
  const gap = 44
  const neighbors = boxes.filter(box => x < box.x + box.w + gap && x + w + gap > box.x)
  const candidates = [y, ...neighbors.flatMap(box => [box.y - h - gap, box.y + box.h + gap])]
  candidates.sort((a, b) => Math.abs(a - y) - Math.abs(b - y) || a - b)
  const top = candidates.find(top => neighbors.every(box => box.id === id || top + h + gap <= box.y || top >= box.y + box.h + gap)) ?? y
  return { x, y: top }
}

/** Horizontal phase layout, optionally substituting local role aliases for long return/cross-phase edges. */
export function autoLayoutGraph(nodes: CanvasNode[], edges: CanvasEdge[], options: AutoLayoutGraphOptions = {}): { nodes: CanvasNode[]; edges: CanvasEdge[] } {
  const original = removeLayoutReferences(nodes, edges)
  const placed = compactLayout(original.nodes, original.edges)
  const nextNodes = [...placed], byId = new Map(placed.map(node => [node.id, node]))
  const groups = new Map<string, CanvasNode>()
  for (const node of placed) if (node.kind === 'group') for (const id of (node.data.memberIds as string[] | undefined) ?? []) groups.set(id, node)
  const boxes = layoutBoxesOf(placed, groupCardSizeOf)
  const roleOf = (id: string): CanvasNode | undefined => {
    const node = byId.get(id), main = node?.kind === 'proxy' ? byId.get(node.proxySourceId ?? '') : node
    return main?.kind === 'agent' || main?.kind === 'parent' ? main : undefined
  }
  const nextEdges = original.edges.map(edge => {
    let next = edge.appearance ? { ...edge, appearance: { ...edge.appearance, waypoints: [], anchorMode: 'auto' as const, sourceSide: undefined, targetSide: undefined } } : { ...edge }
    if (!options.autoReferences) return next
    const source = groups.get(edge.source) ?? byId.get(edge.source), target = groups.get(edge.target) ?? byId.get(edge.target)
    if (!source || !target || source.id === target.id) return next
    const sourceSize = groupCardSizeOf(source), targetSize = groupCardSizeOf(target)
    const dx = target.position.x - source.position.x, dy = Math.abs(target.position.y - source.position.y)
    const isLong = dx < -64 || dx > 1100 || (Math.abs(dx) < 64 && dy > 440)
    if (!isLong) return next
    // A proxy can reference roles, never a Team container or data source. Fall back to the other endpoint.
    const targetRole = roleOf(edge.target), sourceRole = roleOf(edge.source)
    const endpoint = targetRole ? 'target' : sourceRole ? 'source' : null
    const main = endpoint === 'target' ? targetRole : sourceRole
    if (!endpoint || !main) return next
    const originalId = edge[endpoint], originalNode = byId.get(originalId)!
    const stem = `auto-ref-${edge.id}-${endpoint}`
    let id = stem, suffix = 1
    while (byId.has(id)) id = `${stem}-${suffix++}`
    const reference: CanvasNode = {
      id, kind: 'proxy', proxySourceId: main.id, position: { x: 0, y: 0 },
      data: { label: String(originalNode.data?.label ?? main.data?.label ?? main.id), autoLayoutReference: { edgeId: edge.id, endpoint, originalId } satisfies Provenance },
    }
    const size = groupCardSizeOf(reference)
    const x = endpoint === 'target' ? source.position.x + sourceSize.w + 128 : target.position.x - size.w - 128
    const y = endpoint === 'target' ? source.position.y + (sourceSize.h - size.h) / 2 : target.position.y + (targetSize.h - size.h) / 2
    reference.position = verticalSlot(id, x, y, size.w, size.h, boxes)
    boxes.push({ id, ...reference.position, ...size }); byId.set(id, reference); nextNodes.push(reference)
    next = { ...next, [endpoint]: id }
    return next
  })
  const added = nextNodes.length > placed.length
  const offsetX = added ? Math.max(0, 70 - Math.min(...nextNodes.map(node => node.position.x))) : 0
  const offsetY = added ? Math.max(0, 60 - Math.min(...nextNodes.map(node => node.position.y))) : 0
  return { nodes: offsetX || offsetY ? nextNodes.map(node => ({ ...node, position: { x: node.position.x + offsetX, y: node.position.y + offsetY } })) : nextNodes, edges: nextEdges }
}
