// src/client/components/canvas/GraphCanvas.tsx
//
// 自研 SVG 画布。
// 节点为绝对定位 HTML 卡片，角色卡四侧端口居中，按连线用途选择语义通道。
// SVG 支持多锚点曲线与圆角折线、拖拽、平移、缩放、条件标签和运行态高亮。
// Team 卡片渲染成员迷你列表（组内成员节点以迷你形态叠加于组内），并提供 ctx-in 团队任务入点。
//
// 职责拆分（本文件 = 交互编排 + 组装）：
//   - 视口（平移/缩放/适配/坐标换算）：./use-canvas-viewport.ts
//   - 连线层渲染：./CanvasEdges.tsx
//   - 节点卡片：./FlowNode.tsx、./GroupCard.tsx

import { useCallback, useEffect, useMemo, useState, useRef } from 'react'
import { useEdgeRoutes } from './use-edge-routes.js'
import type { LineAppearance, PortSide } from '../../../host/shared/graph-model.js'
import type { Dict } from '../../i18n.js'
import type { CanvasEdge, CanvasNode } from '../../studio/studio-state.js'
import { memberLabelOf } from '../../studio/studio-selectors.js'
import { nodeSizeOf } from '../../lib/card-geometry.js'
import { connectionTargetAt, groupSurfaceUnderPoint } from '../../lib/dom-hit-test.js'
import { FlowNode } from './FlowNode.js'
import { GroupCard } from './GroupCard.js'
import { CanvasEdges } from './CanvasEdges.js'
import { workingGraphNodeIds } from '../../lib/graph-run-focus.js'
import { NodeEditToolbar } from './NodeEditToolbar.js'
import { connectPorts, type ConnectionPort, type ConnectionChannel } from '../../lib/manual-connection.js'
import { HANDLES } from '../../lib/graph-handles.js'
import { EdgeEditToolbar } from './EdgeEditToolbar.js'
import { useCanvasViewport } from './use-canvas-viewport.js'
import { memberGroupIndexOf } from './geometry.js'
import { edgeSegmentDrag, translateEdgeSegment } from '../../lib/edge-segment.js'
import type { SegmentDrag } from '../../lib/edge-segment.js'
import type { RoutePoint } from '../../lib/orthogonal-routing.js'

export type { CanvasApi } from './use-canvas-viewport.js'

export interface GraphCanvasProps {
  /** Explicit route optimization on fixed card positions; never part of the saved workflow. */
  routingRevision?: number
  nodes: CanvasNode[]
  edges: CanvasEdge[]
  copy: Dict & { modeName(id: string | null | undefined): string }
  mode: 'mode1' | 'mode2'
  selectedNode: string | null
  selectedEdge: string | null
  runStatusByNode: Record<string, { status: string; attempts: number; outputSummary: string }>
  highlightedNodeIds: string[]
  /** Running the displayed document: execution focus takes priority over selection emphasis. */
  runtimeFocus?: boolean
  /**
   * 运行中锁定项（已完成流程不可变更；模式一 running 时由 run-locks 计算）：
   * 节点显示锁角标、被锁连线渲染为灰化虚线，点击不选中（属性栏不展开）。
   */
  lockedNodeIds?: ReadonlySet<string>
  lockedEdgeIds?: ReadonlySet<string>
  /** P4：最近一次父代理补丁（origin='agent'）改动的节点 id → 显示「AI 调整」角标。 */
  agentPatchedNodeIds?: string[]
  onInit(api: import('./use-canvas-viewport.js').CanvasApi): void
  onNodeDragStart(): void
  onNodeMove(id: string, position: { x: number; y: number }): void
  /** 角色节点拖入 Team。 */
  onNodeDropToGroup(nodeId: string, groupId: string): void
  onNodeSelect(id: string): void
  onEdgeSelect(id: string): void
  onPaneClick(): void
  onConnect(connection: { source: string; target: string; sourceHandle: string; targetHandle: string; appearance?: LineAppearance }): void
  onEdgeEditStart?(): void
  onEdgeAppearanceChange?(id: string, patch: LineAppearance): void
  onNodeDuplicate?(): void
  onNodeReference?(): void
  onNodeDelete?(id: string): void
  onEdgeDelete?(id: string): void
  /** 子图节点展开：打开全屏预览。 */
  onOpenSubgraph?(id: string): void
  /** 只读画布（子图预览）：禁用拖拽/连线/编辑工具栏，只保留平移缩放与 fit。 */
  readOnly?: boolean
  onConnectionRejected(): void
  onGroupResize(id: string, size: { w: number; h: number }): void
  /** 交换节点左右连接点（用户批注：美化布线防交叉）。 */
  onSwapPorts(id: string): void
  /** 左栏拖拽悬停的 Team id（Team 卡片高亮 + 「放开以入组」提示）。 */
  dropTargetGroupId?: string | null
  fitLabel: string
  zoomInLabel: string
  zoomOutLabel: string
  emptyHint: string
  /** 画布左上角工作流名称角标（实例/模板 + 名称）。 */
  workflowCaption?: string
  documentKey?: string
}

export function GraphCanvas(props: GraphCanvasProps) {
  const {
    nodes, edges, copy, mode, selectedNode, selectedEdge, runStatusByNode, highlightedNodeIds,
    onInit, onNodeDragStart, onNodeMove, onNodeDropToGroup, onNodeSelect, onEdgeSelect, onPaneClick,
    onConnect, onConnectionRejected, onGroupResize, onEdgeEditStart, onEdgeAppearanceChange, dropTargetGroupId, fitLabel, zoomInLabel, zoomOutLabel, emptyHint, workflowCaption,
    lockedNodeIds, lockedEdgeIds, agentPatchedNodeIds, onOpenSubgraph, readOnly = false, runtimeFocus = false,
  } = props
  const { rootRef, viewport, viewportRef, fitView, panning, beginPan, zoomBy, screenToWorld } = useCanvasViewport(nodes, onInit)
  const [draggingNode, setDraggingNode] = useState<{ nodeId: string; startClientX: number; startClientY: number; originX: number; originY: number } | null>(null)
  const nodeDragMoved = useRef(false)
  /** 画布内节点拖拽时悬停的 Team id（Team 卡片高亮 + 「放开以入组」提示）。 */
  const [dragHoverGroupId, setDragHoverGroupId] = useState<string | null>(null)
  const [connectionDraft, setConnectionDraft] = useState<{ port: ConnectionPort; originX: number; originY: number; clientX: number; clientY: number; start: { x: number; y: number } } | null>(null)
  const connectionRef = useRef(connectionDraft)
  connectionRef.current = connectionDraft
  const [drawingChannel, setDrawingChannel] = useState<ConnectionChannel>('flow')
  const drawingChannelRef = useRef(drawingChannel); drawingChannelRef.current = drawingChannel
  const connectionCallbacks = useRef({ onConnect, onConnectionRejected })
  connectionCallbacks.current = { onConnect, onConnectionRejected }
  const [nodeToolbarHidden, setNodeToolbarHidden] = useState(false)
  useEffect(() => { setNodeToolbarHidden(false) }, [selectedNode])
  useEffect(() => { connectionRef.current = null; setConnectionDraft(null) }, [props.documentKey])
  const byId = useMemo(() => new Map(nodes.map((node) => [node.id, node])), [nodes])
  const byIdRef = useRef(byId)
  byIdRef.current = byId
  const selectionCallbacks = useRef({ onNodeSelect, onNodeDragStart })
  selectionCallbacks.current = { onNodeSelect, onNodeDragStart }
  const selectMember = useCallback((id: string): void => selectionCallbacks.current.onNodeSelect(id), [])
  const highlightedSet = useMemo(() => workingGraphNodeIds(nodes, highlightedNodeIds), [nodes, highlightedNodeIds])
  /**
   * 成员 id → 所属组 预建索引：连线几何逐边反查所属组，若每次全节点扫描则是 O(边×节点)。
   * 与 byId 同生命周期（节点集不变即复用），草稿线方向判定同样走它。
   */
  const memberGroups = useMemo(() => memberGroupIndexOf(byId), [byId])
  const { routes: edgeRoutes, connectedPorts, isRouting } = useEdgeRoutes(edges, byId, memberGroups, { pass: copy.lineTypePass, fail: copy.lineTypeFail, content: copy.lineTypeContent }, props.documentKey, !!draggingNode && nodeDragMoved.current, props.routingRevision)
  const portConnections = useMemo(() => {
    const map = new Map<string, string>()
    for (const key of connectedPorts) {
      const separator = key.lastIndexOf(':', key.lastIndexOf(':') - 1), id = key.slice(0, separator)
      map.set(id, (map.get(id) ?? '') + `|${key}|`)
    }
    return map
  }, [connectedPorts])
  const [edgeDrag, setEdgeDrag] = useState<{ id: string; index: number; clientX: number; clientY: number; origin: { x: number; y: number }; segment?: SegmentDrag; waypoints: Array<{ x: number; y: number }> } | null>(null)
  const editRef = useRef({ onEdgeEditStart, onEdgeAppearanceChange })
  editRef.current = { onEdgeEditStart, onEdgeAppearanceChange }
  const [anchorMenu, setAnchorMenu] = useState<{ id: string; index: number; anchors: RoutePoint[]; x: number; y: number } | null>(null)
  const [toolbarHidden, setToolbarHidden] = useState(false)
  useEffect(() => { setToolbarHidden(false) }, [selectedEdge])
  const removeAnchor = useCallback((id: string, index: number, anchors: RoutePoint[]): void => {
    editRef.current.onEdgeEditStart?.()
    editRef.current.onEdgeAppearanceChange?.(id, { waypoints: anchors.filter((_, i) => i !== index), anchorMode: 'manual' })
    setAnchorMenu(null)
  }, [])
  const anchorContext = useCallback((event: React.MouseEvent, id: string, index: number, anchors: RoutePoint[]): void => {
    const rect = rootRef.current?.getBoundingClientRect()
    if (rect) setAnchorMenu({ id, index, anchors, x: Math.max(8, Math.min(rect.width - 140, event.clientX - rect.left)), y: Math.max(8, Math.min(rect.height - 44, event.clientY - rect.top)) })
  }, [rootRef])
  const beginEdgeDrag = useCallback((event: React.PointerEvent, id: string, waypointIndex?: number, segmentIndex?: number, curveAnchors?: RoutePoint[]): void => {
    if (readOnly) return
    if (event.button !== 0 || lockedEdgeIds?.has(id)) return
    event.stopPropagation()
    const edge = edges.find(e => e.id === id)
    if (!edge) return
    const segment = segmentIndex === undefined ? null : edgeSegmentDrag(edgeRoutes.get(id)?.points ?? [], segmentIndex)
    if (segmentIndex !== undefined && !segment) return
    const waypoints = segment?.waypoints ?? curveAnchors?.map(p => ({ ...p })) ?? edge.appearance?.waypoints?.map(p => ({ ...p })) ?? []
    const point = screenToWorld(event.clientX, event.clientY)
    let index = waypointIndex ?? 0
    if (waypointIndex === undefined && waypoints.length) index = waypoints.reduce((best, p, i) => Math.hypot(p.x - point.x, p.y - point.y) < Math.hypot(waypoints[best].x - point.x, waypoints[best].y - point.y) ? i : best, 0)
    setEdgeDrag({ id, index, origin: point, ...(segment ? { segment } : {}), clientX: event.clientX, clientY: event.clientY, waypoints })
  }, [edges, edgeRoutes, lockedEdgeIds, screenToWorld])
  useEffect(() => {
    if (!edgeDrag) return
    let changed = false, frame = 0, pending: PointerEvent | null = null
    const apply = (): void => {
      frame = 0
      if (!pending) return
      const event = pending; pending = null
      if (!changed && Math.hypot(event.clientX - edgeDrag.clientX, event.clientY - edgeDrag.clientY) < 4) return
      if (!changed) { changed = true; editRef.current.onEdgeEditStart?.() }
      const point = screenToWorld(event.clientX, event.clientY), waypoints = edgeDrag.waypoints.map(p => ({ ...p }))
      if (edgeDrag.segment) {
        editRef.current.onEdgeAppearanceChange?.(edgeDrag.id, { waypoints: translateEdgeSegment(edgeDrag.segment, { x: point.x - edgeDrag.origin.x, y: point.y - edgeDrag.origin.y }), anchorMode: 'manual' })
      } else {
        waypoints[edgeDrag.index] = { x: Math.round(point.x), y: Math.round(point.y) }
        editRef.current.onEdgeAppearanceChange?.(edgeDrag.id, { waypoints, anchorMode: 'manual' })
      }
    }
    const move = (event: PointerEvent): void => { pending = event; if (!frame) frame = requestAnimationFrame(apply) }
    const stop = (): void => { if (frame) cancelAnimationFrame(frame); apply(); setEdgeDrag(null) }
    window.addEventListener('pointermove', move); window.addEventListener('pointerup', stop); window.addEventListener('pointercancel', stop); window.addEventListener('blur', stop)
    return () => { if (frame) cancelAnimationFrame(frame); window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', stop); window.removeEventListener('pointercancel', stop); window.removeEventListener('blur', stop) }
  }, [edgeDrag, screenToWorld])
  // 以下判定函数以 useCallback 固定引用：它们是子组件（memo）的 props，引用漂移会让 memo 失效
  const runStatusOf = useCallback((id: string): { status: string; attempts: number; outputSummary: string } | null => runStatusByNode[id] ?? null, [runStatusByNode])
  /** 锁定判定（未传入视为全解锁）：节点锁角标、连线灰化虚线、点击不选中。 */
  const isLockedNode = useCallback((id: string): boolean => lockedNodeIds?.has(id) === true, [lockedNodeIds])
  // P4：父代理补丁改动标记（数组 → Set，渲染期 O(1) 判定）
  const agentPatchedSet = useMemo(() => new Set(agentPatchedNodeIds ?? []), [agentPatchedNodeIds])
  const isLockedEdge = useCallback((id: string): boolean => lockedEdgeIds?.has(id) === true, [lockedEdgeIds])
  /** 节点锁悬停文案（已完成/执行中语义不同，取自词典）。 */
  const nodeLockHint = useCallback((id: string): string => (runStatusOf(id)?.status === 'running'
    ? String(copy.lockedRunningNodeHint)
    : String(copy.lockedCompletedNodeHint)), [runStatusOf, copy.lockedRunningNodeHint, copy.lockedCompletedNodeHint])

  // ---- 节点拖拽 ----
  const beginNodeDrag = useCallback((event: React.PointerEvent, nodeId: string): void => {
    if (readOnly) return
    if (event.button !== undefined && event.button !== 0) return
    const target = event.target as HTMLElement
    if (target.closest?.('.wf-graph__handle')) return
    if (target.closest?.('.wf-group__resize')) return
    event.stopPropagation()
    const node = byIdRef.current.get(nodeId)
    if (!node) return
    selectionCallbacks.current.onNodeSelect?.(nodeId)
    nodeDragMoved.current = false
    setDragHoverGroupId(null)
    setDraggingNode({
      nodeId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      originX: node.position.x,
      originY: node.position.y,
    })
  }, [])

  useEffect(() => {
    if (!draggingNode) return undefined
    let frame = 0, pending: PointerEvent | null = null
    const applyMove = (event: PointerEvent): void => {
      if (!nodeDragMoved.current) {
        if (Math.hypot(event.clientX - draggingNode.startClientX, event.clientY - draggingNode.startClientY) < 4) return
        nodeDragMoved.current = true
        selectionCallbacks.current.onNodeDragStart?.()
      }
      const current = viewportRef.current
      const dx = (event.clientX - draggingNode.startClientX) / current.zoom
      const dy = (event.clientY - draggingNode.startClientY) / current.zoom
      onNodeMove?.(draggingNode.nodeId, {
        x: Math.round(draggingNode.originX + dx),
        y: Math.round(draggingNode.originY + dy),
      })
      // 悬停检测：仅「角色节点」拖到 Team 表面才高亮（排除被拖拽本体；连接点不具入组功能；
      // 角色以外的卡片（任务/数据库/阶段/虚拟）不显示悬浮提示、也不能入组，用户批注）
      const dragged = byId.get(draggingNode.nodeId)
      const canJoinGroup = !!dragged && (dragged.kind === 'parent' || dragged.kind === 'agent')
      setDragHoverGroupId(canJoinGroup ? groupSurfaceUnderPoint(event.clientX, event.clientY, draggingNode.nodeId) : null)
    }
    const onMove = (event: PointerEvent): void => {
      pending = event
      if (!frame) frame = requestAnimationFrame(() => { frame = 0; if (pending) { const event = pending; pending = null; applyMove(event) } })
    }
    const onUp = (event: PointerEvent): void => {
      if (frame) cancelAnimationFrame(frame)
      if (pending) { applyMove(pending); pending = null }
      // 拖入 Team：角色节点落在 Team 表面（不含连接点）时入组；被拖拽节点已排除，
      // 避免「节点覆盖在组上方」导致 elementFromPoint 命中自身而无法入组（用户批注）。
      const node = byId.get(draggingNode.nodeId)
      const groupId = groupSurfaceUnderPoint(event.clientX, event.clientY, draggingNode.nodeId)
      if (nodeDragMoved.current && node && (node.kind === 'parent' || node.kind === 'agent') && groupId && groupId !== node.id
        && !((node.data.groupId as string | null | undefined) ?? null)) {
        onNodeDropToGroup?.(node.id, groupId)
        setDraggingNode(null)
        setDragHoverGroupId(null)
        return
      }
      setDraggingNode(null)
      setDragHoverGroupId(null)
    }
    const onCancel = (): void => { if (frame) cancelAnimationFrame(frame); pending = null; setDraggingNode(null); setDragHoverGroupId(null) }
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
    window.addEventListener('pointercancel', onCancel)
    window.addEventListener('blur', onCancel)
    return () => {
      if (frame) cancelAnimationFrame(frame)
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
      window.removeEventListener('pointercancel', onCancel)
      window.removeEventListener('blur', onCancel)
    }
  }, [draggingNode, byId, onNodeMove, onNodeDropToGroup])

  // A gesture owns one ref from pointer-down to completion; moving cannot install duplicate listeners.
  const clearConnection = useCallback((): void => { connectionRef.current = null; setConnectionDraft(null) }, [])
  const portAt = useCallback((clientX: number, clientY: number): ConnectionPort | null => {
    const hit = document.elementFromPoint?.(clientX, clientY)
    const nodeId = connectionTargetAt(clientX, clientY)
    const node = nodeId ? byIdRef.current.get(nodeId) : null
    if (!node || !nodeId) return null
    const port = hit?.closest<HTMLElement>('[data-handle]')
    if (port) return { nodeId, handles: (port.dataset.handles ?? port.dataset.handle ?? '').split(' '), side: port.dataset.portSide as PortSide | undefined }
    const draft = connectionRef.current
    const reverse = draft?.port.handles.some(handle => handle.endsWith('-in'))
    const handles = HANDLES[node.kind]
    const available = reverse ? handles.outputs : handles.inputs
    return { nodeId, handles: available, side: reverse ? 'right' : 'left' }
  }, [])
  const finishConnection = useCallback((target: ConnectionPort): void => {
    const draft = connectionRef.current
    if (!draft) return
    const connection = connectPorts(draft.port, target, 'rounded', drawingChannelRef.current)
    clearConnection()
    if (connection) connectionCallbacks.current.onConnect(connection)
    else connectionCallbacks.current.onConnectionRejected()
  }, [clearConnection])
  const beginConnection = useCallback((event: React.PointerEvent, nodeId: string, handle: string): void => {
    if (readOnly) return
    if (event.button !== undefined && event.button !== 0) return
    event.preventDefault(); event.stopPropagation()
    const element = event.currentTarget as HTMLElement
    if (element.hasPointerCapture?.(event.pointerId)) element.releasePointerCapture(event.pointerId)
    const port: ConnectionPort = { nodeId, handles: (element.dataset.handles ?? handle).split(' '), side: element.dataset.portSide as PortSide | undefined }
    if (connectionRef.current) { finishConnection(port); return }
    const socket = element.getBoundingClientRect()
    const draft = { port, originX: event.clientX, originY: event.clientY, clientX: event.clientX, clientY: event.clientY, start: screenToWorld(socket.x + socket.width / 2, socket.y + socket.height / 2) }
    connectionRef.current = draft; setConnectionDraft(draft)
  }, [finishConnection, screenToWorld])
  const connecting = connectionDraft !== null
  useEffect(() => {
    if (!connecting) return
    const onMove = (event: PointerEvent): void => {
      const draft = connectionRef.current
      if (draft) { const next = { ...draft, clientX: event.clientX, clientY: event.clientY }; connectionRef.current = next; setConnectionDraft(next) }
    }
    const onUp = (event: PointerEvent): void => {
      const draft = connectionRef.current
      if (!draft) return
      const target = portAt(event.clientX, event.clientY)
      if (target && target.nodeId !== draft.port.nodeId) { finishConnection(target); return }
      if (Math.hypot(event.clientX - draft.originX, event.clientY - draft.originY) > 4) clearConnection()
    }
    const onKey = (event: KeyboardEvent): void => { if (event.key === 'Escape') { event.preventDefault(); clearConnection() } }
    window.addEventListener('pointermove', onMove); window.addEventListener('pointerup', onUp)
    window.addEventListener('pointercancel', clearConnection); window.addEventListener('blur', clearConnection); window.addEventListener('keydown', onKey)
    return () => { window.removeEventListener('pointermove', onMove); window.removeEventListener('pointerup', onUp); window.removeEventListener('pointercancel', clearConnection); window.removeEventListener('blur', clearConnection); window.removeEventListener('keydown', onKey) }
  }, [connecting, clearConnection, finishConnection, portAt])

  // ---- Team 拉伸 ----
  const [groupResize, setGroupResize] = useState<{ nodeId: string; startX: number; startY: number; startSize: { w: number; h: number } } | null>(null)
  const beginGroupResize = useCallback((event: React.PointerEvent, nodeId: string): void => {
    if (event.button !== undefined && event.button !== 0) return
    event.stopPropagation()
    const node = byIdRef.current.get(nodeId)
    if (!node) return
    // 只记录拖拽起点，不直接在回调里注册 window 监听：在 callback 内注册、仅 onUp 移除时，
    // 组件卸载/指针丢失时监听器
    // 残留并持续向已卸载组件回调）。监听与清理统一由下方 useEffect 管理。
    setGroupResize({
      nodeId,
      startX: event.clientX,
      startY: event.clientY,
      startSize: nodeSizeOf(node),
    })
  }, [])

  useEffect(() => {
    if (!groupResize) return undefined
    const onMove = (moveEvent: PointerEvent): void => {
      const dx = (moveEvent.clientX - groupResize.startX) / viewportRef.current.zoom
      const dy = (moveEvent.clientY - groupResize.startY) / viewportRef.current.zoom
      const nextW = Math.max(240, groupResize.startSize.w + dx)
      const nextH = Math.max(150, groupResize.startSize.h + dy)
      onGroupResize?.(groupResize.nodeId, { w: Math.round(nextW), h: Math.round(nextH) })
    }
    const onUp = (): void => setGroupResize(null)
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
    // 鼠标移出浏览器窗口/失焦时 pointerup 可能不触发，
    // pointercancel + blur 一并清理，避免监听器残留与 onGroupResize 空转。
    window.addEventListener('pointercancel', onUp)
    window.addEventListener('blur', onUp)
    return () => {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
      window.removeEventListener('pointercancel', onUp)
      window.removeEventListener('blur', onUp)
    }
  }, [groupResize, onGroupResize])

  // ---- 连线草稿路径（拖拽中） ----
  let draftPath: string | null = null
  if (connectionDraft) {
    const current = viewportRef.current
    const rect = rootRef.current?.getBoundingClientRect()
    const mouseWorld = rect
      ? { x: (connectionDraft.clientX - rect.left - current.x) / current.zoom, y: (connectionDraft.clientY - rect.top - current.y) / current.zoom }
      : connectionDraft.start
    // 草稿线起始控制点方向跟随源端口朝向（与 edgeGeometry 一致；仅出点可发起连线）。
    // 源为组内成员时出点固定在 Team 卡片右缘（+1）；交换节点出点在左缘（-1）；默认右缘（+1）。
    const bend = Math.max(54, Math.abs(mouseWorld.x - connectionDraft.start.x) * 0.46)
    const c1 = connectionDraft.port.side === 'bottom' ? { x: connectionDraft.start.x, y: connectionDraft.start.y + bend } : { x: connectionDraft.start.x + bend, y: connectionDraft.start.y }
    draftPath = `M ${connectionDraft.start.x} ${connectionDraft.start.y} C ${c1.x} ${c1.y}, ${mouseWorld.x - bend} ${mouseWorld.y}, ${mouseWorld.x} ${mouseWorld.y}`
  }

  const transform = `translate(${viewport.x}px, ${viewport.y}px) scale(${viewport.zoom})`
  const selectedLine = selectedEdge ? edges.find(e => e.id === selectedEdge) : null
  const selectedRoute = selectedEdge ? edgeRoutes.get(selectedEdge) : null

  // 派生容器全部 useMemo：拖拽/平移/缩放等本地渲染态重渲染时，节点集未变即不重建
  // （重建会让下游 memo 子组件的 props 引用漂移，memo 边界失效并触发每帧全量重算）。
  // 虚拟节点可显示阶段别名；未命名时回退主角色名称，执行配置仍只归主角色。
  const renderedNodes = useMemo<CanvasNode[]>(() => nodes.map((node) => {
    if (node.kind !== 'proxy') return node
    const sourceId = String(node.proxySourceId ?? '')
    const main = byId.get(sourceId)
    const alias = String(node.data.label ?? '').trim()
    return main ? { ...node, data: { ...node.data, label: alias || String((main.data as { label?: unknown }).label ?? ''), referencedRoleKind: main.kind } } : node
  }), [nodes, byId])
  const groupNodes = useMemo(() => nodes.filter((node) => node.kind === 'group'), [nodes])
  // 组内成员 id（以 group.data.memberIds 为准并对重复 id 去重；与右侧「团队成员」及删除逻辑一致）
  const memberIdsOf = useMemo(() => {
    const ids = new Set<string>()
    for (const group of groupNodes) {
      for (const memberId of [...new Set((group.data.memberIds as string[] | undefined) ?? [])]) ids.add(memberId)
    }
    return ids
  }, [groupNodes])
  // 组内成员仅在 Team 卡片内显示迷你卡（不在画布重复渲染大卡）
  const standalone = useMemo(
    () => renderedNodes.filter((node) => node.kind !== 'group' && !memberIdsOf.has(node.id)),
    [renderedNodes, memberIdsOf],
  )
  const groupMembers = useMemo(() => {
    const members = new Map<string, { id: string; label: string; status: string | null; locked: boolean }[]>()
    for (const group of groupNodes) {
      members.set(group.id, [...new Set((group.data.memberIds as string[] | undefined) ?? [])].map((memberId) => {
        const member = byId.get(memberId)
        return {
          id: memberId,
          // 成员显示名与属性栏共用同一回退规则（studio-selectors.memberLabelOf）
          label: memberLabelOf(member, memberId),
          status: runStatusOf(memberId)?.status ?? null,
          locked: isLockedNode(memberId),
          highlighted: runtimeFocus && highlightedSet.has(memberId),
          dimmed: runtimeFocus && !highlightedSet.has(memberId),
        }
      }))
    }
    return members
  }, [groupNodes, byId, runStatusOf, isLockedNode, runtimeFocus, highlightedSet])

  const actionNode = selectedNode ? byId.get(selectedNode) : undefined
  const actionAnchor = actionNode && (memberGroups.get(actionNode.id) ?? actionNode)
  const canReference = actionNode && ['agent', 'parent', 'proxy'].includes(actionNode.kind)

  return (
    <div className="wf-canvas-stage">
      <div
        className={`wf-canvas${panning ? ' is-panning' : ''}${connectionDraft ? ' is-connecting' : ''}${readOnly ? ' is-readonly' : ''}${runtimeFocus ? ' is-runtime-focused' : ''}`}
        data-connection-kind={connectionDraft?.port.handles[0]?.replace(/-(in|out)$/, '')}
        data-connection-direction={connectionDraft?.port.handles.some(handle => handle.endsWith('-in')) ? 'in' : 'out'}
        data-routing={isRouting ? 'pending' : 'ready'}
        ref={rootRef}
        onPointerDownCapture={event => { if (!(event.target as Element).closest?.('.wf-anchor-menu, .wf-node-toolbar')) setAnchorMenu(null) }}
        onPointerDown={(event) => { if (event.target === event.currentTarget) beginPan(event) }}
        onClick={(event) => { if (event.target === event.currentTarget) { clearConnection(); onPaneClick?.() } }}
      >
        <div className="wf-graph__stage" style={{ transform }}>
          <CanvasEdges
            nodes={nodes}
            edges={edges}
            byId={byId}
            memberGroups={memberGroups}
            selectedEdge={selectedEdge}
            selectedNode={selectedNode}
            routes={edgeRoutes}
            activeNodeIds={runtimeFocus ? highlightedSet : undefined}
            isLockedEdge={isLockedEdge}
            copy={copy}
            onEdgeSelect={onEdgeSelect}
            onEdgePointerDown={beginEdgeDrag}
            onAnchorRemove={removeAnchor}
            onAnchorContext={anchorContext}
            draftPath={draftPath}
          />
          {groupNodes.map((node) => (
            <GroupCard
              key={node.id}
              node={node}
              copy={copy}
              members={groupMembers.get(node.id) ?? []}
              connectedHandles={[node.id, ...((node.data.memberIds as string[] | undefined) ?? [])].map(id => portConnections.get(id) ?? '').join('')}
              selected={node.id === selectedNode}
              highlighted={highlightedSet.has(node.id)}
              dimmed={runtimeFocus && !highlightedSet.has(node.id)}
              dropTarget={dropTargetGroupId === node.id || dragHoverGroupId === node.id}
              locked={isLockedNode(node.id)}
              lockHint={nodeLockHint(node.id)}
              onPointerDown={beginNodeDrag}
              onHandlePointerDown={beginConnection}
              onMemberSelect={selectMember}
              onResizeStart={beginGroupResize}
            />
          ))}
          {standalone.map((node) => (
            <FlowNode
              key={node.id}
              node={node}
              copy={copy}
              connectedHandles={portConnections.get(node.id) ?? ''}
              mode={mode}
              selected={node.id === selectedNode}
              highlighted={highlightedSet.has(node.id)}
              dimmed={runtimeFocus && !highlightedSet.has(node.id)}
              dragging={draggingNode?.nodeId === node.id}
              // 用户批注：仅角色（agent/parent）节点显示/记录状态；阶段/任务/数据库/Team 卡片不渲染状态徽标。
              // parent 为编排执行单元（父代理节点），快照同样记录其状态，必须一并回显
              // （否则仅 parent 节点的工作流在画布上永远看不到节点运行状态）。
              runStatus={node.kind === 'agent' || node.kind === 'parent' ? runStatusOf(node.id) : null}
              locked={isLockedNode(node.id)}
              lockHint={nodeLockHint(node.id)}
              agentPatched={agentPatchedSet.has(node.id)}
              onPointerDown={beginNodeDrag}
              onHandlePointerDown={beginConnection}
              onOpenSubgraph={onOpenSubgraph}
            />
          ))}
          {/* 成员入线内段：Team 卡片背景在连线层之上，需单独抬到卡片之上、接点之下 */}
          <CanvasEdges
            layer="overlay"
            nodes={nodes}
            edges={edges}
            byId={byId}
            memberGroups={memberGroups}
            selectedEdge={selectedEdge}
            selectedNode={selectedNode}
            routes={edgeRoutes}
            activeNodeIds={runtimeFocus ? highlightedSet : undefined}
            isLockedEdge={isLockedEdge}
            copy={copy}
            onEdgeSelect={onEdgeSelect}
            draftPath={null}
          />
        </div>
        {workflowCaption ? <div className="wf-canvas-caption">{workflowCaption}</div> : null}
        {anchorMenu && selectedEdge === anchorMenu.id && !isLockedEdge(anchorMenu.id) ? <div className="wf-anchor-menu" role="menu" style={{ left: anchorMenu.x, top: anchorMenu.y }} onPointerDown={event => event.stopPropagation()} onKeyDown={event => { if (event.key === 'Escape') { event.stopPropagation(); setAnchorMenu(null) } }}>
          <button type="button" role="menuitem" autoFocus onClick={() => removeAnchor(anchorMenu.id, anchorMenu.index, anchorMenu.anchors)}>{copy.deleteAnchor}</button>
        </div> : null}
        {nodes.length === 0 ? (
          <div className="wf-canvas-empty">
            <div className="wf-canvas-empty__hint">
              <div className="wf-canvas-empty__icon">⬡</div>
              <div>{emptyHint}</div>
            </div>
          </div>
        ) : null}
      </div>
      {!readOnly && selectedLine && selectedRoute && !isLockedEdge(selectedLine.id) && !toolbarHidden && !edgeDrag ? <EdgeEditToolbar
        value={selectedLine.appearance ?? {}}
        x={Math.max(12, Math.min(viewport.x + selectedRoute.label.x * viewport.zoom - 140, (rootRef.current?.clientWidth ?? 800) - 360))}
        y={Math.max(12, viewport.y + Math.min(...selectedRoute.points.map(p => p.y)) * viewport.zoom - 100)}
        copy={copy}
        onChange={patch => { onEdgeEditStart?.(); onEdgeAppearanceChange?.(selectedLine.id, patch) }}
        onDelete={props.onEdgeDelete ? () => props.onEdgeDelete?.(selectedLine.id) : undefined}
        onClose={() => setToolbarHidden(true)}
      /> : null}
      {!readOnly && actionNode && actionAnchor && props.onNodeDuplicate && !nodeToolbarHidden && !draggingNode && !connectionDraft ? <NodeEditToolbar
        copy={copy} x={Math.max(12, Math.min(viewport.x + actionAnchor.position.x * viewport.zoom, (rootRef.current?.clientWidth ?? 800) - 270))}
        y={Math.max(56, Math.min(viewport.y + actionAnchor.position.y * viewport.zoom - 50, (rootRef.current?.clientHeight ?? 600) - 60))}
        canCopy={actionNode.kind !== 'parent' && actionNode.kind !== 'start'} canReference={!!canReference} locked={isLockedNode(actionNode.id)}
        onCopy={props.onNodeDuplicate} onReference={() => props.onNodeReference?.()} onDelete={() => props.onNodeDelete?.(actionNode.id)} onClose={() => setNodeToolbarHidden(true)} /> : null}
      {!readOnly ? <div className="wf-drawing-options" role="group" aria-label={copy.newConnectionType} onPointerDown={event => event.stopPropagation()}>
        <span>{copy.newConnectionType}</span>
        <button type="button" aria-pressed={drawingChannel === 'flow'} onClick={() => setDrawingChannel('flow')}>{copy.lineTypeFlow}</button>
        <button type="button" aria-pressed={drawingChannel === 'ctx'} onClick={() => setDrawingChannel('ctx')}>{copy.lineTypeContext}</button>
        <button type="button" aria-pressed={drawingChannel === 'db'} onClick={() => setDrawingChannel('db')}>{copy.lineTypeDatabase}</button>
        {connecting ? <small>{copy.drawingHint}</small> : null}
      </div> : null}
      <div className="wf-graph__controls">
        <button type="button" onClick={() => zoomBy(1.2)} title={zoomInLabel}>+</button>
        <button type="button" onClick={() => fitView()} title={fitLabel}>⛶</button>
        <button type="button" onClick={() => zoomBy(1 / 1.2)} title={zoomOutLabel}>−</button>
      </div>
      <div className="wf-graph__legend" aria-label={String(copy.graphLegend)}>
        {[
          ['', copy.lineTypeFlow],
          ['is-pass', copy.legendPass],
          ['is-content', copy.legendContent],
          ['is-fail', copy.legendFail],
          ['is-ctx', copy.lineTypeContext],
          ['is-db', copy.lineTypeDatabase],
        ].map(([kind, label]) => <span key={kind}>
          <svg viewBox="0 0 36 12" aria-hidden="true">
            <path className={`wf-legend-line ${kind}`} d="M 1 6 H 28" />
            <path className={`wf-arrow-head ${kind}`} d="M 28 2 L 35 6 L 28 10 Z" />
          </svg>
          {label}
        </span>)}
      </div>
    </div>
  )
}
